class _LineageRequestHandler(socketserver.StreamRequestHandler):
    server: "LineageServiceServer"

    def handle(self) -> None:
        request_id = ""
        try:
            request = json.loads(self.rfile.readline())
            if not isinstance(request, dict):
                raise ValueError("request envelope must be an object")
            request_id = str(request.get("id") or "")
            params = request.get("params")
            if not isinstance(params, dict):
                raise ValueError("request params must be an object")
            method = str(request.get("method") or "")
            actor = self.server.rpc_auth.authenticate(method, params, request.get("auth"))
            if method == "instruction.execute":
                self.server.serve_instruction(params, request_id, self._write_line, verified_caller=actor)
                return
            from management_common.authorization_context import authorization_scope, SubjectBinding

            raw_subject = params.get("_authorization")
            binding = SubjectBinding.from_dict(raw_subject) if raw_subject is not None else None
            if binding is not None and binding.context.principal_id != actor:
                raise PermissionError("Authorization subject must match the authenticated RPC actor")
            with authorization_scope(binding):
                result = self.server.dispatch(method, params)
            response = {"id": request_id, "ok": True, "result": _json_value(result)}
        except Exception as exc:
            response = {"id": request_id, "ok": False, "error": _error_payload(exc)}
        try:
            self.wfile.write(
                json.dumps(
                    response,
                    ensure_ascii=False,
                    separators=(",", ":"),
                ).encode("utf-8")
                + b"\n"
            )
        except (BrokenPipeError, ConnectionResetError):
            return

def serve_instruction(self, params: dict[str, Any], request_id: str, write_line: Any, *, verified_caller: str) -> None:
    """``instruction.execute`` (decision_96a887d83e8a); notifications follow the commit."""

    from management_portal.hatg.socket_rpc import serve

    if self.read_pool.workers and _is_read_instruction(params):
        try:
            write_line(self.read_pool.call_instruction(params, request_id, verified_caller))
        except (BrokenPipeError, ConnectionResetError):
            pass
        return
    with collect_changes() as changes:
        try:
            serve(params, request_id, write_line, owner="lineage", verified_caller=verified_caller)
        except (BrokenPipeError, ConnectionResetError):
            return
        finally:
            self._finish_changes(changes)

def _domain_call(self, params: dict[str, Any]) -> Any:
    from management_common.authorization_context import subject_payload

    params = {**params, "_authorization": params.get("_authorization") or subject_payload() or None}
    domain = str(params.get("domain") or "")
    method = str(params.get("name") or "")
    args = params.get("args")
    kwargs = params.get("kwargs")
    handler, bound = _bind_domain_call(domain, method, args, kwargs)
    operation = operation_contract(domain, method)
    if operation.mode == "read" and self.read_pool.workers and not operation.in_process:
        if (domain == "resident" and method == "list_resident_conversation_activity"
                and bound.arguments["page_size"] is not None):
            return self.conversation_index_pool.call(params)
        return self.read_pool.call(params)
    lineage_id = _operation_lineage_id(operation, bound)
    lineage_module = _domain_module("lineage")
    state_scope = lineage_module.lineage_state_scope(lineage_id, f"{domain}.{method}") if lineage_id else nullcontext()
    with collect_changes() as changes:
        try:
            with state_scope:
                return _invoke_domain(operation, handler, bound, domain, method)
        finally:
            self._finish_changes(changes)

def check_definition_version(connection: Any, lineage_id: str) -> None:
    """Check the first definition commit in this invocation, under its row lock.

    Remember the database transaction, not just a Python boolean: a failed
    transaction may be retried and must not consume the caller's precondition.
    """
    context = _PRECONDITIONS.get()
    if context is None or lineage_id not in context.expected:
        return
    previous = context.checked_transactions.get(lineage_id)
    if previous:
        transaction = connection.execute(
            "SELECT pg_current_xact_id()::text AS current_id, pg_xact_status(%s::xid8) AS status",
            (previous,),
        ).fetchone()
        if transaction["status"] == "committed":
            context.expected.pop(lineage_id)
            return
        if transaction["current_id"] == previous:
            return
    current = connection.execute(
        "SELECT revision, pg_current_xact_id()::text AS transaction_id FROM lineages "
        "WHERE lineage_id=%s AND deleted_at IS NULL FOR NO KEY UPDATE", (lineage_id,),
    ).fetchone()
    revision = int(current["revision"]) if current else 0
    expected = context.expected[lineage_id]
    if current is None or str(expected) != str(revision):
        raise InstructionError("instruction.conflict", "Lineage 定义已变化，请重新读取 GetLineage", details={
            "object_id": lineage_id, "expected_version": expected, "current_version": revision,
        })
    context.checked_transactions[lineage_id] = str(current["transaction_id"])

