def relayed_reply(facade: Mapping[str, Any], message_id: str) -> dict[str, Any] | None:
    """A member message shown in the facade Conversation: the request it answers, who took it, and the message.

    Every Agent message a member writes answering a relayed request shows,
    intermediate outputs included.  ``member_id`` is the Family's member that
    took the request; ``worker_id`` the Resident that wrote the message, which
    differs in a nested Family, reached ``via`` its facades.
    """

    clean = str(message_id or "")
    if not clean:
        return None
    repository = resident_conversation_stream.get_repository()
    carried: dict[str, dict[str, tuple[str, str, list[str]]]] = {}
    for request_id, link in relay_links(facade).items():
        member_id = str(link.get("resident_id") or "")
        via, (worker_id, worker_message_id) = relay_holder(member_id, str(link.get("message_id") or ""))
        carried.setdefault(worker_id, {})[worker_message_id] = (request_id, member_id, via)
    # A message lives in one Conversation: each Resident doing the Family's work is read once.
    for worker_id, requests in carried.items():
        reply = repository.message(worker_id, clean)
        if reply is None or reply.get("role") != "agent":
            continue
        found = requests.get(str(reply.get("reply_to_message_id") or ""))
        if found is None:
            continue
        request_id, member_id, via = found
        return {"request_message_id": request_id, "member_id": member_id, "worker_id": worker_id,
                "via": via, "reply": reply}
    return None

def _observe(facade, incident):
    from .resident_workspace_domain import _find_resident
    from .resident_lifecycle_domain import _resident_intake_state
    root = incident.get("request_message_id")
    if root:
        state = family_recovery.request_status(facade, root)
    else:
        state = _input(incident["resident_id"], incident["message_id"])
    state = {**state, "resident_id": state.get("resident_id") or incident["resident_id"],
             "message_id": state.get("member_message_id") or incident["message_id"]}
    status = state.get("state")
    if status == "completed":
        return "resolved", state
    if status == "cancelled":
        return "cancelled", state
    if status in {"queued", "running", "routing"}:
        return "waiting", state
    record = _find_resident(state["resident_id"])
    if record and _resident_intake_state(record) != "open":
        return "paused", state
    return "open", state


def _escalate(lineage_id, family, incidents, reason):
    from .lineage_human_notifications import create_notification
    creator = str(family.get("human_familizer_id") or "")
    for incident in incidents:
        incident["escalation_reason"] = reason
        if not creator:
            incident["status"] = "missing_creator"
            continue
        notification_id = "family-recovery:" + _id(family["facade"] + ":" + incident["key"])
        observed = incident.get("observed") or {}
        create_notification(lineage_id, recipients=[creator], created_by=family["facade"], severity="error",
            notification_id=notification_id, title=f"Family「{family['title']}」需要恢复协助",
            message=f"{reason}。原请求：{incident.get('request_message_id') or incident['message_id']}；"
                    f"当前接手者：{observed.get('resident_id') or incident['resident_id']}；"
                    f"状态：{observed.get('state') or 'unknown'}；错误：{str(observed.get('error') or '')[:1500]}。"
                    "任务和故障记录已保留，请处理阻塞后恢复原任务。")
        incident.update(status="escalated", notification_id=notification_id)

event = event or {}
event_type = str(event.get("type") or "")
candidates = []
if event_type in {"resident.work_failed", "effect.failed", "event.delivery_failed"}:
    subject = _event_input(lineage_id, event)
    if subject and subject[0] in roles:
        candidates.append(_candidate(facade, *subject))
# Timers recheck known incidents only. Historical failed copies (including
# old continue commands) are not new work and must not be rediscovered.
repository = get_lineage_data_store().family_relays
now = _now()
pending = None
with repository.transaction(lineage_id, family["facade"]) as relay:
    ledger = relay.setdefault("supervision", {"incidents": {}})
    incidents = ledger["incidents"]
    for candidate in candidates:
        # A failed repair round belongs to its existing incidents. Do not
        # turn the reminder itself into a new user task (or notify twice).
        if (candidate["resident_id"] == family["steward"] and
                candidate["message_id"] == ledger.get("notice", {}).get("message_id")):
            continue
        incidents.setdefault(candidate["key"], {**candidate, "status": "open", "attempts": 0, "created_at": now})
    for incident in incidents.values():
        if incident["status"] in {"resolved", "cancelled"}:
            continue
        status, observed = _observe(facade, incident)
        incident.update(observed=observed, checked_at=now)
        if incident["status"] not in {"escalated", "missing_creator"} or status in {"resolved", "cancelled"}:
            incident["status"] = status
    missing_creator = [i for i in incidents.values() if i["status"] == "missing_creator"]
    for incident in missing_creator:
        _escalate(lineage_id, family, [incident], incident["escalation_reason"])
    active = [i for i in incidents.values() if i["status"] not in TERMINAL]
    steward_failure = any(i["resident_id"] == family["steward"] and
                          i.get("observed", {}).get("state") in {"failed", "missing"} for i in active)
    if active and (steward_failure or escalate_reason):
        _escalate(lineage_id, family, active, escalate_reason or "steward 运行失败，无法继续监督恢复")
    notice = ledger.get("notice") or {}
    notice_state = _input(family["steward"], notice["message_id"]).get("state") if notice else ""
    if active and notice_state in {"failed", "cancelled"}:
        _escalate(lineage_id, family, [i for i in active if i["status"] not in TERMINAL], "steward 的恢复轮次失败或已停止")
    open_incidents = [i for i in active if i["status"] == "open"]
    repair_pending = bool(notice and (not notice.get("delivered") or notice_state in {"queued", "running"}))
    exhausted = [i for i in open_incidents if i["attempts"] >= MAX_REPAIR_ROUNDS and not repair_pending]
    if exhausted:
        _escalate(lineage_id, family, exhausted, f"steward 已跟进 {MAX_REPAIR_ROUNDS} 轮，原任务仍未恢复完成")
    open_incidents = [i for i in open_incidents if i["status"] == "open"]
    # One outstanding repair message per Family, including a durable unsent outbox.
    if notice and not notice.get("delivered"):
        if any(incidents[key]["status"] == "open" for key in notice["incident_keys"]):
            pending = deepcopy(notice)
        else:
            notice.update(delivered=True, withdrawn=True)
    elif open_incidents and notice_state not in {"queued", "running"}:
        from .resident_lifecycle_domain import _resident_intake_state
        steward = _find_resident(family["steward"])
        if not steward or _resident_intake_state(steward) != "open":
            _escalate(lineage_id, family, open_incidents, "steward 不可接单，无法继续监督恢复")
        else:
            for incident in open_incidents:
                incident["attempts"] += 1
            identity = ";".join(f"{i['key']}:{i['attempts']}" for i in sorted(open_incidents, key=lambda i: i['key']))
            details = "\n".join(f"- {i['key']}：当前 {i['observed']}；第 {i['attempts']} 轮恢复" for i in open_incidents)
            text = (f"Family 故障持续监督（{block['id']}）：\n{details}\n"
                    "请定位原因并修复，目标是完成原任务。用 GetInputState 核对原输入；已经改派则检查新接手者。"
                    "RequeueMessage 或 RestartSession 后的入队/运行只表示正在恢复；不要发一条无原任务的 continue。"
                    "尊重人工关闭接单、暂停和取消，不擅自恢复。你的本轮结束后平台会再核验，未解决会继续交给你。"
                    f"确实无法继续时调用 CheckFamilyRecovery(lineage_id={lineage_id}, family_id={block['id']}, "
                    "escalate_reason=具体阻塞)，平台以门面身份通知实际创立者。")
            pending = {"message_id": "msg_" + _id(family["facade"] + identity), "text": text,
                       "incident_keys": [i["key"] for i in open_incidents], "delivered": False}
            ledger["notice"] = pending
    closed = sorted((i for i in incidents.values() if i["status"] in {"resolved", "cancelled"}), key=lambda i: i["created_at"])
    for incident in closed[:-500]:
        del incidents[incident["key"]]
if pending:
    try:
        family_facade.tell_steward(family["facade"], family["steward"], family["facade"], pending["text"],
                                  message_id=pending["message_id"], business_ref=REF)
    except Exception as exc:
        with repository.transaction(lineage_id, family["facade"]) as relay:
            ledger = relay["supervision"]
            _escalate(lineage_id, family, [ledger["incidents"][key] for key in pending["incident_keys"]
                      if ledger["incidents"][key]["status"] not in TERMINAL], f"无法通知 steward：{str(exc)[:500]}")
            ledger["notice"]["error"] = str(exc)[:1000]
            ledger["notice"]["delivered"] = True
    else:
        with repository.transaction(lineage_id, family["facade"]) as relay:
            if relay["supervision"].get("notice", {}).get("message_id") == pending["message_id"]:
                relay["supervision"]["notice"]["delivered"] = True
ledger = repository.get(lineage_id, family["facade"])["supervision"]
return {"family_id": block["id"], "incidents": list(ledger["incidents"].values()), "notice": ledger.get("notice") or {}}

class NotificationHub:
    """Bounded, process-local cursor used by authenticated SSE handlers."""

    def __init__(self, max_items: int = MAX_LOCAL_NOTIFICATIONS) -> None:
        self._items: deque[Notification] = deque(maxlen=max(32, int(max_items)))
        self._sequence = 0
        self._subscriber_sequence = 0
        self._subscribers: dict[int, Callable[[Notification], None]] = {}
        self._condition = threading.Condition()

    @property
    def sequence(self) -> int:
        with self._condition:
            return self._sequence

    def publish(self, subject: str, payload: dict[str, Any]) -> Notification:
        with self._condition:
            self._sequence += 1
            notification = Notification(
                sequence=self._sequence,
                subject=str(subject or ""),
                payload=dict(payload),
                received_at=time.time(),
            )
            self._items.append(notification)
            subscribers = list(self._subscribers.values())
            self._condition.notify_all()
        for subscriber in subscribers:
            try:
                subscriber(notification)
            except Exception:
                continue
        return notification

    def subscribe(
        self,
        callback: Callable[[Notification], None],
    ) -> Callable[[], None]:
        with self._condition:
            self._subscriber_sequence += 1
            subscription_id = self._subscriber_sequence
            self._subscribers[subscription_id] = callback

        def unsubscribe() -> None:
            with self._condition:
                self._subscribers.pop(subscription_id, None)

        return unsubscribe

    def cursor_has_gap(self, after_sequence: int) -> bool:
        cursor = max(0, int(after_sequence))
        with self._condition:
            return bool(
                self._items
                and cursor < self._items[0].sequence - 1
            )

    def wait(
        self,
        after_sequence: int,
        *,
        predicate: Callable[[Notification], bool] | None = None,
        timeout: float = 15.0,
    ) -> tuple[list[Notification], int]:
        cursor = max(0, int(after_sequence))
        deadline = time.monotonic() + max(0.0, float(timeout))
        with self._condition:
            while True:
                matches = [
                    item
                    for item in self._items
                    if item.sequence > cursor
                    and (predicate is None or predicate(item))
                ]
                if matches:
                    return matches, self._sequence
                remaining = deadline - time.monotonic()
                if remaining <= 0:

                self._condition.wait(remaining)


class NatsNotificationPublisher:
    """Best-effort NATS publisher with a bounded, non-blocking caller path."""

    def __init__(self, *, component: str = "publisher", queue_size: int = 2048) -> None:
        self.component = str(component or "publisher")
        self._queue: queue.Queue[tuple[str, bytes]] = queue.Queue(
            maxsize=max(32, int(queue_size))
        )
        self._thread: threading.Thread | None = None
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self._published = 0
        self._dropped = 0
        self._last_error = ""
        self._connected = False

    def start(self) -> None:
        if not nats_enabled():
            return
        with self._lock:
            if self._thread is not None and self._thread.is_alive():
                return
            self._stop.clear()
            self._thread = threading.Thread(
                target=self._run,
                name=f"portal-nats-{self.component}",
                daemon=True,
            )
            self._thread.start()

    def close(self, timeout: float = 2.0) -> None:
        self._stop.set()
        thread = self._thread
        if thread is not None:
            thread.join(timeout=max(0.0, float(timeout)))
        with self._lock:
            if self._thread is thread and (thread is None or not thread.is_alive()):
                self._thread = None
            self._connected = False

    def publish(self, subject: str, payload: dict[str, Any] | None = None) -> bool:
        body = json.dumps(
            payload or {"kind": "changed"},
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        if len(body) > MAX_NOTIFICATION_BYTES:
            raise ValueError("notification payload exceeds 900 KiB")
        self.start()
        if not nats_enabled():
            return False
        try:
            self._queue.put_nowait((str(subject or ""), body))
            return True
        except queue.Full:
            with self._lock:
                self._dropped += 1
            return False

    def health(self) -> dict[str, Any]:
        with self._lock:
            return {
                "enabled": nats_enabled(),
                "url": nats_url(),
                "connected": self._connected,
                "queued": self._queue.qsize(),
                "published": self._published,
                "dropped": self._dropped,
                "last_error": self._last_error,
            }

    def _run(self) -> None:
        asyncio.run(self._run_async())

    async def _run_async(self) -> None:
        client = None
        while not self._stop.is_set():
            if client is None or not client.is_connected:
                try:
                    from .nats_client import connect_notifications

                    client = await connect_notifications(
                        servers=[nats_url()],
                        name=nats_client_name(self.component),
                        connect_timeout=1,
                        allow_reconnect=True,
                        max_reconnect_attempts=-1,
                        reconnect_time_wait=1,
                    )
                    with self._lock:
                        self._connected = True
                        self._last_error = ""
                except Exception as exc:
                    with self._lock:
                        self._connected = False
                        self._last_error = f"{exc.__class__.__name__}: {exc}"[:500]
                    await asyncio.sleep(1)
                    continue
            try:
                subject, body = self._queue.get_nowait()
            except queue.Empty:
                await asyncio.sleep(0.1)
                continue
            try:
                await client.publish(subject, body)
                await client.flush(timeout=1)
                with self._lock:
                    self._published += 1
                    self._last_error = ""
            except Exception as exc:
                with self._lock:
                    self._connected = False
                    self._last_error = f"{exc.__class__.__name__}: {exc}"[:500]
                try:
                    self._queue.put_nowait((subject, body))
                except queue.Full:
                    with self._lock:
                        self._dropped += 1
                try:
                    await client.close()
                except Exception:
                    pass
                client = None
        if client is not None:
            try:
                await client.drain()
            except Exception:
                try:
                    await client.close()
                except Exception:
                    pass


class NatsNotificationListener:
    def __init__(self, hub: NotificationHub, *, component: str = "portal-gateway") -> None:
        self.hub = hub
        self.component = component
        self._thread: threading.Thread | None = None

def publish_local_projection_change(
    projection: str,
    target_id: str,
    *,
    actor: str = "",
    actors: list[str] | None = None,
    fields: list[str] | None = None,
    details: dict[str, Any] | None = None,
) -> Notification:
    """Notify browser projections after a Portal-local durable commit."""

    payload: dict[str, Any] = {"kind": "changed"}
    if actor:
        payload["actor"] = str(actor)
    clean_actors = sorted({
        str(item).strip()
        for item in (actors or [])
        if str(item).strip()
    })
    if clean_actors:
        payload["actors"] = clean_actors
    if fields:
        payload["fields"] = [str(item) for item in fields if str(item)]
    if details:
        payload["details"] = dict(details)
    return _HUB.publish(
        business_projection_subject(projection, target_id),
        payload,
    )


def publish_projection_change(projection: str, target_id: str, **kwargs) -> Notification:
    """Deliver a committed viewer change locally and to every Portal instance.

    NATS may echo the notification. Consumers coalesce invalidations and read
    authoritative state, so duplicate delivery is safe.
    """
    notification = publish_local_projection_change(projection, target_id, **kwargs)
    _PUBLISHER.publish(notification.subject, notification.payload)
    return notification

async def wait(self, timeout: float) -> AsyncNotificationBatch | None:
    try:
        first = await asyncio.wait_for(
            self._queue.get(),
            timeout=max(0.0, float(timeout)),
        )
    except asyncio.TimeoutError:
        return None
    if first is _CLOSED:
        return AsyncNotificationBatch(closed=True)
    if first is _SNAPSHOT_REQUIRED:
        self._snapshot_pending = False
        return AsyncNotificationBatch(snapshot_required=True)

    notifications = [first]
    while True:
        try:
            item = self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
        if item is _CLOSED:
            self._closed = True
            break
        if item is _SNAPSHOT_REQUIRED:
            self._snapshot_pending = False
            return AsyncNotificationBatch(snapshot_required=True)
        notifications.append(item)
    return AsyncNotificationBatch(notifications=tuple(notifications))

def close(self) -> None:
    if self._closed:
        return
    self._closed = True
    self._fanout._unsubscribe(self._subscription_id)

def _offer(self, notification: Notification) -> None:
    if self._closed or self._snapshot_pending:
        return
    try:
        if not self._predicate(notification):
            return
    except Exception:
        return
    try:
        self._queue.put_nowait(notification)
    except asyncio.QueueFull:
        self._require_snapshot()

def _require_snapshot(self) -> None:
    if self._closed or self._snapshot_pending:
        return
    while True:
        try:
            self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
    self._snapshot_pending = True
    self._queue.put_nowait(_SNAPSHOT_REQUIRED)

def _close_from_fanout(self) -> None:
    if self._closed:
        return
    self._closed = True
    while True:
        try:
            self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
    self._queue.put_nowait(_CLOSED)

def start(self) -> None:
    loop = asyncio.get_running_loop()
    with self._lock:
        if not self._closed:
            raise RuntimeError("async notification fanout is already started")
        self._loop = loop
        self._closed = False
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    self._unsubscribe_hub = self._hub.subscribe(self._accept_from_hub)

def subscribe(
    self,
    predicate: Callable[[Notification], bool] | None = None,
) -> AsyncNotificationSubscription:
    if self._closed or self._loop is None:
        raise RuntimeError("async notification fanout is not running")
    if asyncio.get_running_loop() is not self._loop:
        raise RuntimeError("async notification subscription uses another event loop")
    self._subscriber_sequence += 1
    subscription = AsyncNotificationSubscription(
        self,
        self._subscriber_sequence,
        predicate or (lambda _notification: True),
        self._subscriber_queue_size,
    )
    self._subscribers[self._subscriber_sequence] = subscription
    return subscription

def close(self) -> None:
    with self._lock:
        if self._closed:
            return
        self._closed = True
        unsubscribe_hub = self._unsubscribe_hub
        self._unsubscribe_hub = None
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    if unsubscribe_hub is not None:
        unsubscribe_hub()
    subscribers = tuple(self._subscribers.values())
    self._subscribers.clear()
    for subscription in subscribers:
        subscription._close_from_fanout()

def _unsubscribe(self, subscription_id: int) -> None:
    self._subscribers.pop(subscription_id, None)

def _accept_from_hub(self, notification: Notification) -> None:
    with self._lock:
        if self._closed or self._loop is None:
            return
        if len(self._pending) >= self._pending_limit:
            self._pending.clear()
            self._pending_overflow = True
        elif not self._pending_overflow:
            self._pending.append(notification)
        if self._drain_scheduled:
            return
        self._drain_scheduled = True
        loop = self._loop
    try:
        loop.call_soon_threadsafe(self._drain_pending)
    except RuntimeError:
        with self._lock:
            self._drain_scheduled = False

def _drain_pending(self) -> None:
    with self._lock:
        if self._closed:
            self._drain_scheduled = False
            return
        pending = tuple(self._pending)
        overflow = self._pending_overflow
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    subscribers = tuple(self._subscribers.values())
    if overflow:
        for subscription in subscribers:
            subscription._require_snapshot()
        return
    for notification in pending:
        for subscription in subscribers:
            subscription._offer(notification)

def _run(self) -> None:
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        init = libc.inotify_init1
        init.argtypes = [ctypes.c_int]
        init.restype = ctypes.c_int
        add_watch = libc.inotify_add_watch
        add_watch.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_uint32]
        add_watch.restype = ctypes.c_int
        fd = int(init(os.O_NONBLOCK | os.O_CLOEXEC))
        if fd < 0:
            error_number = ctypes.get_errno()
            raise OSError(error_number, os.strerror(error_number))
        self._fd = fd
        with self._lock:
            self._add_watch = add_watch
            directories = tuple(
                sorted(self._configured_directories, key=str)
            )
        for directory in directories:
            try:
                if self.recursive:
                    self._add_tree(directory, add_watch)
                else:
                    self._add_directory(directory, add_watch)
            except OSError as exc:
                self._set_error(exc)
        with self._lock:
            self._ready = True

        while not self._stopped.is_set():
            try:
                readable, _writable, _errors = select.select([fd], [], [], 1.0)
            except (OSError, ValueError):
                if self._stopped.is_set():
                    break
                raise
            if not readable:
                continue
            try:
                payload = os.read(fd, 256 * 1024)
            except BlockingIOError:
                continue
            offset = 0
            while offset + self._EVENT.size <= len(payload):
                watch, mask, _cookie, name_length = self._EVENT.unpack_from(
                    payload,
                    offset,
                )
                offset += self._EVENT.size
                raw_name = payload[offset : offset + name_length]
                offset += name_length
                if mask & self._IN_Q_OVERFLOW:
                    self.on_overflow()
                    continue
                with self._lock:
                    directory = self._paths_by_watch.get(watch)
                if directory is None:
                    continue
                name = (
                    os.fsdecode(raw_name.split(b"\0", 1)[0])
                    if raw_name
                    else ""
                )
                path = (
                    (directory / name).resolve(strict=False)
                    if name
                    else directory
                )
                if mask & self._IN_IGNORED:
                    with self._lock:
                        removed = self._paths_by_watch.pop(watch, None)
                        if removed is not None:
                            self._watch_by_path.pop(removed, None)
                    continue
                if mask & self._IN_ISDIR and mask & (
                    self._IN_CREATE | self._IN_MOVED_TO
                ):
                    if self.track_new_directories:
                        self._add_tree(path, add_watch)
                with self._lock:
                    self._last_event_at = _now_iso()
                self.on_change(str(path))
    except Exception as exc:
        if not self._stopped.is_set():
            self._set_error(exc)
    finally:
        with self._lock:
            self._ready = False
            self._add_watch = None
        fd = self._fd
        self._fd = -1
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                pass

    resident_ids = {
        resident_id.strip()
        for value in request.query_params.getlist("resident_ids")
        for resident_id in value.split(",")
        if resident_id.strip()
    }

    def accepts(notification) -> bool:
        if notification.subject == "portal.gateway.reconnected":
            return True
        domain, target_id = portal._notification_target(notification.subject)
        if domain not in domains:
            return False
        if domain != "resident" or not notification.subject.endswith(".conversation"):
            return True
        if target_id in resident_ids:
            return True
        event = notification.payload.get("event")
        return (
            notification.payload.get("kind") == "conversation_event"
            and isinstance(event, dict)
            and event.get("event_type") == "resident.state.changed"
        )

    return accepts


async def portal_events(request: Request):
    actor = portal._get_session_username(
        SimpleNamespace(headers=_request_headers(request))
    ) or ""
    if not actor:
        return RedirectResponse("/login", status_code=302)
    domains = _requested_domains(request)
    ensure_notification_listener()
    ensure_knowledge_archive_projection_watcher()
    fanout = getattr(request.app.state, "notification_fanout", None)
    payload_executor = getattr(request.app.state, "sse_payload_executor", None)
    realtime_lifecycle = getattr(
        request.app.state, "realtime_lifecycle", None
    )
    if (
        not isinstance(realtime_lifecycle, RealtimeConnectionLifecycle)
        or not realtime_lifecycle.accepting
        or not isinstance(fanout, AsyncNotificationFanout)
        or payload_executor is None
    ):
        return _json_error(503, "Portal realtime notifications are unavailable")

    async def events() -> AsyncIterator[bytes]:
        connection_id = realtime_lifecycle.open_connection()
        if connection_id is None:
            return
        subscription = fanout.subscribe(_event_subscription_predicate(request, domains))
        drain_wait = asyncio.create_task(realtime_lifecycle.drain_event.wait())
        try:
            yield b"retry: 1500\n\n"
            yield _sse("portal-ready", {"snapshot_required": True})
            while True:
                batch = await subscription.wait(SSE_HEARTBEAT_SECONDS)
                if batch is None:
                    yield _sse("heartbeat", {"at": portal.time.time()})
                    continue
                if batch.closed:
                    return
                if batch.snapshot_required:
                    yield _sse(
                        "portal-change",
                        {
                            "domains": [],
                            "changed": {},
                            "snapshot_required": True,
                        },
                    )
                    continue
                loop = asyncio.get_running_loop()
                payload_future = loop.run_in_executor(
                    payload_executor,
                    partial(
                        portal._portal_change_payload,
                        actor,
                        list(batch.notifications),
                        domains,
                    ),
                )
                try:
                    done, _pending = await asyncio.wait(
                        {payload_future, drain_wait},
                        timeout=SSE_PAYLOAD_TIMEOUT_SECONDS,
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                    if drain_wait in done or realtime_lifecycle.drain_event.is_set():
                        payload_future.cancel()
                        return
                    if payload_future not in done:
                        payload_future.cancel()
                        yield _sse(
                            "portal-change",
                            {
                                "domains": [],
                                "changed": {},
                                "snapshot_required": True,
                            },
                        )
                        continue
                except asyncio.CancelledError:
                    payload_future.cancel()
                    raise
                payload = await payload_future
                if (
                    realtime_lifecycle.drain_event.is_set()
                    or not realtime_lifecycle.accepting
                ):
                    return
                if payload["domains"] or payload["snapshot_required"]:
                    yield _sse("portal-change", payload)

