def get_resource_service():
    global _SERVICE
    if _SERVICE is None:
        with _SERVICE_LOCK:
            if _SERVICE is None:
                mode = resource_service_mode()
                if mode == "client":
                    from .transport import ResourceServiceClient

                    _SERVICE = ResourceServiceClient()
                elif mode in {"local", "server"}:
