                    )
    return _SERVICE

def handle(self) -> None:
    request_id = ""
    try:
        request = json.loads(self.rfile.readline())
        if not isinstance(request, dict):
            raise ValueError("request envelope must be an object")
        request_id = str(request.get("id") or "")
        params = request.get("params")
        if not isinstance(params, dict):
            raise ValueError("request params must be an object")
        method = str(request.get("method") or "")
        actor = self.server.authenticate(method, params, request.get("auth"))
        if method == INSTRUCTION_METHOD:
            self._serve_instruction(params, request_id, actor if request.get("auth") else None)
            return
        from management_common.authorization_context import SubjectBinding, authorization_scope
        from management_common.execution_association import execution_scope
        from management_common.resource_lifecycle import lifecycle_scope

        envelope = params.pop("_authorization", None)
        binding = SubjectBinding.from_dict(envelope) if envelope is not None else None
        if binding is not None and (not request.get("auth") or (actor and actor != binding.context.principal_id)):
            raise PermissionError("Authorization subject must match the authenticated RPC actor")
        execution_id = params.pop("_execution_id", "")
        if execution_id and not request.get("auth"):
            raise PermissionError("Execution association requires authenticated RPC")
        lifecycle_id = params.pop("_resource_lifecycle_id", "")
        if lifecycle_id and not request.get("auth"):
            raise PermissionError("Resource lifecycle requires authenticated RPC")
        with authorization_scope(binding), execution_scope(execution_id), lifecycle_scope(lifecycle_id, actor=actor):
            result = self.server.dispatch(method, params, actor=actor)
        if (
            isinstance(result, tuple)
            and len(result) == 3
            and isinstance(result[0], bytes)
        ):
            data, content_type, resolved = result
            response = {
                "id": request_id,
                "ok": True,
                "content": {
                    "length": len(data),
                    "content_type": str(content_type or "application/octet-stream"),
                    "resolved": resolved,
                },
            }
            try:
                self.wfile.write(
                    json.dumps(
                        response,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ).encode("utf-8")
                    + b"\n"
                )
                self.wfile.write(data)
            except (BrokenPipeError, ConnectionResetError):
                return
            return
        response = {"id": request_id, "ok": True, "result": result}
    except Exception as exc:
        response = {
            "id": request_id,
            "ok": False,
            "error": resource_error_payload(exc),
        }
    try:
        self.wfile.write(
            json.dumps(
                response,
                ensure_ascii=False,
                separators=(",", ":"),
            ).encode("utf-8")
            + b"\n"
        )
    except (BrokenPipeError, ConnectionResetError):
        return

