class ResourceAccessPolicy:
    """Every authenticated User or Resident reads resources.

    No store supplies resource authorization: the dynamic ISA policy decides
    resource credentials (decision_707d2910d389), the facade authenticates
    actors and domain resolvers enforce their own business rules.
    """

    def can_read(self, value: Mapping[str, Any], *, actor: str = "") -> bool:
        # ``value`` is the record callers ask about; no read rule depends on it.
        return is_user_or_resident(actor)

    def authorize_read(self, value: Mapping[str, Any], *, actor: str = "") -> None:
        if not self.can_read(value, actor=actor):
            raise PermissionError("Resource is not accessible to this authenticated actor")

def query(self, **kwargs: Any) -> dict[str, Any]:
    query = ResourceQuery.from_kwargs(kwargs)
    if query.q:
        try:
            parsed = self.parse_address(query.q)
        except ValueError:
            parsed = None
        if parsed is not None and parsed.value == query.q.strip("/"):
            try:
                reference = self.reference(
                    parsed.value,
                    actor=query.actor,
                )
            except (KeyError, FileNotFoundError):
                return query_records(
                    (),
                    query,
                    exact_address=True,
                    portal_access=self._portal_access,
                )
            return query_records(
                (reference,),
                query,
                exact_address=True,
                portal_access=self._portal_access,
            )
    return self._index().query(
        records_projector=self._collaboration_descriptors,
        records_projector_types=COLLABORATION_RESOURCE_TYPES,
        **kwargs,
    )

def _require_ready(
    self,
    adapters: Iterable[str],
    *,
    timeout: float = 30.0,
) -> None:
    missing = [
        name
        for name in adapters
        if not self.store.adapter_has_snapshot(name)
    ]
    if not missing:
        return
    self.adapter_layer.request_refresh(missing)
    self.adapter_layer.wait(missing, timeout=timeout)
    unavailable = [
        name for name in missing if not self.store.adapter_has_snapshot(name)
    ]
    if unavailable:
        raise ResourceServiceUnavailable(
            "resource projection unavailable: " + ", ".join(unavailable)
        )

def query(self, **kwargs: Any) -> dict[str, Any]:
    query = ResourceQuery.from_kwargs(kwargs)
    self._require_ready(self._target_adapters(query.resource_types))
    return self.store.query(**kwargs)

def _fingerprint(
    resource_type: str,
    payload: Mapping[str, Any],
    *,
    actor: str,
) -> str:
    try:
        canonical = json.dumps(
            {
                "actor": actor,
                "payload": dict(payload),
                "resource_type": resource_type,
            },
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "service-managed resource registration payload must be JSON-compatible"
        ) from exc
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

@staticmethod
def _ensure_schema(connection) -> None:
    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS resource_registrations (
            fingerprint TEXT PRIMARY KEY,
            resource_type TEXT NOT NULL,
            actor TEXT NOT NULL,
            resource_id TEXT NOT NULL,
            created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
        )
        """
    )

def _prepare_schema(self) -> None:
    if self._schema_ready:
        return
    with self._schema_lock:
        if self._schema_ready:
            return
        # Only the one-time DDL needs a schema-wide lock. Registrations
        # for different fingerprints must not serialize behind it.
        with self._database.connect() as connection:
            connection.execute(
                "SELECT pg_advisory_xact_lock(hashtextextended(current_schema(), 0))"
            )
            self._ensure_schema(connection)
            connection.commit()
        self._schema_ready = True

def reserve(
    self,
    resource_type: str,
    payload: Mapping[str, Any],
    *,
    actor: str,
    allocate: Callable[[], str],
) -> tuple[str, bool]:
    fingerprint = self._fingerprint(resource_type, payload, actor=actor)
    self._prepare_schema()
    resource_id = allocate()
    with self._database.connect() as connection:
        row = connection.execute(
            '\n                INSERT INTO resource_registrations (\n                    fingerprint, resource_type, actor, resource_id\n                ) VALUES (%s, %s, %s, %s)\n                ON CONFLICT (fingerprint) DO NOTHING\n                RETURNING resource_id\n                ',
            (fingerprint, resource_type, actor, resource_id),
        ).fetchone()
        created = row is not None
        if row is None:
            # ON CONFLICT waits for the competing transaction to finish;
            # a new statement then sees its committed ID.
            row = connection.execute(
                'SELECT resource_id FROM resource_registrations WHERE fingerprint = %s',
                (fingerprint,),
            ).fetchone()
            if row is None:
                raise RuntimeError("registration reservation disappeared")
        connection.commit()
        return str(row[0]), created

def _root(record):
    raw = (record.get("attributes") or {}).get("path")
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        raise ResourceOperationError("workspace_content_root_invalid", "Workspace has no valid registered path", 500)
    root = PurePosixPath(raw)
    if not root.is_absolute() or len(root.parts) < 2 or ".." in root.parts:
        raise ResourceOperationError("workspace_content_root_invalid", "Workspace requires an absolute registered directory", 500)
    return root


@contextmanager
def _open_file(root, parts):
    """Pin every directory and reject symlink swaps, including the root path."""
    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
    with ExitStack() as stack:
        def opened(path, flags, **kwargs):
            fd = os.open(path, flags, **kwargs)
            stack.callback(os.close, fd)
            return fd

        try:
            directory = opened("/", directory_flags)
            for part in (*root.parts[1:], *parts[:-1]):
                directory = opened(part, directory_flags, dir_fd=directory)
            target = opened(parts[-1], os.O_PATH | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory)
        except OSError as exc:
            if exc.errno in {errno.ELOOP, errno.ENOTDIR}:
                raise ValueError("Workspace file path contains a symlink or non-directory component") from exc
            raise
        mode = os.fstat(target).st_mode
        if stat.S_ISLNK(mode):
            raise ValueError("Workspace file path contains a symlink")
        if not stat.S_ISREG(mode):
            raise ValueError("Workspace file address requires a regular file")
        # Reopen the pinned regular inode, never the mutable user pathname.
        fd = opened(f"/proc/self/fd/{target}", os.O_RDONLY | os.O_CLOEXEC)
        yield fd


def _resolve(service: "ResourceService", address, *, actor="", **_context):
    root_id, separator, suffix = address.partition("/")
    record = service.get(root_id, actor=actor)
    attributes = record.get("attributes") or {}
    exists = attributes.get("status") != "deleted" and not attributes.get("deleted_at")
    # get() checks current descriptor lifecycle and the Resource facade. File
    # traversal remains pinned below; old inherited ACL owners are not facts.
    result = {
        "address": address,
        "root_id": root_id,
        "resource_type": "workspace",
        "target_kind": "workspace",
        "record": record,
        "exists": bool(exists),
        "portal_url": record.get("url", ""),
    }
    if not separator:
        return result
    namespace, _, relative = suffix.partition("/")
    parts = tuple(relative.split("/"))
    if namespace != "file" or any(part in {"", ".", ".."} for part in parts):
        raise ValueError("Workspace file address requires a relative file path without dot segments")
    from management_portal.lineage_service.lineage_access_policy import workspace_reaches

    # Before any file is touched, so a denied read looks like a missing one.
    raw_root = str(attributes.get("path") or "")
    file_path = str(PurePosixPath(raw_root) / relative) if raw_root.startswith("/") else ""
    if not workspace_reaches(actor, root_id, "viewer", path=file_path):
        raise KeyError(address)
    result.update(
        target_kind="file", relative_path=relative, filename=parts[-1], title=parts[-1],
        portal_url="/api/resources/content?" + urlencode({"address": address}),
    )
    if exists:
        try:
            with _open_file(_root(record), parts) as fd:
                target_stat = os.fstat(fd)
                result["content_size"] = target_stat.st_size
                result["content_mtime_ns"] = target_stat.st_mtime_ns
        except FileNotFoundError:
            result["exists"] = False
    # No resolved_path: HTTP must read these bytes through this Provider, not
    # reopen a filesystem path after ResourceService's boundary checks.
    return result

def _read_content(resolved, *, max_bytes=4 * 1024 * 1024, **_context):
    if not resolved["exists"]:
        raise KeyError(resolved["address"])
    if resolved["target_kind"] != "file":
        raise ValueError("Workspace root has no byte content; use <workspace-id>/file/<relative-path>")
    if type(max_bytes) is not int or max_bytes < 1:
        raise ValueError("max_bytes must be a positive integer")
    with _open_file(_root(resolved["record"]), tuple(resolved["relative_path"].split("/"))) as fd:
        if os.fstat(fd).st_size > max_bytes:
            raise ValueError(f"resource exceeds {max_bytes} byte content limit")
        with os.fdopen(os.dup(fd), "rb") as stream:
            data = stream.read(max_bytes + 1)
        if len(data) > max_bytes:
            raise ValueError(f"resource exceeds {max_bytes} byte content limit")
    content_type = resolved_media_type(resolved, fallback="application/octet-stream")
    return data, content_type, resolved


def _read_content_range(resolved, *, start, end, **_context):
    if not resolved["exists"]:
        raise KeyError(resolved["address"])
    if resolved["target_kind"] != "file":
        raise ValueError("Workspace root has no byte content; use <workspace-id>/file/<relative-path>")
    if type(start) is not int or type(end) is not int or start < 0 or end < start:
        raise ValueError("content range requires non-negative inclusive start and end")
    with _open_file(_root(resolved["record"]), tuple(resolved["relative_path"].split("/"))) as fd:
        target_stat = os.fstat(fd)
        if start >= target_stat.st_size:
            raise ValueError("content range starts beyond the resource")
        actual_end = min(end, target_stat.st_size - 1)
        remaining = actual_end - start + 1
        os.lseek(fd, start, os.SEEK_SET)
        chunks = []
        while remaining > 0:
            chunk = os.read(fd, min(remaining, 1024 * 1024))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
    current = {
        **resolved,
        "content_size": target_stat.st_size,
        "content_mtime_ns": target_stat.st_mtime_ns,
    }
    content_type = resolved_media_type(resolved, fallback="application/octet-stream")
    return b"".join(chunks), content_type, current

