def update_workspace_link_file(
    raw_path: str,
    actor: str = "",
    content: str = "",
    expected_mtime_ns: object = None,
    base_content: object = None,
    expected_sha256: str = "",
) -> dict[str, Any]:
    path, authorization = _resolve_authorized_link_file_path(
        raw_path,
        actor,
        write=True,
    )
    if path.is_dir() or path.is_symlink():
        raise ValueError("directory or symlink cannot be edited")
    if _file_kind(path) not in {"markdown", "json", "jsonl", "text"}:
        raise ValueError("当前文件种类不支持编辑")
    stat = path.stat()
    if stat.st_size > FILE_PREVIEW_MAX_BYTES:
        raise ValueError(f"file exceeds edit limit {FILE_PREVIEW_MAX_BYTES} bytes")
    if b"\x00" in path.read_bytes()[:4096]:
        raise ValueError("binary file cannot be edited")
    if expected_mtime_ns not in (None, ""):
        try:
            expected = int(expected_mtime_ns)
        except (TypeError, ValueError):
            expected = -1
        if expected > 0 and expected != stat.st_mtime_ns:
            current = path.read_text(encoding="utf-8", errors="replace")
            if base_content is None or current != str(base_content):
                raise ValueError("文件已在预览后被修改，请刷新后再保存")
    if expected_sha256:
        import hashlib

        from .errors import LineageConflictError

        if hashlib.sha256(path.read_bytes()).hexdigest() != str(expected_sha256):
            raise LineageConflictError("文件内容已经变化，未写入", resource=str(path))
    text = str(content or "")
    if len(text.encode("utf-8")) > FILE_PREVIEW_MAX_BYTES:
        raise ValueError(
            f"file content exceeds edit limit {FILE_PREVIEW_MAX_BYTES} bytes"
        )
    resident_store.replace_file_text(path, text)
    return _workspace_link_file_payload(path, authorization)

def _workspace_directory(root: PurePosixPath, parts: tuple[str, ...]) -> Iterator[int]:
    """Open the parent directory of a workspace file without following symlinks."""

    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
    opened: list[int] = []
    try:
        directory = os.open("/", flags)
        opened.append(directory)
        for part in (*root.parts[1:], *parts[:-1]):
            try:
                child = os.open(part, flags, dir_fd=directory)
            except FileNotFoundError:
                if part in root.parts:
                    raise
                os.mkdir(part, 0o775, dir_fd=directory)
                child = os.open(part, flags, dir_fd=directory)
            opened.append(child)
            directory = child
        yield directory
    finally:
        for fd in reversed(opened):
            os.close(fd)


def _expected_file_version(inv: Invocation, address: str) -> str:
    """The content digest the caller read, when it asked for a version check."""

    expected = inv.expected_version
    if isinstance(expected, dict):
        expected = expected.get(address)
    return str(expected) if expected not in (None, "") else ""


def _update_path_file(inv: Invocation, path: str) -> dict[str, Any]:
    """A file named by absolute path: the Portal's workspace-path rules decide access."""

    from management_portal.lineage_service import get_lineage_service

    content = str(inv.argument("content") or "")
    encoded = content.encode("utf-8")
    if len(encoded) > MAX_WORKSPACE_TEXT_BYTES:
        raise invalid(f"文件内容不能超过 {MAX_WORKSPACE_TEXT_BYTES} 字节")
    result = get_lineage_service().workspace.update_workspace_link_file(
        path, inv.caller, content, expected_sha256=_expected_file_version(inv, path),
    )
    return {
        "version": hashlib.sha256(encoded).hexdigest(),
        "modified_at": str((result or {}).get("modified_at") or (result or {}).get("mtime") or _iso(_now())),
    }


def update_workspace_file(inv: Invocation) -> dict[str, Any]:
    from .providers.workspace import _root

    address = inv.argument("address")
    if address.startswith("/"):
        return _update_path_file(inv, address)
    root_id, _, suffix = address.partition("/")
    namespace, _, relative = suffix.partition("/")
    parts = tuple(relative.split("/"))
    if namespace != "file" or not relative or any(part in {"", ".", ".."} for part in parts):
        raise invalid("地址应为 <workspace-id>/file/<相对路径>")
    content = str(inv.argument("content") or "")
    encoded = content.encode("utf-8")
    if len(encoded) > MAX_WORKSPACE_TEXT_BYTES:
        raise invalid(f"文件内容不能超过 {MAX_WORKSPACE_TEXT_BYTES} 字节")
    record = _service().get(root_id, actor=inv.caller)
    from management_portal.lineage_service.lineage_access_policy import workspace_reaches

    root = _root(record)
    if not workspace_reaches(inv.caller, root_id, "contributor", path=str(root / relative)):
        raise InstructionError("instruction.forbidden", f"无权写入 {root_id}：需要 contributor")
    expected = _expected_file_version(inv, address)
    with _workspace_directory(root, parts) as directory:
        name = parts[-1]
        # Compare and replace under one lock on the parent directory.
        fcntl.flock(directory, fcntl.LOCK_EX)
        current = ""
        try:
            existing = os.stat(name, dir_fd=directory, follow_symlinks=False)
            if not stat.S_ISREG(existing.st_mode):
                raise invalid("目标不是普通文件")
            if expected:
                handle = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory)
                with os.fdopen(handle, "rb") as stream:
                    current = hashlib.sha256(stream.read()).hexdigest()
        except FileNotFoundError:
            pass
        if expected and current != expected:
            raise InstructionError(
                "instruction.version_conflict", "文件内容已经变化，未写入",
                details={"address": address, "current_version": current},
            )
        temporary = f".{name}.{secrets.token_hex(4)}.tmp"
        fd = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_CLOEXEC, 0o664, dir_fd=directory)
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(encoded)
            os.replace(temporary, name, src_dir_fd=directory, dst_dir_fd=directory)
        except BaseException:
            try:
                os.unlink(temporary, dir_fd=directory)
            except FileNotFoundError:
                pass
            raise
        written = os.stat(name, dir_fd=directory, follow_symlinks=False)
    _service().notify_source_changed(resource_id=root_id, resource_type="workspace", kind="updated")
    return {
        "version": hashlib.sha256(encoded).hexdigest(),
        "modified_at": _iso(datetime.fromtimestamp(written.st_mtime, timezone.utc)),
    }


