def _update_knowledge(
    resource_id: str,
    payload: dict[str, Any],
    *,
    actor: str = "",
) -> dict[str, Any]:
    import knowledge_board_lan.knowledge_backend as knowledge_backend

    unknown = set(payload) - {"address", "text", "expected_version", "version_recovery_change_ids"}
    if unknown:
        raise ValueError(
            "unsupported Knowledge update fields: "
            + ", ".join(sorted(unknown))
        )
    if "text" not in payload:
        raise ValueError("Knowledge update requires text")
    address = str(payload.get("address") or resource_id).strip().strip("/")
    if address.partition("/")[0] != resource_id:
        raise ValueError("Knowledge update address must belong to resource_id")
    update_options: dict[str, Any] = {}
    if "expected_version" in payload:
        update_options["expected_version"] = payload.get("expected_version")
    if "version_recovery_change_ids" in payload:
        if payload["version_recovery_change_ids"] is None:
            raise ValueError("version_recovery_change_ids cannot be null")
        update_options["version_recovery_change_ids"] = payload["version_recovery_change_ids"]
    try:
        result = knowledge_backend.update_item_text(
            address,
            str(payload.get("text") or ""),
            actor=actor,
            **update_options,
        )
    except knowledge_backend.KnowledgeVersionConflict as exc:
        raise ResourceVersionConflict(
            str(exc),
            expected_version=exc.expected_version,
            current_version=exc.current_version,
        ) from exc
    return canonical_record(resource_id, result)

def authorize(
    declaration: InstructionDeclaration,
    arguments: Mapping[str, Any],
    context: InstructionContext,
    *,
    policy: resource_policy.Snapshot | None = None,
    service=None,
    instruction_id: str = "",
) -> Retention | None:
    """Raise when the caller may not execute this call."""

    if policy is None and service is None:
        from management_portal.resources import get_resource_service
        from management_portal.resources.errors import ResourceServiceUnavailable
        from management_portal.resources.transport import ResourceServiceClient

        service = get_resource_service()
        if isinstance(service, ResourceServiceClient):
            try:
                result = service.check_instruction_authorization(
                    declaration.name, dict(arguments), actor=context.caller, entry=context.entry,
                    **({"instruction_id": instruction_id} if instruction_id else {}),
                )
            except ResourceServiceUnavailable as exc:
                # This is only the authorization read: the instruction owner
                # has not run, even if the authorization exchange was interrupted.
                raise InstructionError(
                    "instruction.owner_unavailable", "ResourceService authorization is unavailable",
                    retryable=True, commit_state="not_committed",
                ) from exc
            except Exception as exc:
                raise InstructionError("instruction.owner_unavailable", "ResourceService authorization is unavailable") from exc
            if not isinstance(result, dict):
                raise InstructionError("instruction.owner_unavailable", "ResourceService authorization returned an invalid result")
            if result.get("allowed") is True:
                if result.get("retention"):
                    from management_common.principal import actor_principal

                    return Retention(service, actor_principal(context.caller).id, result["retention"])
                return
            error = result.get("error")
            if not isinstance(error, dict) or not isinstance(error.get("code"), str):
                raise InstructionError("instruction.owner_unavailable", "ResourceService authorization returned an invalid result")
            raise InstructionError(
                error["code"], str(error.get("message") or "Authorization denied"),
                details=error.get("details") if isinstance(error.get("details"), dict) else None,
                retryable=error.get("retryable") is True,
                commit_state=str(error.get("commit_state") or "not_committed"),
            )

    name = declaration.name
    try:
        if policy is None:
            policy = resource_policy.snapshot()
        resolver = _target_resolver(policy, context, service=service)
        required = resource_policy.requirements(name, arguments, policy=policy, resolve_target=resolver)
    except resource_policy.Unresolved as exc:
        raise InstructionError("instruction.invalid_arguments", str(exc)) from None
    except resource_policy.PolicyUnavailable as exc:
        raise InstructionError("instruction.owner_unavailable", str(exc)) from exc
    required = _held_credentials(required, context, service=service)
    if required:
        evidence = {} if instruction_id else None
        errors = _credential_errors(declaration, context, required, service=service, evidence=evidence)
        for requirement in required:
            if errors[requirement] is not None:
                raise errors[requirement]
        if evidence and evidence.get("requests"):
            from management_common.principal import actor_principal
            from management_portal.resources import get_resource_service

            service = service if service is not None else get_resource_service()
            binding = evidence["binding"]
            from management_portal.resources.errors import ResourceOperationError

            try:
                proof = service.prepare_instruction_retention(
                    binding.subject_ref, binding.context, instruction_id=instruction_id,
                    instruction=declaration.name, requests=evidence["requests"],
                )
            except (PermissionError, ResourceOperationError) as exc:
                if isinstance(exc, ResourceOperationError) and exc.http_status != 403:
                    raise
                raise _denied(declaration, str(exc)) from exc
            if proof:
                return Retention(service, actor_principal(context.caller).id, proof)

def authorize_reads(
    declaration: InstructionDeclaration,
    arguments: list[Mapping[str, Any]],
    context: InstructionContext,
) -> list[InstructionError | None]:
    """Authorize independent reads from one current policy and subject.

    Results preserve argument order and local denials. Nothing is cached across
    requests; a policy or authorization service failure still refuses the read.
    """

    if declaration.mutates:
        raise ValueError("authorize_reads only accepts read instructions")
    if not arguments:
        return []
    try:
        policy = resource_policy.snapshot()
    except resource_policy.PolicyUnavailable as exc:
        raise InstructionError("instruction.owner_unavailable", str(exc)) from exc
    errors: list[InstructionError | None] = [None] * len(arguments)
    resolver = _target_resolver(policy, context)
    requirements: list[list[resource_policy.ResolvedRequirement]] = []
    for index, args in enumerate(arguments):
        try:
            requirements.append(resource_policy.requirements(declaration.name, args, policy=policy, resolve_target=resolver))
        except resource_policy.Unresolved as exc:
            errors[index] = InstructionError("instruction.invalid_arguments", str(exc))
            requirements.append([])
    requests = list(dict.fromkeys(pair for pairs in requirements for pair in pairs))
    if not requests:
        return errors

    by_request = _credential_errors(declaration, context, requests)
    for index, pairs in enumerate(requirements):
        for requirement in pairs:
            if by_request[requirement] is not None:
                errors[index] = by_request[requirement]
                break
    return errors


def _denied(declaration: InstructionDeclaration, message: str, **options: Any) -> InstructionError:
    """A denied read looks like a missing object (decision_898b8911a2ff "返回格式")."""

    if not declaration.mutates:
        return InstructionError("instruction.not_found", message, **options)
    return InstructionError("instruction.forbidden", message, **options)

    def read(self):
        # No process-local cache: the next request observes the committed value.
        return decode(self.registry.get(COLLECTION, ID))

    def update(self, *, actor, expected_version, upsert, remove, parents, authorize_current, remove_types=()):
        identity = require_identity(actor)
        remove_types = list(remove_types)
        event_id = uuid.uuid4().hex
        event = {'audit_id': event_id, 'actor': actor, 'expected_version': expected_version,
                 'upsert': copy.deepcopy(upsert), 'remove': copy.deepcopy(remove),
                 **({'remove_types': remove_types} if remove_types else {}),
                 'created_at': datetime.now(timezone.utc).isoformat()}
        try:
            if type(expected_version) is not int or expected_version < 0:
                raise ValueError('expected_version must be a nonnegative integer')
            if not isinstance(upsert, dict) or not isinstance(remove, list) or not (upsert or remove or remove_types):
                raise ValueError('Provide upsert, remove and/or remove_types')
            if any(not isinstance(n, str) or not n for n in [*upsert, *remove]) or len(set(remove)) != len(remove):
                raise ValueError('Invalid instruction names')
            if any(not isinstance(kind, str) or not kind for kind in remove_types) or len(set(remove_types)) != len(remove_types):
                raise ValueError('Invalid resource types to remove')
            if set(upsert) & set(remove):
                raise ValueError('Cannot upsert and remove the same instruction')
            normalized = {name: validate_requirements(name, items) for name, items in upsert.items()}
            with self.registry.writer(COLLECTION, AUDIT) as writer:
                current = decode(writer.get(COLLECTION, ID))
                # Authorize against the locked BEFORE policy, never against
                # client-supplied changes or a snapshot from before this lock.
                authorize_current(resource_policy.Snapshot.from_dict(current))
                if current['version'] != expected_version:
                    raise ResourceVersionConflict('ISA policy version changed', expected_version=expected_version, current_version=current['version'])
                if set(remove) - set(instruction_catalog()) - set(current['protected']):
                    raise ValueError('Unknown instruction in remove')
                needed = {**current['protected'], **normalized}
                for name in remove:
                    needed.pop(name, None)
                kinds = set(current['b_types']) | {kind for items in normalized.values() for item in items for kind in item.get('types', [])}
                # A type leaves the protected resource set only when no
                # protected instruction names it and no remaining type
                # inherits through it (ET 2026-10-12).
                if set(remove_types) - kinds:
                    raise ValueError('Unknown resource type in remove_types')
                kept = grow_b(kinds - set(remove_types), parents)
                held = set(remove_types) & (set(kept) | set(referenced_types(needed)))
                if held:
                    raise ValueError(f'仍被受保护 ISA 引用或被其他类型继承：{"、".join(sorted(held))}')
                value = {'schema': SCHEMA, 'version': current['version'] + 1,
                         'protected': dict(sorted(needed.items())), 'b_types': kept,
                         'updated_at': event['created_at'], 'updated_by': {'kind': identity.kind, 'id': identity.id}, 'audit_id': event_id}
                decode(value)
                writer.put(COLLECTION, ID, value)
                writer.put(AUDIT, event_id, {**event, 'status': 'committed', 'before_version': current['version'], 'version': value['version']})
                return value
        except Exception as exc:
            with self.registry.writer(AUDIT) as writer:
                writer.put(AUDIT, event_id, {**event, 'status': 'rejected', 'reason': str(exc), 'error_type': type(exc).__name__})
            raise


