def _subject(self, connection: Any, subject_ref: str, context: ExecutionContext | None = None) -> Any:
    # A decision reads one database snapshot. Reuse its subject rows while
    # still checking expiry and the caller's execution context on every use.
    memo = self.store.memo()
    key = ("subject_row", subject_ref)
    row = memo.get(key)
    if row is None:
        row = connection.execute('SELECT * FROM auth_subjects WHERE id=%s', (subject_ref,)).fetchone()
        if row is not None:
            row = decode_times(row, ('expires_at', 'created_at'), format='seconds')
            memo[key] = row
    if row is None:
        raise ResourceOperationError("authorization.invalid_subject", "实际权限主体不存在", 403)
    if row["revoked"] or row["expires_at"] <= self.clock():
        raise ResourceOperationError("authorization.expired_subject", "实际权限主体已撤销或过期", 403)
    if context is not None:
        if not isinstance(context, ExecutionContext) or row["executor"] != context.principal_id or row["execution_id"] != context.execution_id:
            raise ResourceOperationError("authorization.subject_mismatch", "实际权限主体与认证执行不匹配", 403)
        if context.expires_at <= self.clock():
            raise ResourceOperationError("authorization.authentication_expired", "执行认证已过期", 403)
    return row

    return resolved[subject_ref]

