    # executor's (ET 2026-10-12): A asking B means B acts as A, and a chain
    # A→B→C carries A's authority on.  Several initiators (a Mailbox group)
    # give the union of their authority.  Work nobody delegated runs with
    # the executor's own credentials.
    if user_message and (len(sources) != 1 or actor_principal(sources[0][0]).kind != "user"):
        raise ResourceOperationError("authorization.invalid_sources", "User 消息必须来自真实 User 主体", 403)
    if not sources:
        return self._root(connection, executor) if root is None else root
    principal = self.store.object(connection, "principal", executor)
    if not principal or not principal["active"]:
        return Descriptor()
    descriptor = sources[0][1]
    for _, source in sources[1:]:
        descriptor = union(descriptor, source)
    return descriptor

