def authorize(self, subject_ref: str, resource_id: str, level: str, context: ExecutionContext) -> dict:
    return self.authorize_many(subject_ref, [(resource_id, level)], context)[0]

def authorize_many(self, subject_ref: str, requests: Sequence[tuple[str, str]], context: ExecutionContext) -> list[dict]:
    if not isinstance(requests, (list, tuple)) or len(requests) > 1000 or any(not isinstance(request, (list, tuple)) or len(request) != 2 or any(not isinstance(item, str) or not item for item in request) for request in requests):
        raise ValueError("Authorization batches require at most 1000 explicit resource/level pairs")
    decisions = [{
        "allowed": False, "reason_code": "authorization.denied", "decision_id": "authorization_decision_" + secrets.token_hex(12),
        "subject_ref": subject_ref, "resource_id": resource_id, "required": level,
    } for resource_id, level in requests]
    if not decisions:
        return decisions
    if not isinstance(context, ExecutionContext):
        for decision in decisions:
            decision["reason_code"] = "authorization.context_required"
        return decisions
    with self.store.transaction() as connection:
        try:
            row = self._subject(connection, subject_ref, context)
        except ResourceOperationError as exc:
            if exc.http_status != 403:
                raise
            for decision in decisions:
                decision["reason_code"] = exc.code
            return decisions
        targets = self.store.resources(connection, (resource_id for resource_id, _ in requests))
        principal = self.store.object(connection, "principal", row["executor"])
        pending = []
        for decision in decisions:
            target = targets.get(decision["resource_id"])
            if target is None:
                decision["reason_code"] = "authorization.unknown_resource"
            elif not principal or not principal["active"] or not target.active:
                decision["reason_code"] = "authorization.inactive"
            else:
                try:
                    required = Level.parse(decision["required"])
                    if required == Level.none:
                        raise ValueError("A required permission level must be positive")
                except ValueError:
                    decision["reason_code"] = "authorization.invalid_level"
                else:
                    pending.append((decision, target, required))
        if pending:
            eligible = {target.id: target for _, target, _ in pending}
            graph = self._target_graph(connection, eligible, seeded=eligible)
            try:
                descriptor = self._descriptor(connection, subject_ref, graph=graph)
            except ResourceOperationError as exc:
                if exc.http_status != 403:
                    raise
                for decision, _, _ in pending:
                    decision["reason_code"] = exc.code
            else:
                for decision, target, required in pending:
                    effective = descriptor.level(target)
                    decision.update(level=int(effective), required_level=int(required), allowed=effective >= required)
                    decision["reason_code"] = "authorization.allowed" if decision["allowed"] else "authorization.insufficient_level"
        return decisions

def reaching_levels(self, principal_id: str, resource_ids: Sequence[str], *,
                    subject_ref: str = "", context: ExecutionContext | None = None) -> dict[str, int]:
    """The level a principal reaches on the requested resources.

    Inside a turn ``subject_ref`` is its execution subject, so the answer is
    what the turn may do: the union of its initiators' current levels, or
    the executor's own credentials when it has no initiator. Reads the
    requested resources' shared ancestor closure once.
    """
    if not isinstance(resource_ids, (list, tuple)) or len(resource_ids) > 1000 or any(not isinstance(item, str) or not item for item in resource_ids):
        raise ValueError("Level queries take at most 1000 resource IDs")
    if not resource_ids:
        return {}
    with self.store.transaction() as connection:
        if subject_ref:
            if not isinstance(context, ExecutionContext):
                raise ResourceOperationError("authorization.context_required", "缺少认证执行上下文", 403)
            if self._subject(connection, subject_ref, context)["executor"] != principal_id:
                raise ResourceOperationError("authorization.subject_mismatch", "实际权限主体与认证执行不匹配", 403)
        graph = self._target_graph(connection, resource_ids)
        descriptor = (self._descriptor(connection, subject_ref, graph=graph) if subject_ref else
                      self._target_root(connection, principal_id, graph))
        return {identifier: int(descriptor.exceptions.get(identifier, Level.none)) for identifier in resource_ids}

