def private_resources(resources, named, *, order=None) -> frozenset[str]:
    """``named`` private resources and the resources all of whose parents are private."""
    parents = {identifier: [parent for parent in value.get('permission_parents', []) if parent in resources]
               for identifier, value in resources.items()}
    if order is None:
        children = {identifier: [] for identifier in resources}
        pending = {identifier: len(items) for identifier, items in parents.items()}
        for identifier, items in parents.items():
            for parent in items:
                children[parent].append(identifier)
        queue = deque(identifier for identifier, count in pending.items() if not count)
        order = []
        while queue:
            identifier = queue.popleft()
            order.append(identifier)
            for child in children[identifier]:
                pending[child] -= 1
                if not pending[child]:
                    queue.append(child)
    private = set(named) & resources.keys()
    for identifier in order:
        if identifier not in private and parents[identifier] and all(parent in private for parent in parents[identifier]):
            private.add(identifier)
    return frozenset(private)


