class CredentialSets:
    """Each principal's current credential list, in ``auth_credential_sets``.

    ``auth_principals.credential_revision`` names the list by content hash.
    Callers change the list and the pointer in one transaction, so a pointer
    without its matching list is damaged state and fails closed.
    """

    def read(self, connection, principal_id: str, revision: str) -> list[dict]:
        holder = _holder(principal_id)
        if not revision:
            return []
        row = connection.execute(
            'SELECT revision,credentials FROM auth_credential_sets WHERE principal_id=%s', (holder,)).fetchone()
        if row is None or row[0] != revision:
            raise _unavailable()
        return row[1]

    def read_all(self, connection) -> dict[str, list[dict]]:
        """Every principal's current list in one query."""
        result = {}
        for row in connection.execute('''SELECT p.id,p.credential_revision,c.revision,c.credentials
                FROM auth_principals p LEFT JOIN auth_credential_sets c ON c.principal_id=p.id'''):
            if not row[1]:
                result[row[0]] = []
            elif row[1] != row[2]:
                raise _unavailable()
            else:
                result[row[0]] = row[3]
        return result

    @staticmethod
    def holders(connection, resource_id: str) -> list[str]:
        """Principals whose stored list has a credential on ``resource_id``."""
        rows = connection.execute(
            'SELECT principal_id FROM auth_credential_sets WHERE credentials @> %s::jsonb ORDER BY principal_id',
            (json.dumps([{'resource_id': resource_id}]),))
        return [row[0] for row in rows]

    def write(self, connection, principal_id: str, credentials: list[dict]) -> str:
        """Store the list; the caller points the principal at the returned revision."""
        holder = _holder(principal_id)
        revision = credential_revision(holder, credentials)
        connection.execute('''INSERT INTO auth_credential_sets VALUES (%s,%s,%s::jsonb) ON CONFLICT(principal_id)
            DO UPDATE SET revision=excluded.revision,credentials=excluded.credentials''',
            (holder, revision, json.dumps(credentials, ensure_ascii=False)))
        return revision


def resolve_credentials(store, connection, principal_id: str) -> Descriptor:
    return resolve_coverage(store, connection, principal_id).descriptor


def resolve_coverage(store, connection, principal_id: str, *, explain: bool = False) -> Coverage:
    """A principal's effective credentials over explicit resource parents."""
    principal = store.object(connection, 'principal', principal_id)
    if not principal or not principal.get('active'):
        return Coverage()
    graph = store.coverage_graph(connection)
    return graph.expand(permission_roots(store, connection, principal_id, graph.resources), explain=explain)

class ArtifactStore:
    def __init__(self, root: Path | None = None):
        configured = os.environ.get("PORTAL_EFFECT_ARTIFACT_ROOT")
        if root is None and configured is None:
            configuration = Path(__file__).resolve().parents[2] / "config" / "effect_artifacts.json"
            configured = json.loads(configuration.read_text())["root"]
        self.root = root if root is not None else Path(str(configured or ""))
        if not self.root.is_absolute():
            raise ValueError("Effect artifact root must be an absolute configured directory")

    def _scope(self, lineage_id: str, activation_key: str) -> Path:
        return self.root / hashlib.sha256(lineage_id.encode()).hexdigest() / hashlib.sha256(activation_key.encode()).hexdigest()

    def put(self, lineage_id: str, activation_key: str, value: Any, *, purpose: str) -> dict[str, Any]:
        if purpose not in {"recovery", "output"}:
            raise ValueError("invalid Effect artifact purpose")
        data = json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode()
        digest = hashlib.sha256(data).hexdigest()
        directory = self._scope(lineage_id, activation_key) / purpose
        directory.mkdir(parents=True, exist_ok=True, mode=0o700)
        for parent in (directory.parent, directory.parent.parent, self.root, self.root.parent):
            with _directory(parent) as handle:
                os.fsync(handle)
        path = directory / (digest + ".json")
        descriptor, temporary = tempfile.mkstemp(dir=directory)
        try:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
            with _directory(directory) as handle:
                os.fsync(handle)
        finally:
            Path(temporary).unlink(missing_ok=True)
        return {"schema": "dirtybase.effect-artifact.v1", "lineage_id": lineage_id,
                "activation_key": activation_key, "purpose": purpose, "sha256": digest,
                "size_bytes": len(data), "content_type": "application/json"}

    def read(self, lineage_id: str, activation_key: str, reference: dict[str, Any]) -> Any:
        digest = str(reference.get("sha256") or "")
        purpose = reference.get("purpose")
        if (reference.get("schema") != "dirtybase.effect-artifact.v1" or
                reference.get("lineage_id") != lineage_id or reference.get("activation_key") != activation_key or
                purpose not in {"recovery", "output"} or len(digest) != 64 or
                any(c not in "0123456789abcdef" for c in digest)):
            raise ValueError("invalid or foreign Effect artifact reference")
        data = (self._scope(lineage_id, activation_key) / str(purpose) / (digest + ".json")).read_bytes()
        if len(data) != reference.get("size_bytes") or hashlib.sha256(data).hexdigest() != digest:
            raise ValueError("Effect artifact integrity check failed")
        return json.loads(data)

    def clear_recovery(self, lineage_id: str, activation_key: str) -> None:
        path = self._scope(lineage_id, activation_key) / "recovery"
        if path.exists():
            shutil.rmtree(path)


@contextmanager
def _directory(path: Path):
    descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        yield descriptor

def _handle(self, scope: str, digest: str) -> str:
    payload = f"{scope}\0{digest}".encode("utf-8")
    signature = hmac.new(
        self._capability_key(),
        payload,
        hashlib.sha256,
    ).hexdigest()
    return f"{ARTIFACT_HANDLE_PREFIX}{signature}"

@staticmethod
def _validate_handle(handle: object) -> str:
    clean = str(handle or "").strip().lower()
    if not ARTIFACT_HANDLE_RE.fullmatch(clean):
        raise ValueError("Invalid Harness artifact handle")
    return clean

def _artifact_path(self, handle: str) -> Path:
    clean = self._validate_handle(handle)
    directory = self.root / "artifacts" / clean[4:6]
    return directory / f"{clean}.json"

def _scope_dir(self, scope: str) -> Path:
    digest = hashlib.sha256(scope.encode("utf-8")).hexdigest()
    return self.root / "scopes" / digest

def _grant_locked(self, scope: str, handle: str) -> None:
    scope_dir = self._scope_dir(scope)
    scope_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
    marker = scope_dir / handle
    if marker.exists():
        return
    self._atomic_write(marker, b"")

@staticmethod
def _read_envelope(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise KeyError("Harness artifact was not found") from exc
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError("Harness artifact could not be read") from exc
    if not isinstance(payload, dict):
        raise RuntimeError("Harness artifact envelope is invalid")
    return payload

@staticmethod
def _validate_envelope(
    envelope: dict[str, Any],
    *,
    expected_handle: str,
) -> None:
    if (
        envelope.get("schema") != "portal.harness-artifact"
        or int(envelope.get("schema_version") or 0) != 1
        or str(envelope.get("handle") or "") != expected_handle
    ):
        raise RuntimeError("Harness artifact identity is invalid")
    content = str(envelope.get("content") or "")
    digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
    if digest != str(envelope.get("sha256") or ""):
        raise RuntimeError("Harness artifact content digest is invalid")

@staticmethod
def _atomic_write(path: Path, payload: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{secrets.token_hex(8)}.tmp"
    )
    descriptor = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL,
        0o600,
    )
    try:
        os.write(descriptor, payload)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    try:
        os.replace(temporary, path)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
