function create(options = {}) {
  const id = String(options.id || "home").trim();
  const context = options.context && typeof options.context === "object" ? options.context : {};
  const tree = normalizeTree(options.tree || {});
  const records = new Map();
  let mounted = false;
  let generation = 0;
  let activationQueued = false;
  let activationReady = false;

  function isVisible(record) {
    for (let current = record; current; current = records.get(current.parentId)) {
      if (panelVisibility.get(current.root) === false) return false;
    }
    return true;
  }

  function connect(record) {
    const { component, root } = record;
    mark(record, "mounting");
    try {
      const result = component.connect?.({
        root, context, signal: record.abortController.signal,
        component: Object.freeze({ id: record.id, parentId: record.parentId }),
      });
      if (result && typeof result.then === "function") {
        result.then(value => {
          retainCleanup(record, value);
          if (mounted && record.generation === generation) mark(record, "ready");
        }).catch(error => {
          console.error(window.PortalI18n.text`Home component ${record.id} failed to connect`, error);
          if (mounted && record.generation === generation) mark(record, "error", error);
        });
      } else {
        retainCleanup(record, result);
        mark(record, "ready");

function activateVisible() {
  activationQueued = false;
  if (!mounted || !activationReady) return;
  records.forEach(record => {
    if (record.status === "deferred" && isVisible(record)) connect(record);
  });
}

function visibilityChanged() {
  if (activationQueued || !mounted) return;
  activationQueued = true;
  // Finish the whole nested layout transaction before starting any reads.
  queueMicrotask(activateVisible);
}

function publish(record) {
  window.dispatchEvent(new CustomEvent("portal:home-component-state", {
    detail: Object.freeze({
      pageId: id,
      componentId: record.id,
      parentId: record.parentId,
      status: record.status,
    }),
  }));
}

function mark(record, status, error = null) {
  record.status = status;
  record.error = error;
  if (record.root instanceof Element) {
    record.root.dataset.homeComponentState = status;
  }
  publish(record);
}

function retainCleanup(record, value) {
  const cleanup = typeof value === "function"
    ? value
    : typeof value?.destroy === "function" ? () => value.destroy() : null;
  if (!cleanup) return;
  if (!mounted || record.generation !== generation) cleanup();
  else record.cleanup = cleanup;
}

function mountNode(component, parentRoot) {
  const root = resolveRoot(component.root, parentRoot);
  const record = {
    id: component.id,
    parentId: component.parentId,
    component,
    root,
    status: "mounting",
    error: null,
    cleanup: null,
    abortController: new AbortController(),
    generation,
  };
  records.set(record.id, record);
  root?.addEventListener("portal:home-panel-lifecycle", visibilityChanged);
  if (!root && component.required) {
    mark(record, "error", new Error(`Home component root not found: ${component.id}`));
  } else if (component.loadPolicy === "when-visible" && (!activationReady || !isVisible(record))) {
    mark(record, "deferred");
  } else {
    connect(record);
  }
  component.children.forEach(child => mountNode(child, root || parentRoot));
}

function mount() {
  if (mounted) return controller;
  mounted = true;
  generation += 1;
  activationReady = typeof options.ready !== "function";
  mountNode(tree, resolveRoot(options.root, document));
  if (!activationReady) {
    const epoch = generation;
    Promise.resolve().then(() => options.ready(context)).then(() => {
      if (!mounted || epoch !== generation) return;
      activationReady = true;
      activateVisible();
    }).catch(error => {
      if (!mounted || epoch !== generation) return;
      records.forEach(record => {
        if (record.status === "deferred") mark(record, "error", error);
      });
    });
  }

function destroy() {
  if (!mounted) return;
  mounted = false;
  [...records.values()].reverse().forEach(record => {
    record.root?.removeEventListener("portal:home-panel-lifecycle", visibilityChanged);
    record.abortController.abort();
    try { record.cleanup?.(); } catch (error) {
      console.error(window.PortalI18n.text`Home component ${record.id} failed to destroy`, error);
    }
    if (record.root instanceof Element) delete record.root.dataset.homeComponentState;
    record.status = "destroyed";
    publish(record);
  });
  records.clear();
}

class RouterPolicy:
    def __init__(self, verifier: PortalSessionAuthority, dev_users: set[str]):
        self.verifier = verifier
        self.dev_users = {str(item).strip() for item in dev_users if str(item).strip()}

    def default_backend(self, actor: str, valid_backends: set[str] | None = None) -> str:
        desired = "dev" if str(actor or "").strip() in self.dev_users else "release"
        valid = set(valid_backends or {"dev", "release"})
        if desired in valid:
            return desired
        if "release" in valid:
            return "release"
        if "dev" in valid:
            return "dev"
        return sorted(valid)[0] if valid else ""

    def preference(
        self,
        actor: str,
        cookie_header: str,
        valid_backends: set[str] | None = None,
    ) -> str:
        cookie_actor, backend = _decode_deployment_preference(
            _cookie_value(cookie_header, DEPLOYMENT_PREFERENCE_COOKIE)
        )
        valid = set(valid_backends or {"dev", "release"})
        return backend if cookie_actor == str(actor or "").strip() and backend in valid else ""

    def select(
        self,
        path: str,
        cookie_header: str,
        valid_backends: set[str] | None = None,
    ) -> str:
        valid = set(valid_backends or {"dev", "release"})
        clean_path = urlsplit(str(path or "/")).path
        if (
            clean_path.startswith("/api/auth/passkeys/")
            or clean_path.startswith("/api/auth/password-reset/")
            or clean_path.startswith("/api/account/")
            or clean_path in {
                "/forgot-password",
                "/reset-password",
                "/settings.html",
                "/static/portal_passkeys.js",
                "/static/portal_ui_primitives.js",
                "/static/settings.css",
                "/static/settings.js",
            }
        ) and "dev" in valid:
            return "dev"
        actor = self.verifier.verify_cookie(cookie_header)
        if actor:
            return self.preference(actor, cookie_header, valid) or self.default_backend(actor, valid)
        if clean_path in {"/login", "/login/verify"} and "dev" in valid:
            return "dev"
        return self.default_backend("", valid)

def _proxy(self) -> None:
    if not self.path.startswith("/") or urlsplit(self.path).scheme:
        return self._json(400, {"error": "invalid request target"})
    transfer_encoding = str(self.headers.get("Transfer-Encoding") or "").strip().lower()
    if transfer_encoding and transfer_encoding != "identity":
        return self._json(501, {"error": "chunked request bodies are not supported"})
    try:
        body_length = self._content_length()
    except (TypeError, ValueError) as exc:
        return self._json(400, {"error": str(exc)})

    backends = self.server.current_backends()  # type: ignore[attr-defined]
    backend_name = self.server.policy.select(  # type: ignore[attr-defined]
        self.path,
        self.headers.get("Cookie", ""),
        set(backends),
    )
    backend = backends[backend_name]
    try:
        connection = self._connect(backend)
    except OSError as exc:
        self.log_error("Portal backend unavailable: %s", exc)
        return self._backend_unavailable()
    if connection is None:
        self.close_connection = True
        return
    try:
        connection.putrequest(self.command, self.path, skip_host=True, skip_accept_encoding=True)
        forwarded_for, forwarded_proto = _forwarded_metadata(
            self.client_address[0],
            self.headers,
        )
        for key, value in self.headers.raw_items():
            lower = key.lower()
            if lower in HOP_HEADERS or lower == "x-portal-selected-backend":
                continue
            if lower in {"x-forwarded-for", "x-forwarded-proto"}:
                continue
            connection.putheader(key, value)
        connection.putheader("X-Forwarded-For", forwarded_for)
        connection.putheader("X-Forwarded-Proto", forwarded_proto)
        connection.putheader("X-Portal-Selected-Backend", backend_name)
        connection.endheaders()

        remaining = body_length
        while remaining:
            chunk = self.rfile.read(min(1024 * 1024, remaining))
            if not chunk:
                raise ConnectionError("request body ended before Content-Length")
            connection.send(chunk)
            remaining -= len(chunk)

        response = connection.getresponse()
        self.send_response(response.status, response.reason)
        for key, value in response.getheaders():
            lower = key.lower()
            if lower in HOP_HEADERS or lower in {"server", "date", "x-portal-backend"}:
                continue
            self.send_header(key, value)
        self.send_header("X-Portal-Backend", backend_name)
        self.send_header("Connection", "close")
        self.end_headers()
        if self.command != "HEAD":
            read_chunk = getattr(response, "read1", response.read)
            while True:
                chunk = read_chunk(64 * 1024)
                if not chunk:
                    break
                self.wfile.write(chunk)
                self.wfile.flush()
    except (BrokenPipeError, ConnectionResetError):
        pass
    except Exception as exc:
        if not self.wfile.closed:
            try:
                self.log_error("Portal backend unavailable: %s", exc)
                self._json(502, _public_backend_error())
            except Exception:
                pass
    finally:
        connection.close()
        self.close_connection = True

async def portal_http(request: Request) -> StreamingResponse:
    body = tempfile.SpooledTemporaryFile(max_size=SPOOL_MEMORY_BYTES)
    total = 0
    try:
        async for chunk in request.stream():
            total += len(chunk)
            if total > MAX_REQUEST_BODY_BYTES:
                body.close()
                return _json_error(413, "request body exceeds 205 MiB")
            body.write(chunk)
        body.seek(0)
        app = request.scope.get("app")
        handler_executor = getattr(
            getattr(app, "state", None),
            "http_handler_executor",
            None,
        )
        if handler_executor is None:
            capture = await asyncio.to_thread(_run_sync_handler, request, body)
        else:
            capture = await asyncio.get_running_loop().run_in_executor(
                handler_executor,
                _run_sync_handler,
                request,
                body,
            )
    except Exception as exc:
        if portal._is_json_api_path(request.url.path):
            status, payload = exception_http_error(exc)
            return JSONResponse(payload, status_code=status)
        raise
    finally:
        if not body.closed:
            body.close()
    response = StreamingResponse(
        _body_chunks(capture.body),
        status_code=capture.status,
    )
    response.raw_headers = capture.headers
    return response

async def instruction_execute(request: Request):
    """The one instruction address (decision_898b8911a2ff “调用入口”)."""

    from .hatg import routing
    from .hatg.contracts import ERROR_STATUS, InstructionCall, InstructionContext, InstructionError, failed_result
    from .hatg.kernel import new_instruction_id

    caller, entry = await asyncio.to_thread(_instruction_principal, request)
    if not caller:
        # An agent that arrives without credentials learns where the joining and calling rules are.
        return _json_error(401, "需要登录，或使用有效的 User / Resident 凭证",
                           details={"guide": "/guide/agent.md"})
    if entry == "web" and not _same_origin(request):
        return _json_error(403, "跨站请求被拒绝")
    try:
        subject = _authorization_subject(request, caller, entry)
    except (TypeError, ValueError, PermissionError) as exc:
        return _json_error(403, str(exc) or "授权上下文无效")
    payload = None
    try:
        payload = await request.json()
        call = InstructionCall.from_payload(payload)
        from management_common.principal import actor_principal
        execution_id = _execution_id(request, entry) if actor_principal(caller).kind == "resident" else ""
        context = InstructionContext(caller=caller, entry=entry, execution_id=execution_id)
        declaration = routing.declaration_for(call.instruction)
    except InstructionError as exc:
        name = str(payload.get("instruction") or "") if isinstance(payload, dict) else ""
        return JSONResponse(failed_result(new_instruction_id("entry"), name, exc).to_payload(),
                            status_code=ERROR_STATUS.get(exc.code, 400))
    except Exception as exc:  # noqa: BLE001 - malformed JSON or call
        name = str(payload.get("instruction") or "") if isinstance(payload, dict) else ""
        error = InstructionError("instruction.invalid_arguments", str(exc) or "调用格式无效")
        return JSONResponse(failed_result(new_instruction_id("entry"), name, error).to_payload(), status_code=400)
    from management_common.authorization_context import authorization_scope

    if not declaration.streaming:
        executor = getattr(request.app.state, "instruction_executor", None)
        loop = asyncio.get_running_loop()

        def execute():
            with authorization_scope(subject):
                return routing.execute(call, context)

        result = await loop.run_in_executor(executor, execute)
        body = result.to_payload()

async def events() -> AsyncIterator[bytes]:
    from .hatg.socket_rpc import StreamCancellation

    queue: asyncio.Queue = asyncio.Queue(maxsize=16)
    loop = asyncio.get_running_loop()
    stop = threading.Event()
    cancellation = StreamCancellation()

    def publish(item) -> bool:
        if stop.is_set():
            return False
        pending = asyncio.run_coroutine_threadsafe(queue.put(item), loop)
        while not stop.is_set():
            try:
                pending.result(timeout=0.1)
                return True
            except FutureTimeoutError:
                continue
        pending.cancel()
        return False

    def pump() -> None:
        try:
            with authorization_scope(subject):
                for batch in routing.stream(call, context, cancellation=cancellation):
                    if not publish(("batch", batch)):
                        return
            publish(("end", None))
        except Exception as exc:  # noqa: BLE001
            if not stop.is_set():
                from .hatg.contracts import normalize_error

                publish(("error", normalize_error(exc).to_dict()))

    worker = loop.run_in_executor(getattr(request.app.state, "sse_payload_executor", None), pump)
    try:
        yield b"retry: 3000\n\n"
        while True:
            try:
                kind, value = await asyncio.wait_for(queue.get(), timeout=SSE_HEARTBEAT_SECONDS)
            except asyncio.TimeoutError:
                yield _sse("heartbeat", {"at": portal.time.time()})
                continue
            if kind == "batch":
                cursor = value[-1].get("cursor") if value and isinstance(value[-1], dict) else None
                yield _sse("batch", {"items": value}, event_id=str(cursor or ""))
            elif kind == "error":
                yield _sse("error", value)
                return
            else:
                yield _sse("end", {})
                return
    finally:
        stop.set()
        cancellation.cancel()
        worker.cancel()

def list_instructions(category: str = "") -> list[dict[str, Any]]:
    items = []
    for name in sorted(instruction_catalog()):
        declaration = instruction_catalog()[name]
        if category and declaration.category != category:
            continue
        summary = declaration.summary()
        if name == "RunResourceAction":
            summary["resource_actions"] = _resource_actions()
        items.append(summary)
    return items


