def login(self, request, parsed, actor):
    if not self.same_origin(request):
        return self.empty(request, 403)
    form = self.bounded_form(request)
    username = form.get("username", "").strip()
    password = form.get("password", "")
    if self.verify_credentials(username, password) and self.user_allowed(username):
        try:
            requires_two_factor = self.two_factor().enabled(username)
        except RuntimeError as exc:
            print(f"Portal two-factor state error: {exc}", file=sys.stderr)
            return self.empty(request, 503)
        if requires_two_factor:
            challenge_token = self.start_login_challenge(username)
            request.send_response(302)
            self.set_login_challenge_cookie(request, challenge_token)
            request.send_header("Location", "/login/verify")
            request.end_headers()
            return
        token = self.issue_session_token(username)
        request.send_response(302)
        self.set_session_cookie(request, token)
        request.send_header("Location", "/")
        request.end_headers()
    else:
        request.send_response(302)
        request.send_header("Location", "/login?error=1")
        request.end_headers()

def login_verify(self, request, parsed, actor):
    if not self.same_origin(request):
        return self.empty(request, 403)
    form = self.bounded_form(request)
    challenge_token = self.request_cookie(request, self.login_challenge_cookie)
    try:
        verified = self.verify_login_challenge(challenge_token, form.get("code", ""))
    except RuntimeError as exc:
        print(f"Portal two-factor verification error: {exc}", file=sys.stderr)
        return self.empty(request, 503)
    if verified and self.user_allowed(verified[0]):
        username, factor = verified
        token = self.issue_session_token(username)
        self.access().audit(
            username, "two_factor_login_succeeded", target=username,
            details={"factor": factor},
        )
        request.send_response(302)
        self.set_session_cookie(request, token)
        self.clear_login_challenge_cookie(request)
        request.send_header("Location", "/")
        request.end_headers()
        return
    request.send_response(302)
    if not self.login_challenge_username(challenge_token):
        self.clear_login_challenge_cookie(request)
        request.send_header("Location", "/login?error=1")
    else:
        request.send_header("Location", "/login/verify?error=1")
    request.end_headers()

def issue(
    self,
    username: str,
    *,
    max_age: int,
    now: int | None = None,
) -> str:
    actor = str(username or "").strip()
    issued_at = int(time.time() if now is None else now)
    with self._lock:
        self._reload()
        if (actor not in self._users and not self.access_store.is_configured(actor)) or not self.access_store.is_active(actor):
            raise PermissionError("Portal user is not active")
        payload = {
            "v": SESSION_TOKEN_VERSION,
            "u": actor,
            "iat": issued_at,
            "exp": issued_at + max(60, int(max_age)),
            "sv": self.access_store.session_version(actor),
            "nonce": secrets.token_urlsafe(12),
        }
        payload_b64 = _b64url_encode(
            json.dumps(
                payload,
                ensure_ascii=False,
                separators=(",", ":"),
            ).encode("utf-8")
        )
        signature = _b64url_encode(
            hmac.new(
                self._signing_key,
                payload_b64.encode("ascii"),
                hashlib.sha256,
            ).digest()
        )
    return f"{payload_b64}.{signature}"

def verify(self, token: str, now: int | None = None) -> str:
    payload_b64, separator, signature = str(token or "").strip().partition(".")
    if not separator or not payload_b64 or not signature:
        return ""
    try:
        with self._lock:
            self._reload()
            expected = _b64url_encode(
                hmac.new(
                    self._signing_key,
                    payload_b64.encode("ascii"),
                    hashlib.sha256,
                ).digest()
            )
            users = set(self._users)
        if not hmac.compare_digest(expected, signature):
            return ""
        payload = json.loads(_b64url_decode(payload_b64).decode("utf-8"))
        username = str(payload.get("u") or "").strip()
        if int(payload.get("v") or 0) != SESSION_TOKEN_VERSION:
            return ""
        if not username or (username not in users and not self.access_store.is_configured(username)):
            return ""
        if not self.access_store.is_active(username):
            return ""
        if int(payload.get("sv", -1)) != self.access_store.session_version(username):
            return ""
        if int(payload.get("exp") or 0) < int(time.time() if now is None else now):
            return ""
        return username
    except Exception:
        return ""

def verify_cookie(self, cookie_header: str, now: int | None = None) -> str:
    return self.verify(cookie_value(cookie_header, SESSION_COOKIE), now=now)

def _owned_message(viewer, chatroom_id, message_id, expected_version):
    message = _trigger_message(chatroom_id, str(message_id or ""))
    if message.get("role") != "user" or not same_actor(message.get("author_id"), viewer):
        raise PermissionError("只能编辑或撤回自己发送的消息")
    if message.get("retracted_at"):
        raise ValueError("消息已经撤回")
    if not expected_version or message.get("segment_id") != expected_version:
        raise ValueError("消息已被修改，请刷新后重试")
    return message


def _save_message_change(room, viewer, previous, current):
    room_id, message_id = room["chatroom_id"], previous["message_id"]
    # Pin pre-existing delivery intents before the first editable version is
    # created, including intents accepted before version pinning was introduced.
    for delivery in room.get("deliveries", []):
        if delivery.get("trigger_message_id") == message_id:
            delivery.setdefault("trigger_segment_id", previous["segment_id"])
    ordinal = _agent_data().chat_message_ordinal(room_id, message_id)
    stored = _agent_data().update_chat_message(room_id, message_id, current)
    # Edits remove obsolete mentions but do not send new notifications or tasks.
    prose = _mention_text(stored.get("content_parts") or [])
    for user, pending in room.get("user_mentions", {}).items():
        if stored.get("retracted_at") or not (_has_user_mention(prose, user) or _has_user_mention(prose, "全员")):
            room["user_mentions"][user] = [item for item in pending if item["message_id"] != message_id]
    if (room.get("last_message") or {}).get("message_id") == message_id:
        room["last_message"]["preview"] = _preview(stored)
        room["last_message"]["mentioned_users"] = [u for u in room["last_message"].get("mentioned_users", [])
            if not stored.get("retracted_at") and (_has_user_mention(prose, u) or _has_user_mention(prose, "全员"))]
    chatroom_store.record_message_change(room_id, message_id)
    return _project_messages(room_id, viewer, [_public_message(stored, ordinal)])[0]


def edit_message(actor, chatroom_id, message_id, content, *, expected_version):
    viewer, clean_id = _actor(actor), _chatroom_id(chatroom_id)
    if not isinstance(content, str) or len(content) > MAX_MESSAGE_CHARS:
        raise ValueError(f"消息正文最多 {MAX_MESSAGE_CHARS} 个字符")
    with _Transaction(clean_id) as rooms:
        room = _require_member(rooms.get(clean_id), viewer)
        previous = _owned_message(viewer, clean_id, message_id, expected_version)
        media = [p for p in previous["content_parts"] if p.get("type") in MEDIA_TYPES]
        if not content.strip() and not media:
            raise ValueError("消息不能为空；如需移除请使用撤回")
        current = {**previous, "content_parts": ([{"type": "text", "text": content}] if content.strip() else []) + media, "edited_at": _now()}
        message = _save_message_change(room, viewer, previous, current)
        rooms[clean_id] = room
    _publish(room, fields=["messages"])
    return {"message": message}


def retract_message(actor, chatroom_id, message_id, *, expected_version):
    viewer, clean_id = _actor(actor), _chatroom_id(chatroom_id)
    with _Transaction(clean_id) as rooms:
        room = _require_member(rooms.get(clean_id), viewer)
        previous = _owned_message(viewer, clean_id, message_id, expected_version)
        current = {**previous, "content_parts": [], "retracted_at": _now()}
        current.pop("quote", None)
        chatroom_store.clear_reactions(clean_id, message_id)
        message = _save_message_change(room, viewer, previous, current)
        rooms[clean_id] = room
    _publish(room, fields=["messages"])
    return {"message": message}

def _resolve_item(
    self,
    actor: str,
    resource_id: str,
) -> tuple[str, dict[str, Any]]:
    clean_id = str(resource_id or "").strip()
    if not clean_id or "/" in clean_id or "\\" in clean_id:
        raise ValueError("root resource ID required")
    resolution = self._resources.resolve(
        clean_id,
        actor=str(actor or ""),
    )
    item = resolution.get("record")
    if not isinstance(item, dict):
        raise TypeError("resource resolution has no record")
    resolved_id = str(item.get("resource_id") or "").strip()
    if resolved_id != clean_id:
        raise ValueError("discussion resource ID mismatch")
    return clean_id, {
        "resource_id": clean_id,
        "title": str(item.get("title") or item.get("filename") or clean_id),
        "project": str(item.get("project") or ""),
        "resource_type": str(item.get("type") or ""),
    }

@contextmanager
def _record_lock(self, resource_id: str) -> Iterator[None]:
    with get_registry_store().writer(DISCUSSION_COLLECTION) as writer:
        self._local.writer = writer
        try:
            yield
        finally:
            self._local.writer = None

def _load_record(self, resource_id: str) -> dict[str, Any]:
    path = f"{DISCUSSION_COLLECTION}/{resource_id}"
    writer = getattr(self._local, "writer", None)
    payload = (
        writer.get(DISCUSSION_COLLECTION, resource_id)
        if writer is not None
        else get_registry_store().get(DISCUSSION_COLLECTION, resource_id)
    )
    if payload is None:
        now = _now_iso()
        return {
            "schema": "dirtybase.resource-discussion.v2",
            "resource_id": resource_id,
            "messages": [],
            "deliveries": [],
            "created_at": now,
            "updated_at": now,
        }
    if not isinstance(payload, dict):
        raise ValueError(f"discussion record must be an object: {path}")
    if payload.get("schema") != "dirtybase.resource-discussion.v2":
        raise ValueError(f"unsupported discussion record schema: {path}")
    if str(payload.get("resource_id") or "") != resource_id:
        raise ValueError(f"discussion resource ID mismatch: {path}")

