def start(
    task_id: str,
    target: Callable[..., Any],
    *args: Any,
    on_error: Callable[[BaseException], None] | None = None,
    daemon: bool = True,
    **kwargs: Any,
) -> bool:
    """Run Portal-owned business code without creating an Execution."""

    clean_id = str(task_id or "").strip()
    if not clean_id:
        raise ValueError("Portal business task id required")
    with _LOCK:
        if clean_id in _ACTIVE:
            return False
        _ACTIVE.add(clean_id)

    def run() -> None:
        try:
            target(*args, **kwargs)
        except BaseException as exc:
            if on_error is not None:
                on_error(exc)
        finally:
            with _LOCK:
                _ACTIVE.discard(clean_id)

    try:
        threading.Thread(
            target=run,
            name=f"portal-business-{clean_id[:80]}",
            daemon=daemon,
        ).start()
    except BaseException:
        with _LOCK:
            _ACTIVE.discard(clean_id)
        raise
    return True


def is_active(task_id: str) -> bool:
    with _LOCK:
        return str(task_id or "").strip() in _ACTIVE

def process_identity() -> dict:
    """Identify this task host across restarts and PID reuse."""
    stat = Path(f"/proc/{os.getpid()}/stat").read_text().rsplit(")", 1)[1].split()
    return {
        "host": socket.gethostname(),
        "boot_id": Path("/proc/sys/kernel/random/boot_id").read_text().strip(),
        "pid_namespace": os.readlink('/proc/self/ns/pid'),
        "pid": os.getpid(),
        "start_ticks": stat[19],
    }


def process_is_alive(owner: dict) -> bool:
    # A different host or unreadable process is not proof of interruption.
    if not owner or owner.get("host") != socket.gethostname():
        return True
    try:
        if owner["boot_id"] != Path("/proc/sys/kernel/random/boot_id").read_text().strip():
            return False
        namespace = os.readlink('/proc/self/ns/pid')
        if owner.get("pid_namespace", namespace) != namespace:
            return True
        stat = Path(f"/proc/{int(owner['pid'])}/stat").read_text().rsplit(")", 1)[1].split()
        return stat[0] != "Z" and stat[19] == str(owner["start_ticks"])
    except FileNotFoundError:
        return False
    except (OSError, KeyError, ValueError, IndexError):
        return True

def start_review(payload: dict, actor: str) -> dict:
    from management_portal import business_tasks

    paper_id = str(payload.get("paper_id") or "").strip()
    if not paper_id:
        raise ValueError("paper_id required")
    clean_actor = str(actor or "").strip()
    for previous in paper_state_store.records("review_jobs", paper_id=paper_id):
        if previous.get("created_by") == clean_actor:
            _settle_interrupted_review(previous)
    with LOCK:
        papers = _all_papers()
        paper = next((p for p in papers if p["id"] == paper_id), None)
        if not paper:
            raise KeyError("paper not found")
        with paper_state_store.locked("review_jobs"):
            active = next(
                (
                    item
                    for item in reversed(paper_state_store.records("review_jobs", paper_id=paper_id))
                    if str(item.get("created_by") or "") == clean_actor
                    and str(item.get("status") or "")
                    in {"queued", "running"}
                ),
                None,
            )
            if active is not None:
                return active
            known_ids = [
                item.get("review_id")
                for item in _all_reviews()
            ]
            known_ids.extend(
                item.get("review_id")
                for item in _all_review_jobs()
            )
            review_id = get_resource_service().new_id(
                "review",
                known_ids,
            )
            job = {
                "job_id": f"paper-review-{secrets.token_hex(6)}",
                "paper_id": paper_id,
                "paper_title": str(paper.get("title") or ""),
                "review_id": review_id,
                "title": str(payload.get("title") or ""),
                "status": "queued",
                "step": "queued",
                "process_owner": business_tasks.process_identity(),
                "created_by": clean_actor,
                "created_at": _now(),
                "updated_at": _now(),
                "error": "",
            }
            paper_state_store.append("review_jobs", job)
    return _start_review_task(job)


