def _recover_paper_collection_job(job: dict, actor: str) -> dict:
    from management_portal import business_tasks
    from management_portal.paper_collector import CONTRACT, require_actor
    from management_portal.paper_projection import input_receipt

    if (not actor or job.get("created_by") != actor or job.get("deleted")
            or job.get("status") not in {"queued", "running"} or job.get("collector_contract") != CONTRACT):
        return job
    try:
        require_actor(actor)
    except PermissionError:
        return job
    job_id = str(job.get("job_id") or "")
    with LOCK, paper_state_store.locked("collector_jobs"):
        current = paper_state_store.get("collector_jobs", job_id)
        if current is None:
            return job
        if (current.get("deleted") or current.get("status") not in {"queued", "running"}
                or current.get("created_by") != actor or current.get("collector_contract") != CONTRACT
                or "existing_paper_ids" not in current
                or business_tasks.is_active(f"paper-collection:{job_id}")):
            return current
        try:
            binding = input_receipt(current.get("invocation") or {})
        except ValueError:
            return current
        if (current["invocation"].get("input_identity_status") == "unconfirmed"
                or not all(binding.get(key) for key in ("resident_id", "lineage_id", "input_message_id"))):
            return current
        owner = current.get("process_owner") or {}
        here = business_tasks.process_identity()
        if owner and owner != here and business_tasks.process_is_alive(owner):
            return current
        # Claim observation under the durable store lock. Never manufacture the
        # original caller's credentials or replay a missing/unconfirmed input.
        current = paper_state_store.merge("collector_jobs", job_id, {"process_owner": here})
    return _start_paper_collection_task(current)

def set_reviewed(payload: dict[str, Any], actor: str) -> dict[str, Any]:
    reviewed = payload.get("reviewed")
    if not isinstance(reviewed, bool):
        raise ValueError("reviewed 应为布尔值")
    key = str(payload.get("project") or "portal")
    block_id = str(payload.get("block") or "")
    _, point, _, _ = _point(key, block_id, actor)
    revision = _read_revision(point)
    if payload.get("read_revision") != revision:
        invalidate(key)
        raise ValueError("内容已变化，请查看最新内容后重新设置审核状态")
    def save(data):
        marks = data["reviews"].setdefault(actor, {}).setdefault(key, {})
        if reviewed:
            marks[block_id] = revision
        else:
            marks.pop(block_id, None)
        return {"block": block_id, "reviewed": reviewed, "read_revision": revision}
    return _change(save)


def mark_read(payload: dict[str, Any], actor: str) -> dict[str, Any]:
    key = str(payload.get("project") or "portal")
    block_id = str(payload.get("block") or "")
    _, point, _, _ = _point(key, block_id, actor)
    revision = _read_revision(point)
    if payload.get("read_revision") != revision:
        return {"read": False, "block": block_id}
    def save(data):
        data["reads"].setdefault(actor, {}).setdefault(key, {})[block_id] = revision
        return {"read": True, "block": block_id, "read_revision": revision}

def _action(payload: dict[str, Any], actor: str) -> dict[str, Any]:
    key, name, block_id = str(payload.get("project") or "portal"), str(payload.get("action") or ""), str(payload.get("block") or "")
    record = project(key, actor, write=True)
    if name == "discuss":
        return _discuss(key, block_id, actor, backend_route_id=_codex_account(payload.get("backend_route_id", "")))
    if name == "stop":
        job_id = str(payload.get("job_id") or "")
        jobs = [j for j in _read_state()["jobs"].values() if j["project"] == key
                and (j["id"] == job_id if job_id else j.get("block") == block_id)
                and j["actor"] == actor and j["status"] in ACTIVE]
        for job in jobs:
            _patch_job(job["id"], cancel_requested=True)
            if job.get("tau_run_id"):
                from tests.framework import api as test_api
                test_api.cancel_run(job["tau_run_id"], actor=actor)
            if job.get("resident_id") and job.get("message_id"):
                resident_handoff.cancel_resident_invocation(job["resident_id"], actor, job["message_id"])
        return {"accepted": True}
    allowed = {"implement": {"improvement"}, "reject": {"improvement", "inconsistency", "direction"},
               "retire": {"design"}, "align-design": {"inconsistency"}, "align-code": {"inconsistency"},
               "approve-direction": {"direction"}, "publish": {"dev"}}
    if name not in {*allowed, *PROJECT_ACTIONS}:
        raise ValueError("未知 WALL 操作")
    if name in PROJECT_ACTIONS and block_id:
        raise ValueError("工程级操作不能指定卡片")
    point = None
    if name == 'reject':
        cleanup_key = digest(f'{key}\0{block_id}')
        if cleanup_key in _read_state()['resident_cleanup']:
            _remove_point(record, block_id, actor)
            cleanup = _try_resident_cleanup(key, actor)
            return {'accepted': True, 'removed': True, 'cleanup': cleanup}
        if any(j['project'] == key and j.get('block') == block_id and j['status'] in ACTIVE
               for j in _read_state()['jobs'].values()):
            raise ValueError('请先等待或停止这个条目的工作')
    if name in allowed:
        _, point, _, _ = _point(key, block_id, actor)
        if point["status"] not in allowed[name]:
            raise ValueError("当前点的状态不支持这项操作")
    if name == "reject":
        _remove_point(record, block_id, actor)
        cleanup = _try_resident_cleanup(key, actor)
        return {"accepted": True, "removed": True, "cleanup": cleanup}
    account = _codex_account(payload.get("backend_route_id", ""))
    job = {"id": "wall-" + secrets.token_hex(8), "project": key, "block": block_id,
           "actor": actor, "action": name, "backend_route_id": account, "status": "queued", "created_at": time.time(),
           "message": str(payload.get("message") or ""), "title": point["title"] if point else PROJECT_ACTIONS[name],
           "source_id": point["source_id"] if point else "", "cancel_requested": False}
    if name == "verify" and payload.get("test_case_ids"):
        job["test_case_ids"] = _related(payload["test_case_ids"])
    def enqueue(data):
        # One click is one task. Distinct blocks remain independently runnable.
        existing = next((j for j in data["jobs"].values() if j["project"] == key and j["actor"] == actor and j.get("block") == block_id and j["action"] == name and j["status"] in ACTIVE), None)
        if existing:
            return existing
        data["jobs"][job["id"]] = job
        return job
    accepted = _change(enqueue)
    _start_job(accepted["id"])
    return {"accepted": True, "job": accepted}

def _request(self, method: str, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    data = None
    headers: dict[str, str] = {}
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json; charset=utf-8"
    req = urllib.request.Request(f"{self.base_url}{path}", data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=180) as resp:
            return self._decode_response(resp.read())
    except urllib.error.HTTPError as exc:
        error = self._decode_response(exc.read()).get("error") or str(exc)
        if exc.code == 503:
            raise KnowledgeArchiveServiceUnavailable(error)
        if exc.code == 400:
            raise ValueError(error)
        if exc.code == 403:
            raise PermissionError(error)
        if exc.code == 404:
            raise KeyError(error)
        raise RuntimeError(error)
    except urllib.error.URLError as exc:
        raise KnowledgeArchiveServiceUnavailable("KnowledgeArchiveAgent 未运行，归档功能暂不可用。") from exc

def _decode_response(self, raw: bytes) -> dict[str, Any]:
    try:
        payload = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError("invalid KnowledgeArchiveAgent response") from exc
    if not isinstance(payload, dict):
        raise RuntimeError("invalid KnowledgeArchiveAgent payload")
    return payload

def semantic_object(value, actor):
    if not isinstance(value, dict) or set(value) != {"ref", "kind", "status", "source", "observed_at"}:
        raise ProjectionError("projection.object", "对象需要 ref、kind、status、source、observed_at")
    if value["status"] not in {"current", "proposed", "simulated", "verified"}:
        raise ProjectionError("projection.object", "对象状态无效")
    if not isinstance(value["kind"], str) or not 0 < len(value["kind"]) <= 120:
        raise ProjectionError("projection.object", "对象种类无效")
    if not isinstance(value["source"], str) or len(value["source"]) > 2048:
        raise ProjectionError("projection.object", "依据须为地址或空字符串")
    if value["status"] == "verified" and not value["source"]:
        raise ProjectionError("projection.evidence_missing", "已验证结果必须提供可读取的依据")
    try:
        stamp = datetime.fromisoformat(value["observed_at"].replace("Z", "+00:00"))
        if stamp.tzinfo is None:
            raise ValueError()
    except (ValueError, TypeError, AttributeError):
        raise ProjectionError("projection.object", "观察时间需要带时区的 ISO 时间") from None
    observe([value["ref"], *([value["source"]] if value["source"] else [])], actor)
    return dict(value)

if path == "/api/workbenches/resource":
    from management_portal.resources import get_resource_service
    service.store.get(app_id, actor)
    operation = payload.get("operation")
    arguments = dict(payload.get("arguments") or {})
    forbidden = {"actor", "registry_root", "automatic", "principal_id"}
    if forbidden.intersection(arguments):
        raise PermissionError("页面不能指定调用身份或内部配置")
    if operation == "resolve":
        address = str(arguments["address"])
        unavailable = {"readable": False, "resource_type": "", "title": "", "portal_url": ""}
        try:
            resolved = get_resource_service().resolve(address, actor=actor)
        except Exception as error:
            if resource_error_http_response(error)[0] not in {403, 404}:
                raise
            return unavailable
        if not resolved.get("exists"):
            return unavailable
        return {
            "readable": True,
            "resource_type": resolved.get("resource_type", ""),
            "title": resolved.get("title") or (resolved.get("record") or {}).get("title", ""),
            "portal_url": resolved.get("portal_url", ""),
        }
    if operation == "read":
        from management_portal.resources.content_payload import content_payload
        address = str(arguments["address"])
        content, content_type, metadata = get_resource_service().read_content(address, actor=actor)
        metadata = {**metadata, "content_sha256": hashlib.sha256(content).hexdigest()}
        if arguments.get("format") == "yaml":
            import yaml
            return {"address": address, "data": yaml.safe_load(content), "metadata": metadata}
        return content_payload(address, content, content_type, metadata)
    if operation == "query":
        return get_resource_service().query(actor=actor, **arguments)
    raise ProjectionError("projection.resource_operation", "页面资源入口仅支持 query/read/resolve")

def dispatch(self, app_id: str, payload: dict, actor: str) -> dict:
    """One HATG ISA call from a Workbench page, bound to the page's Lineage."""
    app = self.store.get(app_id, actor, published=not bool(payload.get("preview")))
    alias = str(payload.get("binding") or "main")
    binding = app["bindings"].get(alias)
    if not binding:
        raise ProjectionError("projection.lineage_unbound", f"Lineage 未绑定：{alias}", 409)
    name = str(payload.get("instruction") or "")
    schema = instruction_schema(name)
    if schema.get("streaming"):
        raise ProjectionError("projection.streaming", "工作台页面不能订阅流式指令，请改为读取一次")
    if schema.get("mutates") and not payload.get("confirmed"):
        raise ProjectionError("projection.confirmation_required", "请先确认工作台请求的 HATG 操作", 409)
    arguments = dict(payload.get("arguments") or {})
    parameters = {item.get("name") for item in schema.get("parameters") or []}
    if "lineage_id" in parameters:
        arguments["lineage_id"] = binding["lineage_id"]
    graph = bound_lineage_graph(binding, actor)
    flow = str(payload.get("flow") or "")
    if flow:
        event_id = binding.get("events", {}).get(flow)
        sources = {item["id"] for item in graph.get("program", {}).get("components", []) if item.get("kind") == "event_source"}
        if name != "TriggerEvent" or not event_id or event_id not in sources:
            raise ProjectionError("projection.event_unbound", f"流程入口未绑定：{flow}", 409)
        arguments["event_source_id"] = event_id
    role = str(payload.get("role") or "")
    if role:
        resident_id = binding.get("residents", {}).get(role)
        if not resident_id or resident_id not in members(graph):
            raise ProjectionError("projection.resident_unbound", f"Resident 未绑定：{role}；请打开工作台设置重新绑定", 409)
        arguments["resident_id"] = resident_id
    referenced = [arguments[key] for key in ("resident_id", "source_resident_id", "target_resident_id") if arguments.get(key)]
    referenced.extend(arguments.get("resident_ids", []))
    for resident_id in referenced:
        if resident_id not in members(graph):
            raise ProjectionError("projection.resident_unbound", f"Resident 未绑定：{resident_id}", 409)
    return isa(actor, name, arguments, key=str(payload.get("idempotency_key") or ""),
               version=payload.get("expected_version"))

def save_generation_result(self, app_id: str, payload: dict, resident_id: str) -> dict:
    allowed = {"job_id", "base_revision", "title", "description", "html", "manifest", "panels", "application"}
    unknown = set(payload) - allowed
    if unknown:
        raise ProjectionError(
            "projection.generation_fields",
            "页面生成结果包含未允许字段：" + "、".join(sorted(unknown)),
        )
    job_id = str(payload.get("job_id") or "")
    changes = {key: payload[key] for key in ("title", "description", "html", "manifest", "panels", "application") if key in payload}
    if not changes.get("manifest") and not str(changes.get("html") or "").strip():
        raise ProjectionError("projection.empty", "设计师必须提交非空页面源码")
    expected_revision = payload.get("base_revision")
    if type(expected_revision) is not int:
        raise ProjectionError("projection.revision", "页面生成结果必须提供整数 base_revision")
    encoded = json.dumps(changes, ensure_ascii=False, sort_keys=True)
    payload_hash = hashlib.sha256(encoded.encode()).hexdigest()
    with self.lock(f"generation:{job_id}"):
        job = self.store.resident_job(job_id, resident_id)
        if job.get("kind") == "reverse" or job.get("workbench_id") != app_id:
            raise ProjectionError("projection.generation_target", "生成任务与目标工作台不匹配", 409)
        if expected_revision != job.get("base_revision"):
            raise ProjectionError("projection.conflict", "提交基线与生成任务不一致", 409)
        receipt = job.get("save_receipt")
        if receipt:
            if receipt.get("payload_hash") != payload_hash:
                raise ProjectionError("projection.generation_replay", "同一生成任务不能提交不同页面结果", 409)
            return dict(receipt)
        pending = job.get("pending_save")
        if pending and (pending.get("payload_hash") != payload_hash or pending.get("saved_by") != resident_id):
            raise ProjectionError("projection.generation_replay", "生成任务已有不同的待确认页面结果", 409)
        current = self.store.get(app_id, resident_id)
        replayed = bool(
            pending
            and current["revision"] == expected_revision + 1
            and all(current.get(key) == value for key, value in changes.items())
        )
        if current["revision"] == expected_revision:
            self.store.updated_manifest(current, changes)
        elif not replayed:
            raise ProjectionError("projection.conflict", "工作台已被其他修改更新，请重新读取后再实现", 409)
        if not pending:
            pending = {"payload_hash": payload_hash, "changes": changes, "saved_by": resident_id}
            job["pending_save"] = pending
            self.store.job(job_id, job["created_by"], job)
        if not replayed:
            saved = self.apply_update(app_id, {**changes, "expected_revision": expected_revision}, resident_id)
        else:
            saved = current
        receipt = {
            "job_id": job_id,
            "workbench_id": app_id,
            "revision": saved["revision"],
            "published_revision": saved.get("published_revision"),
            "payload_hash": payload_hash,
            "saved_by": resident_id,
        }
        job.pop("pending_save", None)
        job["save_receipt"] = receipt
        self.store.job(job_id, job["created_by"], job)
        return dict(receipt)

async feedback(record, payload, guard) {
  guard();
  const object = objects.get(payload.ref);
  if (!object) throw fail("object_unknown", "请先聚焦反馈对象");
  if (object.status === "simulated") throw fail("simulated", "模拟演示不能触发真实操作");
  if (typeof payload.text !== "string" || !payload.text.trim() || payload.text.length > 20000) throw fail("feedback", "请填写反馈内容（最多 20000 字）");
  if (feedbackContext) throw fail("feedback_busy", "正在发送上一条反馈");
  await api.object(object);
  guard();
  await request("facade", { id: app.workbench_id, preview: !!options.preview });
  guard();
  const chat = workbench.getPanel("facade");
  if (!chat) throw fail("resident_unbound", "工作台没有门面对话");
  feedbackContext = { object, anchor: payload.anchor, scene: payload.scene };
  feedbackGuard = guard;
  try {
    const result = await chat.send({ text: payload.text, refs: [], attachments: [] }, { clear: false, focus: false });
    workbench.showPanel("facade");
    return result;
  } finally { feedbackContext = null; feedbackGuard = null; }

async function mountContent(root, app, options = {}) {
  if (!sdkPromise) sdkPromise = fetch("/static/projection_sdk.js").then(response => { if (!response.ok) throw new Error("工作台 SDK 加载失败"); return response.text(); });
  if (!stylesPromise) stylesPromise = Promise.all(["portal_components.css", "portal_design_system.css", "portal_workbench.css"].map(async name => {
    const response = await fetch(`/static/${name}`);
    if (!response.ok) throw new Error("Portal 基础模板加载失败");
    return response.text();
  })).then(styles => styles.join("\n"));
  const [sdk, sharedCss] = await Promise.all([sdkPromise, stylesPromise]);
  const channel = globalThis.PortalUIPrimitives.randomUUID();
  const frame = document.createElement("iframe");
  frame.title = app.title;
  frame.className = "projectionFrame";
  frame.setAttribute("sandbox", "allow-scripts allow-forms");
  frame.referrerPolicy = "no-referrer";
  const assets = options.packageEntry ? applicationAssets(app, options.packageEntry, !!options.preview) : null;
  const documentSource = assets ? await applicationDocument(assets) : new DOMParser().parseFromString(app.html, "text/html");
  const shared = documentSource.createElement("style");
  shared.textContent = `${sharedCss}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font:14px/1.5 system-ui,sans-serif}body{padding:12px}body [hidden]{display:none!important}h1,h2,h3{font-size:16px;margin:0 0 8px}.paneHead{padding:12px;border-bottom:1px solid var(--border);background:var(--panel-2);display:flex;align-items:center;justify-content:space-between;gap:8px}.paneBody{padding:12px;min-width:0}a{color:var(--accent)}`;
  const theme = documentSource.createElement("style");
  theme.id = "portalProjectionTheme"; theme.textContent = themeCss();
  const policy = documentSource.createElement("meta");
  policy.httpEquiv = "Content-Security-Policy";
  policy.content = "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src 'none'; form-action 'none'; base-uri 'none'; frame-src 'none'; object-src 'none'; worker-src " + (assets ? "blob:; script-src-attr 'none'" : "'none'");
  const bootstrap = documentSource.createElement("script");
  bootstrap.dataset.channel = channel;
  bootstrap.dataset.hostDepth = assets ? "2" : "1";
  bootstrap.dataset.icons = JSON.stringify({ icons: window.PortalUIPrimitives.ICONS, aliases: window.PortalUIPrimitives.ICON_ALIASES });
  bootstrap.textContent = sdk;
  documentSource.head.prepend(policy, shared, theme, bootstrap);
  const record = { app, frame, channel, assets, panelId: options.panelId, page: options.page, preview: !!options.preview, visible: options.visible !== false, busy: false, destroyed: false, refs: [] };
  active.set(channel, record);
  let surface = frame;
  if (assets) {
    // connect-src does not block a document navigating itself. A trusted,
    // empty parent with frame-src 'none' blocks those requests, while srcdoc
    // remains permitted. Application HTML/code is never placed in this
    // same-origin parent; the inner frame retains its opaque sandbox origin.
    surface = document.createElement("iframe");
    surface.title = app.title; surface.className = "projectionFrame";
    surface.referrerPolicy = "no-referrer";

function pageController(app, options) {
  const objects = new Map();
  let workbench, openRegion, feedbackContext = null, feedbackGuard = null;
  const channel = app.manifest.context?.find(item => item.channel === "focus");
  const api = {
    attach(value, navigate) { workbench = value; openRegion = navigate; },
    canRead: record => app.manifest.sidebar.some(item => item.id === record.panelId),
    openPanel(panelId) {
      if (typeof panelId !== "string" || !app.manifest.sidebar.some(item => item.id === panelId)) throw fail("panel_unknown", "只能打开清单中的功能区");
      return openRegion(panelId);
    },
    openPage(target) {
      if (target.pathname !== "/workbenches/view" || target.searchParams.get("id") !== app.workbench_id) return null;
      if (target.hash || [...target.searchParams.keys()].some(key => !["id", "region"].includes(key))
          || target.searchParams.getAll("id").length !== 1 || target.searchParams.getAll("region").length > 1) {
        throw fail("page_target", "当前工作台入口只支持 id 和 region");
      }
      const panelId = target.searchParams.get("region") ?? "facade";
      if (panelId !== "facade" && !app.manifest.sidebar.some(item => item.id === panelId)) throw fail("page_target", "体验入口指向未知功能区");
      if (!workbench.getPanel(panelId)) throw fail("page_target", "体验入口对应的面板未装配");
      return openRegion(panelId);
    },
    current: () => workbench?.contextStore.get("focus"),
    lookup: ref => objects.get(ref),
    snapshot: () => ({ object: api.current() || null, revision: workbench?.contextStore.revision || 0 }),
    async object(value) {
      const object = await request("object", { id: app.workbench_id, preview: !!options.preview, object: value });
      if (objects.has(object.ref) && objects.get(object.ref).status !== object.status) throw fail("status_conflict", "同一对象在各功能区的状态必须一致");
      objects.set(object.ref, object);
      return object;
    },
    async focus(record, object) {
      if (!channel?.publishers.includes(record.panelId)) throw fail("context_forbidden", "此功能区没有发布 focus 的权限");
      for (const target of active.values()) if (target.page === api) cancelFeedback(target);
      const checked = await api.object(object);
      if (record.destroyed) throw fail("cancelled", "功能区已关闭");
      workbench.contextStore.set("focus", checked, { source: record.panelId });
      const snapshot = api.snapshot();
      for (const target of active.values()) if (target.page === api && channel.subscribers.includes(target.panelId)) post(target, "focus", snapshot);
      return snapshot;
    },
    async context(submittedTarget) {
      feedbackGuard?.();
      const target = await request("facade", { id: app.workbench_id, preview: !!options.preview });
      feedbackGuard?.();
      if (submittedTarget?.resident_id !== target.resident_id || submittedTarget?.lineage_id !== target.lineage_id) throw fail("resident_unbound", "门面绑定已变化，请重新打开工作台");
      const object = feedbackContext?.object || api.current();
      if (!object) return null;
      await api.object(object);
      feedbackGuard?.();
      return { context_text: JSON.stringify({ workbench_id: app.workbench_id, ...feedbackContext, object: displayObject(object) }) };

const message = event.data;
if (message?.type !== "portal-projection-request") return;
const record = active.get(message.channel);
if (!record || event.source !== record.frame.contentWindow || record.destroyed || typeof message.requestId !== "string") return;
const { app, frame } = record;
const payload = message.payload || {};
const reply = { type: "portal-projection-result", channel: message.channel, requestId: message.requestId };
try {
  if (message.method === "context") reply.result = { workbench_id: app.workbench_id, title: app.title, bindings: app.bindings, preview: record.preview, panel_id: record.panelId, visible: record.visible, focus: record.page?.canRead(record) ? record.page.snapshot() : undefined };
  else if (message.method === "focus") reply.result = await record.page?.focus(record, payload.object);
  else if (message.method === "focus-read") reply.result = record.page?.canRead(record) ? record.page.snapshot() : undefined;
  else if (message.method === "open-panel") {
    if (!record.page) throw fail("panel_unknown", "此工作台没有清单功能区");
    reply.result = record.page.openPanel(payload.panelId);
  }
  else if (message.method === "open-page") {
    if (!window.PortalNav?.openPage) throw fail("page_unavailable", "页面导航宿主未就绪");
    try {
      reply.result = await window.PortalNav.openPage(payload.url, { handleCurrent: target => {
        if (record.destroyed) throw fail("cancelled", "功能区已关闭");
        return record.page?.openPage(target) ?? null;
      } });
    } catch (error) {
      if (error.code?.startsWith("portal.")) error.code = error.code.replace("portal.", "projection.");
      throw error;
    }
  }
  else if (message.method === "watch") {
    const revision = record.watchRevision = (record.watchRevision || 0) + 1;
    const result = await request("observe", { id: app.workbench_id, preview: record.preview, refs: payload.refs });
    if (revision === record.watchRevision) {
      record.refs = result.references.map(item => item.ref);
      record.references = result.references;
    }

else if (message.method === "feedback") {
  if (!record.page) throw fail("resident_unbound", "工作台没有门面对话");
  const object = record.page.lookup(payload.ref);
  if (!object) throw fail("object_unknown", "请先聚焦反馈对象");
  if (object.status === "simulated") throw fail("simulated", "模拟演示不能触发真实操作");
  if (record.busy) throw fail("feedback_busy", "已有操作等待确认");
  if (!record.visible || record.page.snapshot().object?.ref !== payload.ref) throw fail("cancelled", "反馈对象已不在当前情境，请重新选择");
  if (payload.subject !== undefined && (typeof payload.subject !== "string" || !payload.subject.trim() || payload.subject.length > 240)) throw fail("feedback", "讨论对象名称须为非空文字（最多 240 个 UTF-16 码元）");
  if (typeof payload.text !== "string" || !payload.text.trim() || payload.text.length > 20000) throw fail("feedback", "请填写反馈内容（最多 20000 字）");
  const feedbackPayload = { ...payload,
    anchor: feedbackContextField(payload.anchor, "anchor", 2048),
    scene: feedbackContextField(payload.scene, "scene", 8000),
  };
  const pending = { controller: new AbortController(), revision: record.page.snapshot().revision };
  record.pendingFeedback = pending;
  record.busy = true;
  try {
