def _ensure_idle(self) -> None:
    status, _state = self._load_status()
    state = _run_status(status.get("state") or status.get("status"))
    if state in {"queued", "running"}:
        raise ResourceBackupConflict(
            "A Resource Backup operation is already active"
        )
    active = self._active_run(status, self._load_run_records())
    if active:
        raise ResourceBackupConflict("A Resource Backup operation is already active")

def _schedule_status(self, actor: str) -> dict[str, Any]:
    try:
        return self._workflow.schedule(actor)
    except Exception:  # noqa: BLE001 - the overview reports an unreadable schedule
        return {"readable": False, "lineage_id": LINEAGE_ID, "actions": [], "timers": []}

def _start(self, operation: str, actor: str) -> dict[str, str]:
    """Use the same manual Event as the graph; never bypass its switches."""

    schedule = self._schedule_status(actor)
    actions = {item["operation"]: item for item in schedule["actions"]}
    action = actions.get(operation, {})
    if not action.get("available"):
        raise ResourceBackupUnavailable("备份流程未配置或已关闭，请在 Portal System 中打开对应 Event 和 Effect")
    if any(item.get("active") for item in actions.values()):
        raise ResourceBackupConflict("A Resource Backup operation is already active")
    try:
        receipt = self._workflow.trigger(action["event_source_id"], actor)
    except Exception as exc:  # noqa: BLE001 - executor details stay server-side
        raise ResourceBackupUnavailable("Resource Backup executor is unavailable") from exc
    delivery = receipt.get("delivery") or {}
    accepted = any(item.get("status") == "executed" and item.get("target_id") == action.get("effect_id")
                   for item in delivery.get("results") or [])
    if not receipt.get("event_id") or not accepted:
        raise ResourceBackupUnavailable("备份流程没有接受本次操作，请检查 Event、Effect 与连线状态")
    return {"lineage_id": LINEAGE_ID, "event_source_id": action["event_source_id"],
            "event_id": receipt["event_id"], "trigger_path_id": receipt.get("trigger_path_id", "")}

    effects = lineage.get("program_effect_runtime") or {}
    wires = lineage.get("program", {}).get("wires", [])
    actions, timers = [], []
    for operation in OPERATIONS:
        binding = bindings.get(operation) or {}
        effect_id = binding.get("effect_id", "")
        effect = components.get(effect_id, {})
        effect_state = effects.get(effect_id) or {}
        for role, event_type, collection in (("manual", "manual.triggered", actions), ("timer", "time.reached", timers)):
            if role == "timer" and operation not in SCHEDULES:
                continue
            event_id = binding.get(f"{role}_event_id", "")
            event = components.get(event_id, {})
            state = events.get(event_id) or {}
            config = event.get("config") or {}
            connected = any(w.get("kind") == "route" and w.get("source") == event_id
                            and w.get("target") == effect_id for w in wires)
            configured = (event.get("kind") == "event_source" and config.get("event_type") == event_type
                          and effect.get("kind") == "effect" and connected
                          and event_id in events and effect_id in effects)
            paused = bool(state.get("paused") or effect_state.get("paused"))
            available = bool(configured and not paused and not state.get("exhausted"))
            collection.append({
                "name": event_id, "operation": operation, "event_source_id": event_id,
                "effect_id": effect_id, "configured": configured, "available": available,
                "paused": paused, "active": False,
                "calendar": _calendar(config) if role == "timer" else "",
                "last_trigger_at": str(state.get("last_fired_at") or ""),
                "next_trigger_at": str(state.get("next_due_at") or state.get("next_scheduled_at") or "") if available else "",
            })
    return {"readable": True, "lineage_id": LINEAGE_ID, "actions": actions, "timers": timers}

