def _connect(
    self,
    *,
    timeout: float | None | object = _USE_DEFAULT_REQUEST_TIMEOUT,
    cancellation_requested: Callable[[], bool] | None = None,
) -> None:
    if self._transport is not None:
        return
    with self._connect_lock:
        if self._transport is not None:
            return
        try:
            sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            sock.settimeout(5.0)
            sock.connect(str(self.socket_path))
            transport = WebSocketTransport(sock)
            sock.settimeout(None)
        except (OSError, CodexAppServerUnavailable) as exc:
            try:
                sock.close()
            except Exception:
                pass
            raise CodexAppServerUnavailable(
                f"Codex app-server socket unavailable: {self.socket_path}: {exc}"
            ) from exc
        with self._state_lock:
            self._socket = sock
            self._transport = transport
            self._closing = False
            self._reader_thread = threading.Thread(
                target=self._reader_loop,
                name="portal-codex-app-server-reader",
                daemon=True,
            )
            self._reader_thread.start()
        try:
            self.request(
                "initialize",
                {
                    "clientInfo": {
                        "name": "dirtybase-portal-execution-worker",
                        "title": "DirtyBase Portal",
                        "version": "1",
                    },
                    "capabilities": {"experimentalApi": True},
                },
                timeout=timeout,
                cancellation_requested=cancellation_requested,
            )
            self.notify("initialized", {})
        except Exception:
            self._disconnect(CodexAppServerUnavailable("Codex app-server initialization failed"))
            raise
        self._ensure_maintenance_thread()

