                additional_context=(
                    additional_context
                    if isinstance(additional_context, dict)
                    else None
                ),
                cancellation_requested=cancellation_requested,
            )
            applied = True
    except Exception as exc:
        error = type(exc).__name__
    if turn_control_result_callback is not None:
        try:
