    ).fetchall()}

def _capacity_limit(self, connection, capacity_key: str) -> int:
    settings = self._capacity_settings(connection).get(capacity_key)
    return int(settings["limit_value"]) if settings else self._default_capacity_limits.get(capacity_key, self.max_concurrency)
def _account_quota(self, connection, capacity_key: str) -> dict[str, Any]:
    states, _ = self._quota_states(connection, {capacity_key}, set(), now=time.time())
    return states[capacity_key]

def _quota_states(self, connection, capacity_keys, binding_ids, *, now):
    """Read quota samples, thresholds and overrides once for a scheduling pass."""
    keys = [prefix + key for key in capacity_keys for prefix in ("quota:", "quota_threshold:")]
    keys.extend("quota_override:" + binding for binding in binding_ids if binding)
    metadata = {row["key"]: _object(row["value"]) for row in connection.execute(
        "SELECT key,value FROM execution_store_meta WHERE key=ANY(%s)", (keys,),
    ).fetchall()} if keys else {}
    accounts = {account.capacity_key: account for account in self.accounts.accounts()}
    states = {}
    for key in capacity_keys:
        sample = metadata.get("quota:" + key, {})
        threshold = account_close_threshold(accounts[key], sample, metadata.get("quota_threshold:" + key, {}))
        states[key] = quota_state(sample, now=now, threshold=threshold)
    overrides = {binding for binding in binding_ids if metadata.get("quota_override:" + binding, {}).get("enabled") is True}
    return states, overrides

def _admission_snapshot(self, connection, requests, *, now=None):
    """Shared inputs for claim, a detailed queue view and batched states."""
    now = time.time() if now is None else now
    active_counts = defaultdict(int)
    active_bindings = set()
    for _, request in self._active_scheduling_requests(connection):
        active_counts[self._capacity_key(request)] += 1
        binding = str((request.get("session") or {}).get("binding_id") or "")
        if binding:
            active_bindings.add(binding)
    capacities = {self._capacity_key(request) for request in requests}
    bindings = {str((request.get("session") or {}).get("binding_id") or "") for request in requests}
    settings = self._capacity_settings(connection)
    limits = {key: int(settings[key]["limit_value"]) if key in settings else self._default_capacity_limits.get(key, self.max_concurrency) for key in capacities}
    dispatch = {row["capacity_key"]: {name: float(row[name]) if name == "interval_seconds" else epoch_seconds(row[name]) for name in ("last_dispatched_at", "next_dispatch_at", "interval_seconds")} for row in connection.execute(
        "SELECT * FROM capacity_dispatch_state WHERE capacity_key=ANY(%s)", (list(capacities),),
    ).fetchall()}
    quota_keys = capacities & self.quota_capacity_keys if self.quota_reserve_enabled else set()
    quotas, overrides = self._quota_states(connection, quota_keys, bindings, now=now)
    return {"now": now, "active_counts": active_counts, "active_bindings": active_bindings,
            "limits": limits, "dispatch": dispatch, "quotas": quotas, "overrides": overrides}

def _admission_reason(self, request, available_at, interrupt_only, admission):
    capacity = self._capacity_key(request)
    binding = str((request.get("session") or {}).get("binding_id") or "")
    paused = admission["quotas"].get(capacity, {}).get("automatic_paused", False)
    return self._queue_reason(
        paused=not interrupt_only and paused and binding not in admission["overrides"],
        deferred=float(available_at) > admission["now"],
        capacity=interrupt_only or admission["limits"][capacity] > admission["active_counts"][capacity],
        dispatch_wait=not interrupt_only and admission["dispatch"].get(capacity, {}).get("next_dispatch_at", 0) > admission["now"],
        binding_busy=binding in admission["active_bindings"],
    )

def _queue_reason(*, paused, deferred, capacity, dispatch_wait, binding_busy):
    if paused:
        return 'quota_reserve'
    if deferred:
        return 'deferred'
    if not capacity:
        return 'capacity'
    if dispatch_wait:
        return 'dispatch_interval'
    if binding_busy:
        return 'session_binding'
    return 'ready'

def _dispatch_interval_range(self, connection, capacity_key: str) -> tuple[float, float]:
    if capacity_key.startswith(SESSION_CONTROL_CAPACITY_PREFIX):
        return (0.0, 0.0)
    settings = self._capacity_settings(connection).get(capacity_key)
    if settings and settings["dispatch_interval_min_seconds"] is not None and settings["dispatch_interval_max_seconds"] is not None:
        return (float(settings["dispatch_interval_min_seconds"]), float(settings["dispatch_interval_max_seconds"]))
    return (self.dispatch_interval_min_seconds, self.dispatch_interval_max_seconds)
def _next_dispatch_interval_seconds(self, connection, capacity_key: str) -> float:
    lower, upper = self._dispatch_interval_range(connection, capacity_key)
    if upper <= 0:
        return 0.0
    if upper == lower:
        return lower
    return random.uniform(lower, upper)

@staticmethod
def _capacity_dispatch_state(
    connection: Any,
    capacity_key: str,
) -> dict[str, float]:
    row = connection.execute(
        '\n            SELECT last_dispatched_at, next_dispatch_at, interval_seconds\n            FROM capacity_dispatch_state\n            WHERE capacity_key = %s\n            ',
        (capacity_key,),
    ).fetchone()
    if row is None:
        return {
            "last_dispatched_at": 0.0,
            "next_dispatch_at": 0.0,
            "interval_seconds": 0.0,
        }
    return {
        "last_dispatched_at": (epoch_seconds(row["last_dispatched_at"]) or 0.0),
        "next_dispatch_at": (epoch_seconds(row["next_dispatch_at"]) or 0.0),
        "interval_seconds": float(row["interval_seconds"]),
    }

def _reserve_capacity_dispatch(
    self,
    connection: Any,
    capacity_key: str,
    *,
    now_epoch: float,
) -> dict[str, float]:
    interval_seconds = self._next_dispatch_interval_seconds(connection, capacity_key)
    next_dispatch_at = now_epoch + interval_seconds
    connection.execute(
        '\n            INSERT INTO capacity_dispatch_state (\n                capacity_key, last_dispatched_at, next_dispatch_at,\n                interval_seconds, updated_at\n            ) VALUES (%s, %s, %s, %s, %s)\n            ON CONFLICT(capacity_key) DO UPDATE SET\n                last_dispatched_at=excluded.last_dispatched_at,\n                next_dispatch_at=excluded.next_dispatch_at,\n                interval_seconds=excluded.interval_seconds,\n                updated_at=excluded.updated_at\n            ',
        (
            capacity_key,
            instant(now_epoch),
            instant(next_dispatch_at),
            interval_seconds,
            execution_timestamp(),
        ),
    )
    return {
        "last_dispatched_at": now_epoch,
        "next_dispatch_at": next_dispatch_at,
        "interval_seconds": interval_seconds,

def _fair_queue_order(
    connection: Any,
    rows: list[Any],
) -> list[Any]:
    """Round-robin queued work across actors while preserving priority/FIFO."""
    if not rows:
        return []
    last_dispatch = {
        (int(row["priority"]), str(row["actor"])): (epoch_seconds(row["last_dispatched_at"]) or 0.0)
        for row in connection.execute(
            """
            SELECT priority, actor, last_dispatched_at
            FROM execution_actor_dispatch_state
            """
        ).fetchall()
    }
    pending: dict[int, dict[str, deque[Any]]] = defaultdict(
        lambda: defaultdict(deque)
    )
    for row in rows:
        pending[int(row["priority"])][str(row["actor"])].append(row)

    ordered: list[Any] = []
    virtual_dispatch = max(last_dispatch.values(), default=0.0)
    for priority in sorted(pending, reverse=True):
        actor_queues = pending[priority]
        while actor_queues:
            actor = min(
                actor_queues,
                key=lambda candidate: (
                    (priority, candidate) in last_dispatch,
                    last_dispatch.get((priority, candidate), 0.0),
                    str(actor_queues[candidate][0]["created_at"]),
                    candidate,
                ),
            )
            ordered.append(actor_queues[actor].popleft())
            virtual_dispatch += 1.0
            last_dispatch[(priority, actor)] = virtual_dispatch
            if not actor_queues[actor]:
                del actor_queues[actor]
    return ordered

@staticmethod
def _record_actor_dispatch(
    connection: Any,
    *,
    actor: str,
    priority: int,
    now_epoch: float,
) -> None:
    connection.execute(
        '\n            INSERT INTO execution_actor_dispatch_state (\n                priority, actor, last_dispatched_at, updated_at\n            ) VALUES (%s, %s, %s, %s)\n            ON CONFLICT(priority, actor) DO UPDATE SET\n                last_dispatched_at=excluded.last_dispatched_at,\n                updated_at=excluded.updated_at\n            ',
        (priority, actor, instant(now_epoch), execution_timestamp()),
    )

@contextmanager

def close_threshold(account, sample, setting=None):
    metric = "percent" if account.quota_policy == "reserve" else "balance"
    setting = setting or {}
    observed_unit = "%" if metric == "percent" else str(sample.get("currency") or "")
    # A reading without a currency keeps the configured threshold: an
    # unavailable balance is unknown, not a disabled (zero) threshold.
    unit = observed_unit or str(setting.get("unit") or "")
    default = RESERVE_PERCENT if metric == "percent" else 0.0
    value = setting.get("value", default) if setting.get("unit", unit) == unit else default
    return {"metric": metric, "unit": unit, "value": value, "supported": bool(observed_unit)}


def validate_threshold(value, expected):
    if not isinstance(value, dict) or not finite_number(value.get("value")):
        raise ValueError("Close threshold must be a finite number")
    if not expected["supported"] or value.get("unit") != expected["unit"]:
        raise ValueError("Close threshold unit is unavailable or does not match this account")
    amount = value["value"]
    if amount < 0 or (expected["metric"] == "percent" and amount > 100):
        raise ValueError("Close threshold must be nonnegative and percentages cannot exceed 100")
    return {**expected, "value": amount}


def quota_state(sample: dict[str, Any], *, now: float, threshold=None) -> dict[str, Any]:
    threshold = threshold or {"metric": "percent", "unit": "%", "value": RESERVE_PERCENT, "supported": True}
    metric = threshold["metric"]
    remaining = sample.get("remaining_percent" if metric == "percent" else "remaining_balance")
    fresh = (now - float(sample.get("observed_at") or 0) <= float(sample.get("max_age_seconds") or MAX_SAMPLE_AGE_SECONDS)
             and (sample.get("valid_until") is None or now < float(sample["valid_until"])))
    status = sample.get("status", "unknown")
    threshold_enabled = threshold["value"] != 0
    if not threshold_enabled:
        # Availability here is Portal admission policy, not a claim of a fresh
        # provider balance. Zero disables protection even for stale prior holds.
        status = "available"
    elif fresh and finite_number(remaining) and threshold["supported"]:
        status = "reserved" if remaining <= threshold["value"] else "available" if sample.get("complete", status != "unknown") else "unknown"
    elif not fresh and status != "reserved":
        status = "unknown"
    return {**sample, "status": status, "remaining": remaining, "fresh": fresh, "close_threshold": threshold,
            "threshold_enabled": threshold_enabled,
            "reserve_percent": threshold["value"] if metric == "percent" else None,
            "automatic_paused": threshold_enabled and (status == "reserved" or (metric == "percent" and status != "available"))}

def _enforce_quota_reserve(self, connection, capacity_key: str = "") -> None:
    if not self.quota_reserve_enabled:
        return
    active = self._active_scheduling_requests(connection, uncancelled=True)
    requests = [request for _, request in active]
    keys = {self._capacity_key(request) for request in requests} & self.quota_capacity_keys
    bindings = {str((request.get("session") or {}).get("binding_id") or "") for request in requests}
    quotas, overrides = self._quota_states(connection, keys, bindings, now=time.time())
    exempt = {key: self._threshold_exempt_ids(connection, key) for key in keys}
    account_ids = {account.capacity_key: account.account_id for account in self.accounts.accounts()}
    for execution_id, request in active:
        key = self._capacity_key(request)
        if key not in quotas or (capacity_key and key != capacity_key):
            continue
        binding = str((request.get("session") or {}).get("binding_id") or "")
        quota = quotas[key]
        if execution_id in exempt[key] or binding in overrides or not quota["automatic_paused"] or quota["status"] != "reserved":
            continue
        connection.execute(
            'UPDATE executions SET cancel_requested=1, updated_at=%s WHERE execution_id=%s',
            (execution_timestamp(), execution_id),
        )
        self._event(connection, execution_id, "cancellation_requested", {
            "reason": "quota_reserve", "account_id": account_ids[key],
            "close_threshold": quota["close_threshold"], "reserve_percent": quota["reserve_percent"],
        })

def _recover_expired(self, connection: Any) -> int:
    rows = connection.execute(
        "\n            SELECT execution_id, owner_worker_id, status, cancel_requested,\n                   checkpoint_json, request_json, usage_accounted_json\n            FROM executions\n            WHERE (status IN ('claimed', 'running')\n              AND lease_expires_at IS NOT NULL\n              AND lease_expires_at < %s) FOR UPDATE\n            ",
        (instant(time.time()),),
    ).fetchall()
    for row in rows:
        execution_id = str(row["execution_id"])
        if self._requeue_abandoned_provider_work(connection, row):
            continue
        if bool(row["cancel_requested"]):
            self._finalize_released_cancellation(
                connection, row,
                error=(
                    "execution cancellation finalized after worker lease expired"
                ),
                details={
                    "reason": (
                        "worker lease expired after cancellation"
                    ),
                    "previous_worker_id": row["owner_worker_id"],
                },
            )
            continue
        checkpoint = _object(row["checkpoint_json"])
        resumable = bool(checkpoint.get("resumable"))
        if str(row["status"]) == "running" and not resumable:
            error = (
                "execution worker lease expired after backend execution "
                "started"
            )
            result = self._with_accounted_usage(row, ExecutionResult(
                execution_id=execution_id,
                status="failed",
                error=error,
            ).to_payload())
            connection.execute(
                "\n                    UPDATE executions\n                    SET status = 'failed', result_json = %s, error = %s,\n                        owner_worker_id = '', claim_token = '',\n                        lease_expires_at = NULL, updated_at = %s\n                    WHERE execution_id = %s\n                    ",
                (_json(result), error, execution_timestamp(), execution_id),
            )
            self._event(
                connection,
                execution_id,
                "failed",
                {
                    "reason": "worker lease expired after start",
                    "previous_worker_id": row["owner_worker_id"],
                },
            )
            continue
        connection.execute(
            "\n                UPDATE executions\n                SET status = 'queued', owner_worker_id = '', claim_token = '',\n                    lease_expires_at = NULL, updated_at = %s\n                WHERE execution_id = %s\n                ",
            (execution_timestamp(), execution_id),
        )
        self._event(
            connection,
            execution_id,
            "requeued",
            {
                "reason": (
                    "worker lease expired with resumable provider turn"
                    if checkpoint
                    else "worker lease expired"
                ),
                "previous_worker_id": row["owner_worker_id"],
                "checkpoint": checkpoint,
            },
        )
    if rows:
        self._worker_control_changed.notify_all()
    return len(rows)

def _wait_ready(self, worker: WorkerProcess) -> None:
    deadline = time.monotonic() + self.ready_timeout
    while (
        time.monotonic() < deadline
        and not self._stopping.is_set()
    ):
        return_code = worker.process.poll()
        if return_code is not None:
            raise RuntimeError(
                f"replacement ExecutionWorker exited with code {return_code}"
            )
        health = self._health(worker)
        if (
            health.get("ok")
            and health.get("worker_id") == worker.worker_id
            and health.get("build_id") == worker.build_id
        ):
            return
        time.sleep(0.1)
    if self._stopping.is_set():
        raise InterruptedError("ExecutionWorkerManager is stopping")
    raise TimeoutError(
        f"replacement ExecutionWorker was not ready after {self.ready_timeout:g}s"
    )

def _activate_replacement(
    replacement: WorkerProcess,
    previous: WorkerProcess | None,
) -> None:
    error: Exception | None = None
    for _attempt in range(3):
        try:
            ExecutionServiceClient().request(
                "scheduler.worker.activate",
                {
                    "worker_id": replacement.worker_id,
                    "previous_worker_id": (
                        previous.worker_id if previous else ""
                    ),
                },
            )
            return
        except Exception as exc:
            error = exc
            time.sleep(0.1)
    assert error is not None
    raise error

def _replace(self) -> None:
    replacement = self._spawn()
    previous = self._current
    try:
        self._wait_ready(replacement)
        self._activate_replacement(replacement, previous)
    except Exception:
        self._discard_failed_replacement(replacement)
        raise
    self._cleanup_offline_registrations()
    self._current = replacement
    if previous is not None:
        self._mark_draining(previous)
        self._draining.append(previous)

def _reap(self) -> None:
    remaining: list[WorkerProcess] = []
    for worker in self._draining:
        if worker.process.poll() is None:
            if not worker.draining_started_at:
                worker.draining_started_at = time.time()
            self._request_worker_stop(worker)
            now = time.time()
            drain_deadline = (
                worker.draining_started_at + self.drain_timeout
            )
            if now >= drain_deadline:
                worker.drain_timed_out = True
            if now >= drain_deadline + self.kill_grace:
                self._kill_worker(worker)
            if worker.process.poll() is None:
                remaining.append(worker)
                continue
        if worker.handover is None or worker.handover.get("blocked_execution_ids"):
            worker.handover = self._handover(worker)
        if worker.handover is None:
            remaining.append(worker)
            continue
        if worker.handover.get("blocked_execution_ids"):
            remaining.append(worker)
            continue
        if not self._unregister(worker.worker_id):
            remaining.append(worker)
            continue
        try:
            worker.health_path.unlink()
        except FileNotFoundError:
            pass
    self._draining = remaining

def _handover_checkpoint(
    checkpoint: dict[str, Any], worker_id: str,
) -> dict[str, Any]:
    payload = dict(checkpoint)
    payload["turn_start_reason"] = "backend_service_update"
    if payload.get("turn_id") and not payload.get("provider_completed"):
        payload["worker_handover"] = {
            "worker_id": worker_id,
            "turn_id": str(payload["turn_id"]),
            "backend_session_id": str(payload.get("backend_session_id") or ""),
        }
        provider = AGENT_PROVIDERS.get(str(payload.get("provider") or ""))
        if provider is not None and provider.handover_keeps_turn and payload.get("operation") == "turn":
            # The turn goes on in the Provider's daemon; the next Worker
            # attaches to it instead of asking it again.
            payload["worker_handover"]["turn_kept_running"] = True
    return payload

def prepare_handover(
    self, execution_id: str, *, worker_id: str, claim_token: str,
) -> dict[str, Any]:
    with self._lock, self._connect() as connection:
        self._transaction_lock(connection, f"execution:{execution_id}")
        row = self._assert_owner(
            connection.execute(
                'SELECT * FROM executions WHERE execution_id = %s FOR UPDATE',
                (execution_id,),
            ).fetchone(),
            worker_id=worker_id, claim_token=claim_token,
        )
        if row["status"] not in ACTIVE_STATUSES:
            raise PermissionError("execution claim is no longer active")
        if row["cancel_requested"]:
            return {"ready": False, "cancel_requested": True}
        checkpoint = _object(row["checkpoint_json"])
        if not checkpoint.get("resumable"):
            return {"ready": False, "cancel_requested": False}
        payload = self._handover_checkpoint(checkpoint, worker_id)
        connection.execute(
            'UPDATE executions SET checkpoint_json = %s, updated_at = %s WHERE execution_id = %s',
            (_json(payload), execution_timestamp(), execution_id),
        )
        if payload != checkpoint:
            self._event(connection, execution_id, "handover_prepared", {
                "worker_id": worker_id,
                "turn_id": str(payload.get("turn_id") or ""),
            })
        connection.commit()
    return {
        "ready": True,
        "cancel_requested": False,
        "interrupt_required": bool(
            payload.get("turn_id") and not payload.get("provider_completed")
            and not _turn_kept_running(payload)
        ),
    }

def heartbeat_loop() -> None:
    heartbeat_interval = max(5.0, float(lease_seconds) / 3)
    lease_deadline = time.monotonic() + float(lease_seconds)

    def interrupt_cancelled_turn() -> None:
        # The cancellation flag records intent, not delivery. A lost
        # reply or a Provider still starting must be retried while this
        # Worker owns the execution, until execute() actually returns.
        try:
            self.runtime.interrupt(execution_id)
        except Exception:
            LOGGER.warning("Cancellation interrupt failed for %s; will retry", execution_id)

    def fence(*, interrupt_provider: bool = True) -> None:
        if heartbeat_stop.is_set():
            return
        ownership_lost.set()
        cancelled.set()
        try:
            if interrupt_provider:
                self.runtime.interrupt(execution_id)
        except Exception:
            pass

    def prepare_handover() -> bool:
        status = self.scheduler.prepare_handover(execution_id, claim_token)
        if status.get("cancel_requested"):
            cancelled.set()
            return False
        if not status.get("ready"):
            heartbeat_stop.wait(0.25)
            return False
        planned_handover.set()
        fence(interrupt_provider=bool(status.get("interrupt_required", True)))
        return True

    while not heartbeat_stop.is_set():
        try:
            if not cancelled.is_set() and self.shutdown_requested() and prepare_handover():
                return
            if cancelled.is_set():
                if heartbeat_stop.wait(heartbeat_interval):
                    return
                status = {}
            else:
                status = self.scheduler.wait_for_control(
                    execution_id, claim_token,
                    timeout_seconds=min(heartbeat_interval, 0.25) if self.shutdown_requested() else heartbeat_interval,
                )
            if heartbeat_stop.is_set():
                return
            if status.get("cancel_requested"):
                cancelled.set()
            interrupt_attempted = cancelled.is_set()
            if interrupt_attempted:
                interrupt_cancelled_turn()
            if not cancelled.is_set() and (self.shutdown_requested() or status.get("handover_requested")):
                if prepare_handover():
                    return
            elif not cancelled.is_set():
                enqueue_turn_controls(status.get("turn_controls"))
            if time.monotonic() >= lease_deadline:
                fence()
                return
            status = self.scheduler.heartbeat(
                execution_id,
                claim_token,
                lease_seconds,
            )
            lease_deadline = time.monotonic() + float(lease_seconds)
            if status.get("cancel_requested"):
                cancelled.set()
                if not interrupt_attempted:
                    interrupt_cancelled_turn()
        except ExecutionClaimOwnershipLost:
            fence()
            return
        except (ExecutionServiceUnavailable, ExecutionResponseUnknown):
            if time.monotonic() >= lease_deadline:
                fence()
                return
            if heartbeat_stop.wait(1.0):
                return
        except BaseException:
            fence()
            return

    backend_result = self.runtime.execute(
        request,
        RuntimeContext(
            accepted_at=str(execution.get("created_at") or ""),
            emit_event=emit_event,
            cancellation_requested=cancellation_requested,
            handover_requested=ownership_lost.is_set,
            reassign_backend_route=lambda backend_route_id: (
                claim_scoped(
                    lambda: self.scheduler.reassign_capacity(
                        execution_id,
                        claim_token,
                        backend_route_id,
                    )
                )
            ),
            checkpoint_provider=lambda checkpoint: (
                claim_scoped(
                    lambda: self.scheduler.checkpoint(
                        execution_id,
                        claim_token,
                        checkpoint,
                    )
                )
            ),
            recovery_checkpoint=recovery_checkpoint,
            turn_control_provider=next_turn_control,
            turn_control_result_callback=(
                record_turn_control_result
            ),
        ),
    )
    result = ExecutionResult(
        execution_id=execution_id,
        status="completed",
        output=dict(backend_result.output),
        backend_session_id=backend_result.backend_session_id,
        backend_route_id=backend_result.backend_route_id,
        usage=dict(backend_result.usage),
    )
except ExecutionRecoveryDeferred as exc:
    with receipt_lock:
        pass
    heartbeat_stop.set()
    if planned_handover.is_set():
        heartbeat.join()
    deferred_reason = (
        "worker generation handover"
        if planned_handover.is_set()
        else str(exc or "provider recovery deferred")
    )
    try:
        retry_after_seconds = float(
            getattr(exc, "retry_after_seconds", 0) or 0
        )
        if retry_after_seconds > 0:
            self.scheduler.requeue(
                execution_id,
                claim_token,
                deferred_reason,
                retry_after_seconds=retry_after_seconds,
            )
        else:
            self.scheduler.requeue(
                execution_id,
                claim_token,
                deferred_reason,
            )
        if planned_handover.is_set():
            # A successful fenced requeue released our own claim. The
            # local detach flag is not evidence that another owner stole it.
            ownership_lost.clear()

finally:
    # A Provider call can end while its input pump still persists a
    # receipt. Keep the lease alive until that receipt is acknowledged.
    with receipt_lock:
        pass
    heartbeat_stop.set()
if planned_handover.is_set() and not deferred_reason:
    heartbeat.join()
    try:
        released = self.scheduler.requeue(
            execution_id, claim_token, "worker generation handover",
        )
        return {
            "execution_id": execution_id,
            "status": (
                "cancelled" if released.get("status") == "cancelled"
                else "requeued"
            ),
            "reason": "worker generation handover",
        }
    except (ExecutionClaimOwnershipLost, ExecutionServiceUnavailable):
        ownership_lost.set()
if ownership_lost.is_set():
    heartbeat.join(timeout=2)
    return {
        "execution_id": execution_id,
        "status": "claim_lost",
        "reason": "execution claim ownership changed",
    }
if deferred_reason:
    heartbeat.join(timeout=2)
    return {
        "execution_id": execution_id,
        "status": "requeued",
        "reason": deferred_reason,
    }
if result is None:
    heartbeat.join(timeout=2)
    raise RuntimeError("execution produced no terminal result")
try:
    snapshot = self.scheduler.finish(result, claim_token)
except ExecutionClaimOwnershipLost:
    return {
        "execution_id": execution_id,
        "status": "claim_lost",
        "reason": "execution claim ownership changed",
    }
finally:
    # Publishing the terminal state wakes the blocking control wait,
    # so the heartbeat can be reclaimed without paying its join
    # timeout on every successful execution.
    heartbeat.join(timeout=2)
return {
    "execution_id": execution_id,
    "status": result.status,
    "result": result.to_payload(),
    "snapshot": snapshot,
}

def _fill_slots(self) -> bool:
    claimed_any = False
    while (
        not self._stopping.is_set()
        and self._active_count() < self.max_parallel
    ):
        claim = self.worker.claim(
            wait_seconds=(
                30.0
                if not claimed_any
                else 0.1
            )
        )
        if not claim.get("claimed"):
            reason = claim.get("reason")
            if reason == "worker_not_registered" or (
                reason == "worker_not_active"
                and claim.get("worker_state") in {"draining", "offline"}
            ):
                self._leave_retired()
            elif reason == "worker_not_active":
                self._stopping.wait(1.0)
            break
        execution = (
            claim.get("execution")
            if isinstance(claim.get("execution"), dict)
            else {}
        )
        execution_id = str(execution.get("execution_id") or "")
        claim_marker = object()
        with self._active_lock:
            self._active[execution_id] = {
                "_claim_marker": claim_marker,
                "execution_id": execution_id,
                "capability": str(
                    execution.get("capability") or ""
                ),
                "started_at": time.time(),
            }
        threading.Thread(
            target=self._execute,
            args=(claim, claim_marker),
            name=f"execution-{execution_id}",
            daemon=True,
        ).start()
        claimed_any = True
    return claimed_any

def execute(
    self,
    request: ExecutionRequest,
    context: RuntimeContext | None = None,
) -> BackendResult:
    request.validate()
    runtime_context = context or RuntimeContext()
    execution_id = request.execution_id
    abandoned = isinstance((runtime_context.recovery_checkpoint or {}).get("abandoned"), dict)
    waited_for_predecessor = False
    with self._execution_slot_changed:
        while execution_id in self._execution_slots:
            waited_for_predecessor = True
            if runtime_context.is_cancelled() and not abandoned:
                raise ExecutionCancelled(
                    "execution was cancelled while waiting for its local predecessor"
                )
            if runtime_context.is_handover():
                raise ExecutionRecoveryDeferred(
                    "execution claim changed while waiting for its local predecessor"
                )
            self._execution_slot_changed.wait(0.1)
        if runtime_context.is_cancelled() and not abandoned:
            raise ExecutionCancelled(
                "execution was cancelled before ExecutionRuntime started"
            )
        if waited_for_predecessor and runtime_context.is_handover():
            raise ExecutionRecoveryDeferred(
                "execution claim changed before ExecutionRuntime started"
            )
        self._execution_slots.add(execution_id)
    try:
        return self._execute_once(request, runtime_context)
    finally:
        with self._execution_slot_changed:
            self._execution_slots.discard(execution_id)
            self._execution_slot_changed.notify_all()

def _execute_once(
    self,
    request: ExecutionRequest,
    context: RuntimeContext,
) -> BackendResult:
    request.validate()
    try:
        service = self.services[request.service_type]
    except KeyError as exc:
        raise ValueError(
            f"unsupported AI execution service: {request.service_type}"
        ) from exc
    runtime_context = context or RuntimeContext()
    recovery_checkpoint = dict(
        runtime_context.recovery_checkpoint or {}
    )
    if isinstance(recovery_checkpoint.get("abandoned"), dict):
        self._end_abandoned(service, request, runtime_context, recovery_checkpoint)
    if runtime_context.is_cancelled():
        raise ExecutionCancelled(
            "execution was cancelled before ExecutionRuntime started"
        )
    session = self.sessions.prepare(
        request,
        recovery=bool(recovery_checkpoint),
    )
    if recovery_checkpoint:
        if str(recovery_checkpoint.get("provider") or "") != request.provider:
            raise ValueError(
                "execution checkpoint belongs to another provider"
            )
        recovered_session_id = str(
            recovery_checkpoint.get("backend_session_id") or ""
        )
        recovered_route_id = str(
            recovery_checkpoint.get("backend_route_id") or ""
        )
        if recovered_session_id:
            session = replace(
                session,
                backend_session_id=recovered_session_id,
                backend_route_id=(
                    recovered_route_id or session.backend_route_id
                ),
            )
    system_instructions = request.system_instructions
    injection_parts = system_instructions.parts

if bool(recovery_checkpoint.get("provider_completed")):
    result = BackendResult(
        output=dict(
            recovery_checkpoint.get("output")
            if isinstance(
                recovery_checkpoint.get("output"),
                dict,
            )
            else {}
        ),
        backend_session_id=str(
            recovery_checkpoint.get("backend_session_id")
            or ""
        ),
        backend_route_id=str(
            recovery_checkpoint.get("backend_route_id") or ""
        ),
        usage=dict(
            recovery_checkpoint.get("usage")
            if isinstance(
                recovery_checkpoint.get("usage"),
                dict,
            )
            else {}
        ),
        available_harness_tool_names=frozenset(
            str(name or "").strip()
            for name in (
                recovery_checkpoint.get(
                    "available_harness_tool_names"
                )
                or ()
            )
            if str(name or "").strip()
        ),
    )
    emit(
        "provider_result_recovered",
        {
            "provider": request.provider,
            "turn_id": str(
                recovery_checkpoint.get("turn_id") or ""
            ),
        },
    )
else:
    result = service.execute(
        invocation,

        "provider_completed": True,
        "output": dict(result.output),
        "usage": dict(result.usage),
        "available_harness_tool_names": sorted(
            result.available_harness_tool_names
        ),
    }
    if live_context_usage:
        completed_checkpoint["context_usage"] = (
            live_context_usage
        )
        completed_checkpoint["context_usage_at"] = (
            live_context_usage_at
        )
    if live_context_window:
        completed_checkpoint["model_context_window"] = (
            live_context_window
        )
    runtime_context.checkpoint(completed_checkpoint)
if runtime_context.is_handover():
    raise ExecutionRecoveryDeferred(
        "worker handover deferred terminal reconciliation"
    )
self.agent_data_projector.complete(

class AgentSessionService:
    service_type = "agent_session"

    def __init__(
        self,
        providers: dict[str, Backend] | None = None,
        harness: AgentHarness | None = None,
    ) -> None:
        self.providers = providers or {
            definition.provider: definition.build_backend() for definition in AGENT_PROVIDERS.values()
        }
        self.harness = harness if harness is not None else default_agent_harness()

    def execute(
        self,
        invocation: BackendInvocation,
        context: BackendContext,
    ) -> BackendResult:
        try:
            provider = self.providers[invocation.request.provider]
        except KeyError as exc:
            raise ValueError(
                "unsupported Agent Backend Provider: "
                f"{invocation.request.provider}"
            ) from exc
        from .native_options import prepare_invocation
        invocation = prepare_invocation(invocation)
        invocation = self.harness.prepare_invocation(invocation, provider)
        def execute_with_context_seed(
            prepared: BackendInvocation,
            backend_context: BackendContext,
        ) -> BackendResult:
            return provider.execute(
                prepare_backend_context_seed(provider, prepared),
                backend_context,
            )
        if not self.harness.should_run(invocation):
            return execute_with_context_seed(invocation, context)
        return self.harness.execute(
            provider=provider,
            invocation=invocation,
            context=context,
            execute=execute_with_context_seed,
        )

    def interrupt(
        self,
        *,
        provider: str,
        backend_session_id: str,
        turn_id: str,
        backend_route_id: str,
        runtime_options: dict[str, Any],
    ) -> bool:
        selected = self.providers.get(provider)
        if selected is None:
            return False
        return selected.interrupt(
            backend_session_id=backend_session_id,
            turn_id=turn_id,
            backend_route_id=backend_route_id,
            runtime_options=runtime_options,
        )


def default_execution_services(
    *,
    agent_harness: AgentHarness | None = None,
) -> dict[str, ExecutionServiceAdapter]:
    services: tuple[ExecutionServiceAdapter, ...] = (
        AgentSessionService(harness=agent_harness),
        ChatCompletionService(),
    )
    return {service.service_type: service for service in services}

def _requeue_abandoned_provider_work(
    self, connection: Any, row: Any, *,
    cancelled_error: str = "execution cancellation finalized after worker lease expired",
) -> bool:
    """A lost Worker's Provider work is interrupted before its execution ends.

    The Provider runs a turn outside the Worker (Codex app server, Claude
    Code daemon, DSH process, Kimi server), so it keeps running when its
    Worker dies.  A turn or compaction that cannot be resumed (cancelled,
    or its turn not yet confirmed by the Provider) would otherwise end
    while its Provider work goes on, and the Resident would look idle.
    It returns to the queue marked ``abandoned``: the next Worker only
    interrupts that work and then ends the execution as failed (or
    cancelled).  The execution stays active until then.
    """

    checkpoint = _object(row["checkpoint_json"])
    status = str(row["status"])
    cancel_requested = bool(row["cancel_requested"])
    abandoned = checkpoint.get("abandoned")
    if isinstance(abandoned, dict):
        if status == "running":
            # The Worker sent to interrupt was lost too: end it as decided.
            details = {"reason": "worker lost while interrupting abandoned provider work",
                       "previous_worker_id": str(row["owner_worker_id"] or "")}
            if abandoned.get("status") == "cancelled":
                self._finalize_released_cancellation(
                    connection, row, error=str(abandoned.get("error") or "cancelled"), details=details,
                )
                return True
            return False
        # Waiting to be interrupted: a cancellation does not end it early.
        if status != "queued" or not cancel_requested:
            return False
        abandoned = {**abandoned, "status": "cancelled"}
    else:
        if status != "running" and not _turn_kept_running(checkpoint):
            return False
        if not cancel_requested and checkpoint.get("resumable"):
            return False
        # Only a Provider turn or compaction can still be running for this
        # execution; the Worker may have died before it learned any id.
        request = _object(row["request_json"])
        if (
            str(request.get("service_type") or "") != "agent_session"
            or str(request.get("operation") or "") not in {"turn", "compact"}
        ):
            return False
        abandoned = {
            "status": "cancelled" if cancel_requested else "failed",
            "error": (
                cancelled_error if cancel_requested else
                "execution worker lease expired after backend execution started"
            ),
            "previous_worker_id": str(row["owner_worker_id"] or ""),
        }
    execution_id = str(row["execution_id"])
    connection.execute(
        "\n            UPDATE executions\n            SET status = 'queued', cancel_requested = 0, checkpoint_json = %s,\n                owner_worker_id = '', claim_token = '', lease_expires_at = NULL,\n                updated_at = %s\n            WHERE execution_id = %s\n            ",
        (_json({**checkpoint, "resumable": False, "abandoned": abandoned}), execution_timestamp(), execution_id),
    )
    self._event(
        connection,
        execution_id,
        "requeued",
        {
            "reason": "worker lost; interrupt its provider work before ending",
            "previous_worker_id": str(row["owner_worker_id"] or ""),
            "abandoned": abandoned,
        },
    )
    return True

class ChatCompletionService:
    service_type = "chat_completion"

    def __init__(
        self,
        provider_registry: AIProviderRegistry | None = None,
    ) -> None:
        self.provider_registry = (
            provider_registry or shared_ai_provider_registry
        )

    def execute(
        self,
        invocation: BackendInvocation,
        context: BackendContext,
    ) -> BackendResult:
        transport: dict[str, Any] = {}
        try:
            return self._execute(invocation, context, transport)
        except Exception as exc:
            if transport.get("schema"):
                existing = getattr(exc, "error_details", {})
                exc.error_details = {**(existing if isinstance(existing, dict) else {}), "provider_transport": transport}
            raise

    def _execute(
        self, invocation: BackendInvocation, context: BackendContext, transport: dict[str, Any],
    ) -> BackendResult:
        request = invocation.request
        if context.is_cancelled():
            raise InterruptedError("execution was cancelled before provider call")
        options = request.runtime_options
        provider_id = request.provider
        item = self.provider_registry.get(provider_id)
        raw_messages = options.get("messages")
        messages = [
            dict(message)
            for message in raw_messages
            if isinstance(message, dict)
        ] if isinstance(raw_messages, list) else []
        if invocation.attach_system_context:
            messages.insert(
                0,
                {
                    "role": "system",
                    "content": invocation.system_context,
                },
            )
        business_system_prompt = str(options.get("system_prompt") or "").strip()
        if business_system_prompt:
            insert_at = 1 if invocation.attach_system_context else 0
            messages.insert(
                insert_at,
                {"role": "system", "content": business_system_prompt},
            )
        if messages and messages[-1].get("role") == "user":
            messages[-1]["content"] = invocation.user_prompt
        else:
            messages.append({"role": "user", "content": invocation.user_prompt})
        parameters = (
            dict(options.get("parameters"))
            if isinstance(options.get("parameters"), dict)
            else {}
        )
        from .model_api_protocols import protocol_adapter
        adapter = protocol_adapter(str(item.get("kind") or "openai_compatible_chat"))
        adapter.validate(parameters, require_questions=True)
        model = str(options.get("model") or item.get("default_model") or "").strip()
        if not model:
            raise ValueError(f"LLM provider model is missing: {provider_id}")
        if options.get("context_history"):
            context.emit("context_history", options["context_history"])
        result = adapter.execute(
            self.provider_registry, {**item, "id": provider_id}, model, messages, parameters,
            float(options.get("timeout_seconds") or 120), max(0, int(options.get("max_retries") or 0)),
            context.is_cancelled, transport.update, lambda call: _until_cancelled(call, context.is_cancelled),
        )
        return self._result(context, provider_id, model, result.response, result.content, transport,
                            structured=result.structured)

    def _result(self, context, provider_id, model, response, content, transport, *, structured=None):
        usage = (
            dict(response.get("usage"))
            if isinstance(response.get("usage"), dict)
            else {}
        )
        usage.update(
            {
                "api_id": provider_id,
                "model": str(model),
            }
        )
        context.emit(
            "provider_output",
            {"text": content, "final": True,
             "request_timing": {key: transport.get(key) for key in ("started_at", "finished_at")}},
        )
        return BackendResult(
            output={
                "message": content,
                "service_type": self.service_type,
                "provider": provider_id,
                "response": response,
                **({"structured": structured} if structured is not None else {}),
                **({"provider_transport": transport} if transport.get("schema") else {}),
            },
            usage=usage,
        )

    def interrupt(
        self,
        *,
        provider: str,
        backend_session_id: str,
        turn_id: str,
        backend_route_id: str,
        runtime_options: dict[str, Any],
    ) -> bool:
        return False

def _append_sequence_ids(
    cls,
    connection: Any,
    *,
    sequence: Any,
    segment_ids: Iterable[str],
    actor_ref: str,
) -> list[str]:
    requested = list(dict.fromkeys(
        str(value or "").strip()
        for value in segment_ids
        if str(value or "").strip()
    ))
    if not requested:
        return []
    found = cls._existing_segment_ids(connection, requested)
    missing = [item for item in requested if item not in found]
    if missing:
        raise KeyError(missing[0])
    sequence_id = str(sequence["sequence_id"])
    # MAX(ordinal) + 1 is safe only while this Sequence's parent row is
    # locked. Unrelated Sequences still append in parallel.
    locked = connection.execute(
        'SELECT sequence_id FROM sequences WHERE sequence_id = %s FOR UPDATE',
        (sequence_id,),
    ).fetchone()
    if locked is None:
        raise RuntimeError("Sequence disappeared during append")
    selected: set[str] = set()
    for chunk in _batches(requested):
        placeholders = ",".join("%s" for _ in chunk)
        selected.update(
            str(row["segment_id"])
            for row in connection.execute(
                f"SELECT segment_id FROM sequence_segments "
                f"WHERE sequence_id = %s AND segment_id IN ({placeholders})",
                [sequence_id, *chunk],
            ).fetchall()
        )
    additions = [item for item in requested if item not in selected]
    if not additions:
        return []
    base = next_position(connection, sequence_id) - 1
    connection.executemany(
        'INSERT INTO sequence_segments(sequence_id, ordinal, segment_id) VALUES (%s, %s, %s)',
        [
            (sequence_id, base + index, segment_id)
            for index, segment_id in enumerate(additions, 1)
        ],
    )
    chat_position_index.upsert_segments(connection, sequence_id, additions)
    cls._touch_sequence(connection, sequence_id, actor_ref)
    return additions

def fork_agent(
    self, *, source_agent_id: str, target_agent_id: str,
    segment_ids: Sequence[str], actor_ref: str,
) -> dict[str, Any]:
    """Materialize the selected immutable references, never a parent's prefix.

    The creation owner freezes selection before publishing the child. Retries
    verify the same selection even after the child has started working.
    """
    source_id, target_id = str(source_agent_id).strip(), str(target_agent_id).strip()
    identities = list(segment_ids)
    if not source_id or not target_id or source_id == target_id:
        raise ValueError("Agent fork requires distinct source and target identities")
    if len(identities) != len(set(identities)):
        raise ValueError("Fork selection contains repeated Segment identities")

    def write(connection: Any) -> dict[str, Any]:
        if self._agent_trace(connection, source_id) is None:
            raise ValueError("Fork source Agent is not registered")
        target_sequence_id = self._locked_trace(connection, target_id, actor_ref)
        if len(self._existing_segment_ids(connection, identities)) != len(identities):
            raise ValueError("Fork selection contains unknown Segments")
        operation_id = stable_segment_id("fork", target_id)
        facts = {"source_agent_id": source_id, "segment_count": len(identities),
                 "selection_sha256": hashlib.sha256(canonical_json(identities).encode()).hexdigest()}
        receipt = connection.execute("SELECT operation_id FROM agent_operations WHERE operation_id=%s", (operation_id,)).fetchone()
        if not receipt:
            existing = self._sequence_ids(connection, target_sequence_id)
            if existing and existing != identities:
                raise ValueError("Fork target already contains different work")
            if not existing:
                self._append_sequence_ids(connection, sequence={"sequence_id": target_sequence_id},
                                          segment_ids=identities, actor_ref=actor_ref)
        put_operation(connection, operation_id=operation_id, kind="forked", agent_id=target_id,
                      created_at=utc_now(), data=facts)
        return {"source_agent_id": source_id, "target_agent_id": target_id,
                "trace_sequence_id": target_sequence_id, "segment_count": len(identities)}

    return self.database.write(write)

def message_facts(message: Mapping[str, Any]) -> dict[str, Any]:
    facts = {key: value for key, value in message.items()
             if key not in {"content_parts", "segment_id", "usage", "provider_response"}}
    # Attachments retain their order relative to text without storing that text.
    facts["parts"] = [
        {"type": "text", "length": len(str(part.get("text") or ""))} if part.get("type") == "text" else dict(part)
        for part in message.get("content_parts", ()) if isinstance(part, Mapping)
    ]
    return facts


def content_text(content: Any) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, Mapping):
        parts = content.get("content")
        if isinstance(parts, list):
            return "\n".join(str(part.get("text", "")) for part in parts
                             if isinstance(part, Mapping) and part.get("type") in {"input_text", "text"})
    return str(content or "")


def project_message(segment_id: object, facts: Mapping[str, Any], content: Any) -> dict[str, Any]:
    message = {key: value for key, value in facts.items() if key != "parts"}
    text = content_text(content)
    if facts.get("role") == "user" or facts.get("harness_input"):
        text = unwrap_message(text)
    parts: list[dict[str, Any]] = []
    templates = facts.get("parts", ({"type": "text"},))
    texts = [part for part in templates if part.get("type") == "text"]
    original_length = (
        sum(part["length"] for part in texts) + len(texts) - 1
        if texts and all("length" in part for part in texts) else None
    )
    exact = original_length == len(text)
    quote = facts.get("quote")
    if facts.get("role") == "user" and isinstance(quote, Mapping) and quote and not exact:
        # Original message text is already the body. Composed input also carries
        # the accepted quote; remove only its complete matching envelope.
        text = _unwrap_quote(text, quote)
        exact = original_length == len(text)
    inserted, offset = False, 0
    for part in templates:
        if part.get("type") == "text":
            if exact:
                length = part["length"]
                parts.append({"type": "text", "text": text[offset:offset + length]})
                offset += length + 1
            elif not inserted:
                parts.append({"type": "text", "text": text})
            inserted = True
        else:
            parts.append(dict(part))
    if text and not inserted:
        parts.insert(0, {"type": "text", "text": text})
    message.update(segment_id=str(segment_id), content_parts=parts)
    return message

def read_chat_messages(
    self,
    agent_id: str,
    *,
    limit: int = 0,
) -> list[dict[str, Any]]:
    """The Agent's Chat, oldest first; the newest ``limit`` messages when given."""

    with self._conversation_read() as connection:
        sequence_id = self._trace_id(connection, agent_id)
        if not sequence_id:
            return []
        return self._chat_from_rows(self._chat_rows(
            connection, sequence_id, after=self._chat_floor(connection, sequence_id),
            limit=max(0, int(limit)),
        ))

def reserve_execution(
    self, *, execution_id: str, agent_id: str, actor_ref: str, provider: str,
    created_at: str = "",
) -> dict[str, Any]:
    """Create the single execution identity before preparing its request.

    Preparation and pre-start cancellation are part of execution history.
    The queue and worker use this identity; they never allocate a second
    Resident job or turn identity.
    """
    if not all((execution_id, agent_id, actor_ref, provider)):
        raise ValueError("Execution reservation requires identity, agent, actor and provider")

    def write(connection: Any) -> dict[str, Any]:
        connection.execute(
            "INSERT INTO executions(execution_id,agent_id,actor_ref,provider,provider_session_ref,"
            "provider_turn_id,created_at,started_at,finished_at,status,usage_json) "
            "VALUES(%s,%s,%s,%s,NULL,'',%s,NULL,NULL,'preparing','{}') "
            "ON CONFLICT(execution_id) DO NOTHING",
            (execution_id, agent_id, actor_ref, provider, created_at or utc_now()),
        )
        row = connection.execute("SELECT * FROM executions WHERE execution_id=%s FOR UPDATE", (execution_id,)).fetchone()
        if (row["agent_id"], row["actor_ref"], row["provider"]) != (agent_id, actor_ref, provider):
            raise ValueError("Execution identity refers to different immutable provenance")
        return self._execution_record(row)

    return self.database.write(write)

def queue_execution(self, execution_id: str) -> None:
    """Mark request admission; retries cannot rewind a started execution."""
    def write(connection: Any) -> None:
        row = connection.execute("SELECT status FROM executions WHERE execution_id=%s FOR UPDATE", (execution_id,)).fetchone()
        if row is None:
            raise KeyError(execution_id)
        if row["status"] == "preparing":
            connection.execute("UPDATE executions SET status='queued' WHERE execution_id=%s", (execution_id,))
    self.database.write(write)

def begin_execution(
    self,
    *,
    execution_id: str,
    agent_id: str,
    actor_ref: str,
    provider: str,
    started_at: str,
) -> dict[str, Any]:
    clean_execution_id = str(execution_id or "").strip()
    if not clean_execution_id:
        raise ValueError("Execution identity is required")
    identity = (
        str(agent_id or ""),
        str(actor_ref or ""),
        str(provider or ""),
        instant(started_at or utc_now()),
    )

    def write(connection: Any) -> dict[str, Any]:
        existing = connection.execute(
            'SELECT * FROM executions WHERE execution_id = %s',
            (clean_execution_id,),
        ).fetchone()
        if existing is not None:
            existing_identity = (
                str(existing["agent_id"]),
                str(existing["actor_ref"]),
                str(existing["provider"]),
            )
            if existing_identity != identity[:3]:
                raise ValueError(
                    "Execution identity refers to different immutable provenance"
                )
            if existing["status"] in {"preparing", "queued"}:
                connection.execute(
                    "UPDATE executions SET status='running',started_at=%s WHERE execution_id=%s",
                    (identity[3], clean_execution_id),
                )
                existing = connection.execute("SELECT * FROM executions WHERE execution_id=%s", (clean_execution_id,)).fetchone()
            elif existing["started_at"] != identity[3]:
                raise ValueError("Execution identity refers to different immutable provenance")
            return self._execution_record(existing)
        connection.execute(
            "INSERT INTO executions(execution_id,agent_id,actor_ref,provider,provider_session_ref,"
            "provider_turn_id,created_at,started_at,finished_at,status,usage_json) "
            "VALUES(%s,%s,%s,%s,NULL,'',%s,%s,NULL,'running','{}')",
            (
                clean_execution_id,
                identity[0],
                identity[1],
                identity[2],
                identity[3],
                identity[3],
            ),
        )
        created = connection.execute(
            'SELECT * FROM executions WHERE execution_id = %s',
            (clean_execution_id,),
        ).fetchone()
        if created is None:
            raise RuntimeError("Execution creation did not produce a record")
        return self._execution_record(created)

    return self.database.write(write)

def record_input_acceptance(
    self, execution_id: str, *, agent_id: str, provider_turn_id: str,
) -> None:
    turn_id = str(provider_turn_id or "").strip()
    if not turn_id:
        raise ValueError("Provider input acceptance requires a turn identity")

    def write(connection: Any) -> None:
        execution = connection.execute(
            'SELECT * FROM executions WHERE execution_id = %s FOR UPDATE',
            (execution_id,),
        ).fetchone()
        if execution is None or execution["agent_id"] != agent_id:
            raise KeyError(execution_id)
        if execution["provider_turn_id"] == turn_id:
            self._record_session_input_acceptance(connection, execution)
            return
        if execution["status"] != "running":
            raise ValueError("Execution terminal fact cannot be changed")
        connection.execute(
            'UPDATE executions SET provider_turn_id = %s WHERE execution_id = %s',
            (turn_id, execution_id),
        )
        self._record_session_input_acceptance(
            connection, {**dict(execution), "provider_turn_id": turn_id},
        )

    self.database.write(write)

def bind_provider_session(
    self,
    binding_id: str,
    provider_session_ref: str,
    *,
    context_fingerprint: object = _FIELD_NOT_PROVIDED,
    context_injected_at: object = _FIELD_NOT_PROVIDED,
    context_injection_count: object = _FIELD_NOT_PROVIDED,
    harness_tool_names: object = _FIELD_NOT_PROVIDED,
) -> dict[str, Any]:
    clean_binding = str(binding_id or "").strip()
    clean_session_ref = str(provider_session_ref or "").strip()
    if not clean_binding or not clean_session_ref:
        raise ValueError("Provider binding and Session identities are required")

    def write(connection: Any) -> dict[str, Any]:
        if connection.execute(
            'SELECT 1 FROM provider_sessions WHERE provider_session_ref = %s',
            (clean_session_ref,),
        ).fetchone() is None:
            raise KeyError(clean_session_ref)
        existing = self._provider_binding_row(connection, clean_binding)
        at = utc_now()
        fingerprint = (
            str(existing["context_fingerprint"] or "")
            if existing is not None and context_fingerprint is _FIELD_NOT_PROVIDED
            else str("" if context_fingerprint is _FIELD_NOT_PROVIDED else context_fingerprint or "")
        )
        injected_at = (
            (iso_time(existing["context_injected_at"]) or "")
            if existing is not None and context_injected_at is _FIELD_NOT_PROVIDED
            else str("" if context_injected_at is _FIELD_NOT_PROVIDED else context_injected_at or "")
        )
        injection_count = (
            int(existing["context_injection_count"] or 0)
            if existing is not None and context_injection_count is _FIELD_NOT_PROVIDED
            else max(0, int(0 if context_injection_count is _FIELD_NOT_PROVIDED else context_injection_count or 0))
        )
        tools_json = (
            str(existing["harness_tool_names_json"] or "[]")
            if existing is not None and harness_tool_names is _FIELD_NOT_PROVIDED
            else canonical_json(clean_string_tuple(
                () if harness_tool_names is _FIELD_NOT_PROVIDED else harness_tool_names
            ))
        )
        if existing is None:
            connection.execute(
                '\n                    INSERT INTO provider_bindings(\n                        binding_id, provider_session_ref, context_fingerprint,\n                        context_injected_at, context_injection_count,\n                        harness_tool_names_json, created_at, updated_at\n                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)\n                    ',
                (
                    clean_binding,
                    clean_session_ref,
                    fingerprint,
                    instant(injected_at),
                    injection_count,
                    tools_json,
                    at,
                    at,
                ),
            )
        else:
            if str(existing["provider_session_ref"]) != clean_session_ref:
                raise ValueError("Provider binding identity is immutable")
            connection.execute(
                '\n                    UPDATE provider_bindings\n                    SET context_fingerprint = %s, context_injected_at = %s,\n                        context_injection_count = %s, harness_tool_names_json = %s,\n                        updated_at = %s\n                    WHERE binding_id = %s\n                    ',
                (
                    fingerprint,
                    instant(injected_at),
                    injection_count,
                    tools_json,
                    at,
                    clean_binding,
                ),
            )
        row = self._provider_binding_row(connection, clean_binding)
        if row is None:
            raise RuntimeError("Provider binding write did not produce a record")
        return self._provider_binding_record(row)

    return self.database.write(write)

def replace_provider_binding(
    self,
    binding_id: str,
    prepared_binding_id: str,
    *,
    expected_provider: str = "",
    expected_backend_session_id: str = "",
    expected_provider_session_ref: str = "",
    expected_absent: bool = False,
) -> dict[str, Any]:
    canonical = str(binding_id or "").strip()
    prepared = str(prepared_binding_id or "").strip()
    if not canonical or not prepared or canonical == prepared:
        raise ValueError("Provider binding replacement requires distinct identities")
    if expected_absent and (
        expected_provider or expected_backend_session_id or expected_provider_session_ref
    ):
        raise ValueError("An expected absent binding cannot also have an expected identity")

    def write(connection: Any) -> dict[str, Any]:
        previous_row = self._provider_binding_row(connection, canonical)
        prepared_row = self._provider_binding_row(connection, prepared)
        if expected_absent and previous_row is not None:
            raise RuntimeError("Provider binding changed before replacement")
        if previous_row is None and not expected_absent:
            raise KeyError(f"Provider binding not found: {canonical}")
        if prepared_row is None:
            raise KeyError(f"Prepared Provider binding not found: {prepared}")
        if (
            expected_provider_session_ref
            and str(previous_row["provider_session_ref"]) != expected_provider_session_ref
        ):
            raise RuntimeError("Provider binding changed before replacement")
        if expected_provider and str(previous_row["provider"]) != expected_provider:
            raise RuntimeError("Provider binding changed before replacement")
        if (
            expected_backend_session_id
            and str(previous_row["backend_session_id"]) != expected_backend_session_id
        ):
            raise RuntimeError("Provider binding changed before replacement")
        previous = self._provider_binding_record(previous_row) if previous_row is not None else {}
        connection.execute(
            'DELETE FROM provider_bindings WHERE binding_id = %s', (canonical,)
        )
        connection.execute(
            'UPDATE provider_bindings SET binding_id = %s, updated_at = %s WHERE binding_id = %s',
            (canonical, utc_now(), prepared),
        )
        current_row = self._provider_binding_row(connection, canonical)
        if current_row is None:
            raise RuntimeError("Provider binding replacement did not produce a record")
        return {
            "previous_binding": previous,
            "current_binding": self._provider_binding_record(current_row),
        }

    return self.database.write(write)

def restore_provider_binding(
    self,
    binding_id: str,
    *,
    expected_provider_session_ref: str,
    binding: Mapping[str, Any],
    expected_absent: bool = False,
) -> dict[str, Any]:
    canonical = str(binding_id or "").strip()
    expected = str(expected_provider_session_ref or "").strip()
    previous_ref = str(binding.get("provider_session_ref") or "").strip()
    if not canonical or (not expected and not expected_absent) or not previous_ref:
        raise ValueError("Provider binding restoration requires explicit current and prior state")

    def write(connection: Any) -> dict[str, Any]:
        current = self._provider_binding_row(connection, canonical)
        if expected_absent:
            if current is not None:
                raise RuntimeError("Provider binding changed after detachment")
            connection.execute(
                "INSERT INTO provider_bindings (binding_id, provider_session_ref, created_at, updated_at, "
                "context_fingerprint, context_injected_at, context_injection_count, harness_tool_names_json) "
                "VALUES (%s,%s,%s,%s,'',NULL,0,'[]')",
                (canonical, previous_ref, utc_now(), utc_now()),
            )
            current = self._provider_binding_row(connection, canonical)
        if current is None or str(current["provider_session_ref"]) != (previous_ref if expected_absent else expected):
            raise RuntimeError("Provider binding changed after replacement")
        if connection.execute(
            'SELECT 1 FROM provider_sessions WHERE provider_session_ref = %s',
            (previous_ref,),
        ).fetchone() is None:
            raise KeyError(previous_ref)
        at = utc_now()
        connection.execute(
            '\n                UPDATE provider_bindings\n                SET provider_session_ref = %s, context_fingerprint = %s,\n                    context_injected_at = %s, context_injection_count = %s,\n                    harness_tool_names_json = %s, updated_at = %s\n                WHERE binding_id = %s\n                ',
            (
                previous_ref,
                str(binding.get("context_fingerprint") or ""),
                instant(str(binding.get("context_injected_at") or "")),
                max(0, int(binding.get("context_injection_count") or 0)),
                canonical_json(clean_string_tuple(binding.get("harness_tool_names"))),
                at,
                canonical,
            ),
        )
        row = self._provider_binding_row(connection, canonical)
        if row is None:
            raise RuntimeError("Provider binding restoration did not produce a record")
        return self._provider_binding_record(row)

    return self.database.write(write)

def delete_provider_binding(
    self, binding_id: str, *, expected_provider_session_ref: str = "",
) -> None:
    clean_id = str(binding_id or "").strip()
    if not clean_id:
        return

    def write(connection: Any) -> None:
        current = self._provider_binding_row(connection, clean_id)
        if current is None:
            return
        if (
            expected_provider_session_ref
            and str(current["provider_session_ref"]) != expected_provider_session_ref
        ):
            raise RuntimeError("Provider binding changed before release")
        connection.execute(
            'DELETE FROM provider_bindings WHERE binding_id = %s', (clean_id,)
        )

    self.database.write(write)

def prepare(
    self,
    request: ExecutionRequest,
    *,
    recovery: bool = False,
) -> RuntimeSession:
    options = request.session.validate()
    backend_session_id = ""
    backend_route_id = str(options.backend_route_id or "")
    session_context: dict[str, Any] = {}
    destination_exists = False
    if options.mode == "persistent":
        destination = self.provider_binding(options.binding_id)
        destination_exists = bool(destination)
        binding_kind, separator, binding_owner_id = str(
            options.binding_id or ""
        ).partition(":")
        binding_agent_id = (
            binding_owner_id
            if binding_kind == "resident" and separator and binding_owner_id
            else str(destination.get("agent_id") or "")
        )
        request_agent_id = str(request.agent_id or "")
        if (
            binding_kind == "resident"
            and request_agent_id == str(options.binding_id or "")
        ):
            request_agent_id = binding_owner_id
        if (
            destination
            and request_agent_id
            and binding_agent_id
            and request_agent_id != binding_agent_id
        ):
            raise ValueError("Agent session belongs to another agent")
        if destination and destination["provider"] != request.provider:
            raise ValueError("Agent session belongs to another provider")
        if (
            request.operation in {"create", "fork"}
            and destination
            and not recovery
        ):
            raise ValueError(
                f"Agent session already exists: {options.binding_id}"
            )
        if request.operation in {"compact", "release"} and not destination:
            raise KeyError(
                f"Agent session not found: {options.binding_id}"
            )
        if destination:
            backend_session_id = str(
                destination["backend_session_id"] or ""
            )
            backend_route_id = str(
                destination.get("backend_route_id") or ""
            ) or backend_route_id
            session_context = destination
    if options.context_source_binding_id and not destination_exists:
        source_binding = self.provider_binding(
            options.context_source_binding_id
        )
        if not source_binding:
            raise KeyError(
                "execution context source binding not found: "
                f"{options.context_source_binding_id}"
            )
        if source_binding["provider"] != request.provider:
            raise ValueError(
                "execution context source belongs to another provider"
            )
        backend_session_id = str(
            source_binding["backend_session_id"] or ""
        )
        source_route_id = str(
            source_binding.get("backend_route_id") or ""
        )
        if (
            backend_route_id
            and source_route_id
            and backend_route_id != source_route_id
        ):
            raise ValueError(
                "execution context source belongs to another backend route"
            )
        backend_route_id = source_route_id or backend_route_id
        session_context = source_binding
    return RuntimeSession(
        mode=options.mode,
        binding_id=options.binding_id,
        backend_session_id=backend_session_id,
        backend_route_id=backend_route_id,
        is_new_backend_session=(
            options.mode == "stateless" or not destination_exists
        ),
        context_fingerprint=str(
            session_context.get("context_fingerprint") or ""
        ),
        context_injected_at=str(
            session_context.get("context_injected_at") or ""
        ),
        context_injection_count=int(
            session_context.get("context_injection_count") or 0
        ),
        harness_tool_names=clean_string_tuple(
            session_context.get("harness_tool_names")
        ),
        provider_session_ref=str(session_context.get("provider_session_ref") or ""),
    )

def replace_unaccepted_session(
    self, request: ExecutionRequest, session: RuntimeSession, *,
    backend_session_id: str, backend_route_id: str,
) -> dict[str, Any]:
    """Replace a lost empty provider session before its first input arrives.

    The caller establishes that the provider lost the thread. The binding
    still has to name the prepared session and must have accepted no input;
    another job's replacement or an existing conversation cannot be reset.
    """
    if session.mode != "persistent" or not session.provider_session_ref:
        raise ValueError("Empty session recovery requires an existing binding")
    if backend_route_id != session.backend_route_id:
        raise ValueError("Empty session recovery cannot change provider route")

    def write(connection: Any) -> dict[str, Any]:
        row = connection.execute(
            "SELECT provider_session_ref FROM provider_bindings WHERE binding_id=%s FOR UPDATE",
            (session.binding_id,),
        ).fetchone()
        if row is None or row["provider_session_ref"] != session.provider_session_ref:
            raise RuntimeError("Provider binding changed before empty session recovery")
        if self.has_accepted_input(session.binding_id, agent_id=request.agent_id):
            raise RuntimeError("Cannot replace a provider session that accepted input")
        prepared = f"recovery:{request.execution_id}"
        self.bind_session(
            prepared, provider=request.provider, backend_route_id=backend_route_id,
            backend_session_id=backend_session_id,

        )
        return self.replace_session(session.binding_id, prepared, expected_binding={
            "provider_session_ref": session.provider_session_ref,
            "provider": request.provider, "backend_session_id": session.backend_session_id,
        })

    return self.agent_data.database.write(write)

def replace_session(
    self,
    binding_id: str,
    prepared_binding_id: str,
    *,
    expected_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if expected_binding is not None and not isinstance(expected_binding, Mapping):
        raise ValueError("Expected session binding must be an object")
    expected = expected_binding or {}
    return self.agent_data.replace_provider_binding(
        binding_id,
        prepared_binding_id,
        expected_provider=str(expected.get("provider") or ""),
        expected_backend_session_id=str(expected.get("backend_session_id") or ""),
        expected_provider_session_ref=str(expected.get("provider_session_ref") or ""),
        expected_absent=expected_binding is not None and not expected_binding,
    )

def restore_session(
    self, binding_id: str, replacement: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(replacement, Mapping):
        raise ValueError("Session replacement must be an object")
    current = replacement.get("current_binding")
    previous = replacement.get("previous_binding")
    if not isinstance(current, Mapping) or not isinstance(previous, Mapping):
        raise ValueError("Provider binding replacement state is incomplete")
    if current.get("binding_id") != binding_id or (previous and previous.get("binding_id") != binding_id):
        raise ValueError("Provider binding replacement belongs to another identity")
    if not previous:
        current_ref = str(current.get("provider_session_ref") or "")
        if not current_ref:
            raise ValueError("Provider binding restoration requires explicit current state")
        self.agent_data.delete_provider_binding(binding_id, expected_provider_session_ref=current_ref)
        return {}
    return self.agent_data.restore_provider_binding(
        binding_id,
        expected_provider_session_ref=str(current.get("provider_session_ref") or ""),
        binding=previous,
        expected_absent=current.get("detached") is True,
    )

def release_session(
    self, binding_id: str, *, expected_provider_session_ref: str = "",
) -> None:
    self.agent_data.delete_provider_binding(
        binding_id, expected_provider_session_ref=expected_provider_session_ref,
    )

def observe_runtime_event(
    self,
    execution_id: str,
    event_type: str,
    details: Mapping[str, Any],
) -> None:
    with self._lock:
        projection = self._active.get(execution_id)
    if projection is None:
        return
    if event_type == "provider_input_bound":
        if projection.request.operation not in {"turn", "generate"}:
            return
        projection.turn_id = str(details.get("turn_id") or "")
        if not projection.turn_id.strip():
            raise ValueError("Provider input acceptance requires a turn identity")
        resolved_backend_session_id = str(
            details.get("backend_session_id")
            or projection.session.backend_session_id
            or ""
        )
        if (
            not resolved_backend_session_id
            and projection.request.session.mode == "stateless"
        ):
            resolved_backend_session_id = projection.request.execution_id
        if not resolved_backend_session_id:
            return
        self._bind_provider_session(
            projection,
            provider=str(details.get("provider") or projection.request.provider),
            backend_session_id=resolved_backend_session_id,
            backend_route_id=str(
                details.get("backend_route_id")
                or projection.session.backend_route_id
            ),
        )
        self.store.record_input_acceptance(
            execution_id, agent_id=projection.agent_id,
            provider_turn_id=projection.turn_id,
        )

def harness_capabilities(self, route: str = "") -> frozenset[str]:
    """Every Harness capability of this Backend, for the given route."""

    capabilities = set(self.harness)
    if self.active_turn_input:
        capabilities.add(ACTIVE_TURN_INPUT)
    if self.media and self.image_input_transport == "native" and self._route_takes_images(route):
        capabilities.add(NATIVE_IMAGE_INPUT)
    return frozenset(capabilities)

def _route_takes_images(self, route: str) -> bool:
    """Some Backends reach several model routes; not all of them read images."""

    if not self.catalog_module:
        return True
    try:
        return bool(self.catalog(route)["capabilities"]["media"])
    except Exception:  # noqa: BLE001 - an unknown route offers no image input
        return False

def runtime_capabilities(self) -> dict[str, Any]:
    return self.runtime_adapter().capabilities(self)

def build_backend(self):
    return self._adapter_class(self.adapter, "management_portal.execution.backends")()

def catalog(self, route: str = "") -> dict[str, Any]:
    if not self.catalog_module:
        from . import account_adapters
        adapter = getattr(account_adapters, self.account_adapter)()
        return adapter.catalog(adapter.resolve(route, {}))
    return import_module(self.catalog_module).catalog(route or self.default_route)

def routes(self) -> list[dict[str, Any]]:
    return import_module(self.catalog_module).routes() if self.catalog_module else []

def validate_settings(self, route: str, model: str, effort: str = "") -> tuple[str, str]:
    catalog = self.catalog(route)
    model = model or catalog["default_model"]
    if model not in catalog["models"]:
        raise ValueError(f"Model {model!r} is not enabled for {self.label}")
    if effort and effort not in catalog.get("efforts_by_model", {}).get(model, []):
        raise ValueError(f"Effort {effort!r} is not supported for {model!r}")
    return model, effort

def capabilities(self, definition):
    # The Harness features this Backend can run follow from what its
    # Adapter can do; no Backend lists features by hand.
    from .harness_capabilities import available_feature_ids
    harness = definition.harness_capabilities()
    return {"schema": "dirtybase.runtime-capabilities.v1",
            "settings": list(definition.runtime_settings),
            "operations": sorted(definition.operations),
            "permission_presets": list(self.permission_labels), "permission_labels": dict(self.permission_labels),
            "default_permission_label": self.permission_labels.get(self.default_permission_preset, ""),
            "harness_capabilities": sorted(harness),
            "harness_features": available_feature_ids(harness)}

def native_permission_mode(self, settings):
    preset = str(settings.get("permission_preset") or self.default_permission_preset)
    return self.native_permission_modes[preset]

def validate_requested_fields(self, definition, updates):
    capabilities = self.capabilities(definition)
    fields = set(capabilities["settings"]) | {"prompt_injection", "allow_subagents", "agent_harness", "prompt_context", "backend_options"}
    from .resident_configuration import normalize_configuration_settings
    normalize_configuration_settings(updates, definition.provider)
    # The switch exists only where the model can start subagents; off is no change elsewhere.
    if updates.get("allow_subagents") is True and "subagents" not in capabilities["harness_capabilities"]:
        raise ValueError(f"{definition.label} does not let its model start subagents")
    if capabilities["permission_presets"]:
        fields.add("permission_preset")
    if "permission_preset" in updates and not updates["permission_preset"]:
        fields.update({"permissions", "approvals_reviewer", "approval_policy", "sandbox", "profile"})
    unsupported = set(updates) - fields
    if unsupported:
        raise ValueError(f"{definition.label} does not support settings: {', '.join(sorted(unsupported))}")
    preset = str(updates.get("permission_preset") or "")
    if preset and preset not in capabilities["permission_presets"]:
        raise ValueError(f"{definition.label} does not support permission preset {preset!r}")
    return fields

def reconcile(self, definition, route, settings):
    catalog = definition.catalog(route)
    model = settings.get("model") or catalog["default_model"]
    if model not in catalog["models"]:
        model = catalog["default_model"]
    effort = settings.get("reasoning_effort", "")
    if effort not in catalog.get("efforts_by_model", {}).get(model, []):
        effort = ""
    return {**settings, "backend": definition.provider, "model": model, "reasoning_effort": effort}

def validate_updates(self, definition, route, current, updates):
    fields = self.validate_requested_fields(definition, updates)
    existing = current if isinstance(current, dict) else {}
    model = str(updates.get("model", existing.get("model", "")))
    effort = str(updates.get("reasoning_effort", existing.get("reasoning_effort", "")))
    if effort and "reasoning_effort" not in updates:
        # A model switch keeps the current effort; a model without it needs
        # the caller's explicit choice (decision_8b2fa224616b).
        model, _ = definition.validate_settings(route, model)
        offered = definition.catalog(route).get("efforts_by_model", {}).get(model, [])
        if effort not in offered:
            raise ValueError(f"{model!r} does not offer reasoning effort {effort!r}; "
                             f"set reasoning_effort with the model to one of {['', *offered]}")
    model, effort = definition.validate_settings(route, model, effort)
    result = {**updates, "model": model}
    if "reasoning_effort" in fields:
        result["reasoning_effort"] = effort
    return result

def prepare(self, invocation):
    raw = invocation.request.runtime_options
    if "runtime_settings" not in raw:
        return invocation
    options = dict(raw)
    settings = options.pop("runtime_settings")
    options.pop("authorization_scope", None)
    from .provider_catalog import AGENT_PROVIDERS
    definition = AGENT_PROVIDERS[invocation.request.provider]
    route = invocation.session.backend_route_id or options.get("provider_profile") or definition.default_route
    model, effort = definition.validate_settings(route, settings.get("model", ""), settings.get("reasoning_effort", ""))
    options.update(model=model, effort=effort, provider_profile=route)
    options["config_dir"] = str(native_config_dir(
        definition.provider, options.pop("runtime_root", ""),
        invocation.request.session.binding_id or invocation.request.execution_id,
    ))
    options = self.native_options(options, settings)
    return replace(invocation, request=replace(invocation.request, runtime_options=options))

def adapter_capabilities(provider: Any, invocation: Any = None) -> frozenset[str]:
    """The capabilities of the Adapter that will run the turn.

    An Adapter object may declare ``harness_capabilities`` itself; otherwise
    the declaration of its Backend in the Provider catalog applies.
    """

    declared = getattr(provider, "harness_capabilities", None)
    if declared is not None and not callable(declared):
        return frozenset(str(item) for item in declared)
    return provider_capabilities(
        getattr(provider, "provider_id", ""),
        _invocation_route(invocation) if invocation is not None else "",
    )


def unmet_requirement(requirement: Requirement, capabilities: Iterable[str]) -> str:
    """``""`` when a feature can be planned, else ``requires_<capability>``.

    The reason names the first capability missing from the feature's first
    alternative, which is the feature's main way of working.
    """

    if not requirement:
        return ""
    available = frozenset(capabilities)
    if any(alternative <= available for alternative in requirement):
        return ""
    missing = sorted(requirement[0] - available)
    return f"requires_{missing[0]}" if missing else ""


def feature_requirement(feature: Any) -> Requirement:
    """A feature's declared requirement; a feature that declares none runs anywhere."""

    raw = getattr(feature, "requires", ())
    if not isinstance(raw, (tuple, list)):
        return ()
    return tuple(
        frozenset(str(item) for item in alternative)
        for alternative in raw
        if isinstance(alternative, (frozenset, set, tuple, list))
    )


def default_feature_requirements() -> dict[str, Requirement]:
    """Requirements of the features ``default_agent_harness`` registers."""

    from .harness import HARNESS_FEATURES
    return {name: feature_requirement(definition.feature_class())
            for name, definition in HARNESS_FEATURES.items()}


def available_feature_ids(capabilities: Iterable[str]) -> list[str]:
    """The registered features a Backend with these capabilities can run."""

    available = frozenset(capabilities)
    return [
        feature_id
        for feature_id, requirement in default_feature_requirements().items()
        if not unmet_requirement(requirement, available)
    ]

def validate(self) -> "ExecutionRequest":
    if self.schema != EXECUTION_SCHEMA:
        raise ValueError("unsupported execution request schema")
    if self.schema_version != EXECUTION_SCHEMA_VERSION:
