    "default_model": "TEXT", "timeout_s": "DOUBLE PRECISION", "max_retries": "INTEGER",
    "cost_tier": "TEXT", "privacy_tier": "TEXT", "priority": "INTEGER",
    "models": "JSONB", "default_headers": "JSONB", "default_parameters": "JSONB",
}
