@lru_cache(maxsize=8)
def _database(dsn, namespace):
    return DomainDatabase("model_apis", "registry", DDL)


def database():
    return _database(os.getenv("PORTAL_DATABASE_URL"), os.getenv("PORTAL_DATABASE_NAMESPACE"))

def route_api_id(backend, route_id):
    with database().read() as c:
        row = c.execute("SELECT api_id FROM routes WHERE backend=%s AND route_id=%s", (backend, route_id)).fetchone()
    return row["api_id"] if row else None


def _bind_routes(c, entry, bindings):
    if not isinstance(bindings, list):
        raise ValueError("Model API routes must be an array")
    keys = []
    for binding in bindings:
        if not isinstance(binding, dict) or set(binding) != {"backend", "route_id"}:
            raise ValueError("A Model API route requires backend and route_id")
        key = (binding["backend"], binding["route_id"])
        if key not in SERVICE_ROUTES or SERVICE_ROUTES[key] != entry.get("provider") or entry.get("kind") != "openai_compatible_chat":
            raise ValueError("Model API does not support the requested service route")
        if key in keys:
            raise ValueError("Duplicate Model API route")
        keys.append(key)
    c.execute("DELETE FROM routes WHERE api_id=%s", (entry["id"],))
    for backend, route_id in keys:
        existing = c.execute("SELECT api_id FROM routes WHERE backend=%s AND route_id=%s", (backend, route_id)).fetchone()
        if existing:
            raise ValueError("Route already bound; remove its existing binding before assigning another API")
        c.execute("INSERT INTO routes(backend,route_id,api_id) VALUES (%s,%s,%s)", (backend, route_id, entry["id"]))

    def _api_runtime_catalog(self, entry: dict[str, Any], *, include_routes: bool = True) -> dict[str, Any]:
        from .account_adapters import ApiProfileAccounts
        from .resident_configuration import api_capabilities
        from .model_api_protocols import protocol_settings

        if not AIProviderRegistry.supports_model_api(entry):
            raise ValueError("backend_route_id must reference an enabled Model API")
        # A native agent and direct API calls can use the same billing account.
        # The selected backend owns model capabilities; the account keeps its
        # single scheduler identity and capacity settings.
        account = self.get(entry["id"])
        result = ApiProfileAccounts(entry).catalog(account)
        capabilities = api_capabilities()
        routes = {"api_routes": [self._api_runtime_catalog(item, include_routes=False)
                  for item in self.provider_registry.entries() if AIProviderRegistry.supports_model_api(item)]} if include_routes else {}
        return {**result, **routes, "schema": "dirtybase.agent-runtime-catalog.v1", "backend": "provider_api",
                "provider": "provider_api", "account_id": account.account_id, "backend_route_id": entry["id"],
                "api_protocol": entry["kind"], "api_settings": protocol_settings(entry),
                "runtime_settings": capabilities["settings"], "operations": [], "runtime_capabilities": capabilities}


def default_execution_accounts(*, account_registry=None, provider_registry=None, tolerate_unavailable=False) -> ExecutionAccounts:
    from . import account_adapters
    from .provider_catalog import AGENT_PROVIDERS
    from management_portal.ai_provider_registry import shared_ai_provider_registry
    adapters = tuple(
        getattr(account_adapters, provider.account_adapter)(account_registry=account_registry, provider_registry=provider_registry)
        if provider.account_adapter else account_adapters.ConfiguredAccounts(provider, tolerate_unavailable=tolerate_unavailable)
        for provider in AGENT_PROVIDERS.values()
    )
    existing = {account.account_id for adapter in adapters for account in adapter.accounts()}
    profiles = tuple(account_adapters.ApiProfileAccounts(entry)
                     for entry in (provider_registry or shared_ai_provider_registry).entries()
                     if AIProviderRegistry.is_enabled(entry) and entry["id"] not in existing)
    return ExecutionAccounts((*adapters, *profiles), provider_registry=provider_registry)

class ApiProfileAccounts:
    """One registered completion profile using the common scheduler policy."""

    def __init__(self, entry):
        self.provider = entry["id"]
        self.entry = entry

    def accounts(self):
        return (ExecutionAccount(self.provider, self.provider, "", f"account:{self.provider}",
                                 billing_account_id=self.provider),)

    def resolve(self, route_id, options, *, bound=False):
        if route_id:
            raise ValueError("API completion accounts do not have native session routes")
        return self.accounts()[0]

    def catalog(self, account):
        models = AIProviderRegistry.models(self.entry)
        default = str(self.entry.get("default_model") or "")
        return {"models": models, "default_model": default, "efforts_by_model": {},
                "default_efforts_by_model": {}, "service_tiers_by_model": {}}

    def observe(self, account, *, force=False):
        return {"status": "ok", "rate_limits": []}

def _until_cancelled(call: Callable[[], Any], cancelled: Callable[[], bool]) -> Any:
    """Wait for one blocking Provider request; a stop ends the wait at once.

    The request runs on in its own daemon thread until its response or its own
    timeout, and what it returns after the stop is dropped: the Provider may
    still bill that response, but the Resident stops now.
    """

    outcome: dict[str, Any] = {}

    def run() -> None:
        try:
            outcome["response"] = call()
        except BaseException as exc:  # noqa: BLE001 - handed to the waiting caller
            outcome["error"] = exc

    worker = threading.Thread(target=run, name="chat-completion-request", daemon=True)
    worker.start()
    while worker.is_alive():
        worker.join(0.25)
        if worker.is_alive() and cancelled():
            raise InterruptedError("execution was cancelled during provider call")
    if "error" in outcome:
        raise outcome["error"]
    return outcome["response"]

def _execute(
    self, invocation: BackendInvocation, context: BackendContext, transport: dict[str, Any],
) -> BackendResult:
    request = invocation.request
    if context.is_cancelled():
        raise InterruptedError("execution was cancelled before provider call")
    options = request.runtime_options
    provider_id = request.provider
    item = self.provider_registry.get(provider_id)
    raw_messages = options.get("messages")
    messages = [
        dict(message)
        for message in raw_messages
        if isinstance(message, dict)
    ] if isinstance(raw_messages, list) else []
    if invocation.attach_system_context:
        messages.insert(
            0,
            {
                "role": "system",
                "content": invocation.system_context,
            },
        )
    business_system_prompt = str(options.get("system_prompt") or "").strip()
    if business_system_prompt:
        insert_at = 1 if invocation.attach_system_context else 0
        messages.insert(
            insert_at,
            {"role": "system", "content": business_system_prompt},
        )
    if messages and messages[-1].get("role") == "user":
        messages[-1]["content"] = invocation.user_prompt
    else:
        messages.append({"role": "user", "content": invocation.user_prompt})
    parameters = (
        dict(options.get("parameters"))
        if isinstance(options.get("parameters"), dict)
        else {}
    )
    from .model_api_protocols import protocol_adapter
    adapter = protocol_adapter(str(item.get("kind") or "openai_compatible_chat"))
    adapter.validate(parameters, require_questions=True)
    model = str(options.get("model") or item.get("default_model") or "").strip()
    if not model:
        raise ValueError(f"LLM provider model is missing: {provider_id}")
    if options.get("context_history"):
        context.emit("context_history", options["context_history"])
    result = adapter.execute(
        self.provider_registry, {**item, "id": provider_id}, model, messages, parameters,
        float(options.get("timeout_seconds") or 120), max(0, int(options.get("max_retries") or 0)),
        context.is_cancelled, transport.update, lambda call: _until_cancelled(call, context.is_cancelled),
    )
    return self._result(context, provider_id, model, result.response, result.content, transport,
                        structured=result.structured)

def _result(self, context, provider_id, model, response, content, transport, *, structured=None):
    usage = (
        dict(response.get("usage"))
        if isinstance(response.get("usage"), dict)
        else {}
    )
    usage.update(
        {
            "api_id": provider_id,
            "model": str(model),
        }
    )
    context.emit(
        "provider_output",
        {"text": content, "final": True,
         "request_timing": {key: transport.get(key) for key in ("started_at", "finished_at")}},
    )
    return BackendResult(
        output={
            "message": content,
            "service_type": self.service_type,
            "provider": provider_id,
            "response": response,
            **({"structured": structured} if structured is not None else {}),
            **({"provider_transport": transport} if transport.get("schema") else {}),
        },
        usage=usage,
    )

def interrupt(
    self,
    *,
    provider: str,
    backend_session_id: str,
    turn_id: str,
    backend_route_id: str,
    runtime_options: dict[str, Any],
) -> bool:
    return False

class ChatProtocol:
    name = "openai_compatible_chat"
    settings_view = "chat"
    default_history = True
    timeout_max = 86400
    parameters = frozenset({"temperature", "top_p", "max_tokens", "max_completion_tokens",
        "stop", "frequency_penalty", "presence_penalty", "seed", "response_format", "thinking", "reasoning_effort"})
    # Only protocol-common controls are inferred. Provider extensions require
    # explicit model metadata in the registry.
    default_controls = ("temperature", "top_p", "max_tokens")

    def validate(self, parameters, *, require_questions=False):
        if "questions" in parameters:
            raise ValueError("questions requires the typesafe_system_one protocol")
        # Resident settings validate their supported keys separately. Other
        # Execution callers may use provider-specific generation parameters.

    def execute(self, registry, item, model, messages, parameters, timeout, retries, cancelled, observe, run):
        payload = {**parameters, "model": model, "messages": messages}
        for attempt in range(retries + 1):
            if cancelled():
                raise InterruptedError("execution was cancelled before provider retry")
            def observed(report):
                if not cancelled():
                    observe({**report, "attempt_number": attempt + 1})
            try:
                response = run(lambda: registry.request(item["id"], "chat/completions", payload,
                    timeout_seconds=timeout, observe_transport=observed))
                break
            except Exception as exc:
                if attempt >= retries or not AIProviderRegistry.retryable_error(exc):
                    raise
                time.sleep(min(2.0, 0.25 * (attempt + 1)))
        choice = (response.get("choices") or [{}])[0]
        message = choice.get("message") if isinstance(choice, dict) else {}
        content = message.get("content") if isinstance(message, dict) else ""
        if isinstance(content, list):
            content = "\n".join(str(part.get("text") or "").strip() for part in content if isinstance(part, dict))
        content = content.strip() if isinstance(content, str) else ""
        if not content:
            raise RuntimeError(f"{item['id']} returned an empty completion")
        return ApiResponse(response, content)

class JevProtocol:
    name = "typesafe_system_one"
    settings_view = "jev"
    default_history = False
    timeout_max = 120
    parameters = frozenset({"questions"})
    default_controls = ()

    def validate(self, parameters, *, require_questions=False):
        from management_portal.jev_provider import validate_questions
        if set(parameters) - self.parameters:
            raise ValueError("Jev accepts questions, not chat generation parameters")
        if "questions" in parameters:
            validate_questions(parameters["questions"])
        elif require_questions:
            raise ValueError("Jev requires backend_options.parameters.questions (choice, score or noul)")

    def execute(self, registry, item, model, messages, parameters, timeout, retries, cancelled, observe, run):
        from management_portal.jev_provider import JevProvider
        response = run(lambda: JevProvider(registry, item["id"]).decide(
            state={"messages": messages}, questions=parameters["questions"], model=model,
            timeout_seconds=timeout, max_retries=retries, configuration=item,
            is_cancelled=cancelled, observe_transport=observe))
        answers = response["answers"]
        return ApiResponse(response, "```json\n" + json.dumps(answers, ensure_ascii=False, indent=2) + "\n```", answers)


PROTOCOLS = {adapter.name: adapter for adapter in (ChatProtocol(), JevProtocol())}


def protocol_adapter(name):
    try:
        return PROTOCOLS[name]
    except KeyError:
        raise ValueError(f"Unsupported Model API protocol: {name}") from None

def configuration(self, item: dict[str, Any] | None = None) -> dict[str, Any]:
    item = self.registry.get(self.provider_id) if item is None else item
    if item.get("id") != self.provider_id or not AIProviderRegistry.is_enabled(item):
        raise ValueError("Jev provider configuration does not match the enabled route")
    if str(item.get("provider") or "").strip().lower() != "typesafe":
        raise ValueError("Jev provider must use the TypeSafe service")
    if str(item.get("kind") or "").strip() != JEV_PROVIDER_KIND:
        raise ValueError("Jev provider requires the typesafe_system_one protocol")
    return item

def enabled_models(self) -> tuple[str, ...]:
    item = self.configuration()
    return tuple(AIProviderRegistry.models(item))

def decide(
    self,
    *,
    state: object,
    questions: object,
    model: str = "",
    timeout_seconds: float | None = None,
    max_retries: int | None = None,
    configuration: dict[str, Any] | None = None,
    is_cancelled=None,
    observe_transport=None,
) -> dict[str, Any]:
    if not isinstance(state, (str, list, dict)):
        raise ValueError("Jev state must be text, an array, or an object")
    clean_questions = validate_questions(questions)
    item = self.configuration(configuration)
    enabled_models = AIProviderRegistry.models(item)
    selected_model = str(model or item.get("default_model") or "").strip()
    if not selected_model or selected_model not in enabled_models:
        raise ValueError(f"Jev model is not enabled: {selected_model or '<empty>'}")
    payload = {
        "state": state,
        "model": selected_model,
        "questions": clean_questions,
    }
    if _json_size(payload) > MAX_REQUEST_BYTES:
        raise ValueError("Jev request exceeds the 2 MB Portal limit")
    timeout = timeout_seconds if timeout_seconds is not None else item.get("timeout_s", 30)
    attempts = 1 + max(0, int(item.get("max_retries") or 0) if max_retries is None else int(max_retries))
    for attempt in range(attempts):
        if is_cancelled and is_cancelled():
            raise InterruptedError("execution was cancelled before Jev call")
        try:
            def observe(report):
                if observe_transport and not (is_cancelled and is_cancelled()):
                    observe_transport({**report, "attempt_number": attempt + 1})

            response = self.registry.request(
                self.provider_id, JEV_ENDPOINT, payload,
                timeout_seconds=max(1.0, min(float(timeout), 120.0)), configuration=item,
                **({"observe_transport": observe} if observe_transport else {}),
            )
            break
        except Exception as exc:
            if attempt + 1 >= attempts or not AIProviderRegistry.retryable_error(exc):
                raise
            time.sleep(min(2.0, 0.25 * (attempt + 1)))
    return self._validate_response(response, clean_questions)

def validate_questions(value: object) -> dict[str, dict[str, Any]]:
    if not isinstance(value, Mapping) or not value:
        raise ValueError("Jev questions must be a non-empty object")
    if len(value) > MAX_QUESTIONS:
        raise ValueError(f"Jev supports at most {MAX_QUESTIONS} questions per call")
    questions: dict[str, dict[str, Any]] = {}
    for raw_id, raw_question in value.items():
        question_id = str(raw_id or "").strip()
        if not question_id or len(question_id) > 120:
            raise ValueError("Jev question IDs must contain 1 to 120 characters")
        if question_id in questions:
            raise ValueError(f"duplicate Jev question ID: {question_id}")
        if not isinstance(raw_question, Mapping):
            raise ValueError(f"Jev question {question_id} must be an object")
        question = dict(raw_question)
        unknown = set(question) - {"type", "instructions", "criteria"}
        if unknown:
            raise ValueError(
                f"Jev question {question_id} has unsupported fields: "
                + ", ".join(sorted(str(item) for item in unknown))
            )
        question_type = str(question.get("type") or "").strip().lower()
        if question_type not in {"choice", "score", "noul"}:
            raise ValueError(
                f"Jev question {question_id} type must be choice, score, or noul"
            )
        normalized: dict[str, Any] = {
            "type": question_type,
            "instructions": _structured_content(
                question.get("instructions"),
                field=f"Jev question {question_id}.instructions",
            ),
        }
        criteria = question.get("criteria")
        if question_type == "choice":
            if not isinstance(criteria, Mapping) or not 1 <= len(criteria) <= 255:
                raise ValueError(
                    f"Jev choice question {question_id} requires 1 to 255 criteria"
                )
            clean_criteria: dict[str, object] = {}
            for raw_label, description in criteria.items():
                label = str(raw_label or "").strip()
                if not label or len(label) > 200:
                    raise ValueError(
                        f"Jev choice question {question_id} has an invalid label"
                    )
                clean_criteria[label] = (
                    None
                    if description is None
                    else _structured_content(
                        description,
                        field=f"Jev choice question {question_id}.{label}",
                    )
                )
            normalized["criteria"] = clean_criteria
        elif question_type == "score":
            if not isinstance(criteria, list) or not 2 <= len(criteria) <= 10:
                raise ValueError(
                    f"Jev score question {question_id} requires 2 to 10 ordered levels"
                )
            normalized["criteria"] = [
                _structured_content(
                    item,
                    field=f"Jev score question {question_id}.criteria[{index}]",
                )
                for index, item in enumerate(criteria)
            ]
        elif criteria is not None:
            if not isinstance(criteria, Mapping) or set(criteria) != {"true", "false"}:
                raise ValueError(
                    f"Jev noul question {question_id} criteria must define true and false"
                )
            normalized["criteria"] = {
                key: _structured_content(
                    criteria[key],
                    field=f"Jev noul question {question_id}.criteria.{key}",
                )
                for key in ("true", "false")
            }
        questions[question_id] = normalized
    return questions

def _validate_response(
    response: object,
    questions: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    if not isinstance(response, dict):
        raise JevProviderError("Jev returned an invalid response")
    model = str(response.get("model") or "").strip()
    answers = response.get("answers")
    usage = response.get("usage")
    if not model or not isinstance(answers, dict) or set(answers) != set(questions):
        raise JevProviderError("Jev response does not match the requested questions")
    if not isinstance(usage, dict):
        raise JevProviderError("Jev response is missing usage")
    for question_id, question in questions.items():
        answer = answers.get(question_id)
        expected_type = question["type"]
        if not isinstance(answer, dict) or answer.get("type") != expected_type:
            raise JevProviderError(
                f"Jev answer type mismatch for question {question_id}"
            )
        if expected_type == "noul":
            _probability(answer.get("noul"), field=f"answers.{question_id}.noul")
        elif expected_type == "choice":
            selected = str(answer.get("choice") or "")
            if selected not in question["criteria"]:
                raise JevProviderError(
                    f"Jev returned an unknown choice for question {question_id}"
                )
            _probability(
                answer.get("confidence"),
                field=f"answers.{question_id}.confidence",
            )
            probabilities = answer.get("probabilities")
            if not isinstance(probabilities, dict) or set(probabilities) != set(question["criteria"]):
                raise JevProviderError(
                    f"Jev choice probabilities mismatch for question {question_id}"
                )
            for label, probability in probabilities.items():
                _probability(
                    probability,
                    field=f"answers.{question_id}.probabilities.{label}",
                )
        else:
            score = answer.get("score")
            if isinstance(score, bool):
                raise JevProviderError(
                    f"Jev score is invalid for question {question_id}"
                )
            try:
                numeric_score = float(score)
            except (TypeError, ValueError) as exc:
                raise JevProviderError(
                    f"Jev score is invalid for question {question_id}"
                ) from exc
            if not math.isfinite(numeric_score) or not 0 <= numeric_score <= len(question["criteria"]) - 1:
                raise JevProviderError(
                    f"Jev score is out of range for question {question_id}"
                )
            _probability(
                answer.get("confidence"),
                field=f"answers.{question_id}.confidence",
            )
    return response

def complete_chat(inv: Invocation) -> dict[str, Any]:
    registry = _registry()
    api_id = inv.argument("api_id")
    item = registry.get(api_id)
    options = dict(inv.argument("options") or {})
    for forbidden in ("model", "messages", "stream"):
        options.pop(forbidden, None)
    messages = list(inv.argument("messages") or [])
    schema = inv.argument("response_schema")
    validator = None
    if schema is not None:
        validator = _response_validator(schema)
        messages.insert(0, {
            "role": "system",
            "content": "只输出一个 JSON 值，它必须满足下面的 JSON Schema；不要输出任何其他文字。\n"
            + json.dumps(schema, ensure_ascii=False),
        })
    payload = {
        "model": inv.argument("model") or str(item.get("default_model") or ""),
        "messages": messages,
        **options,
    }
    if not payload["model"]:
        raise invalid(f"{api_id} 没有默认模型，请提供 model")
    response = registry.request(
        api_id, "chat/completions", payload,
        timeout_seconds=float(item.get("timeout_s") or 120),
    )
    choices = response.get("choices") if isinstance(response.get("choices"), list) else []
    message = choices[0].get("message") if choices and isinstance(choices[0], dict) else None
    if not isinstance(message, dict) or not str(message.get("content") or "").strip():
        raise InstructionError("instruction.failed", f"{api_id} 没有返回消息")
    result: dict[str, Any] = {"message": message, "usage": dict(response.get("usage") or {})}
    if validator is not None:
        result["structured"] = _structured_answer(api_id, message, validator)
    return result

def _parse_allowed_networks(raw: str) -> list[ipaddress._BaseNetwork]:
    networks: list[ipaddress._BaseNetwork] = []
    for item in raw.split(","):
        text = item.strip()
        if not text:
            continue
        try:
            networks.append(ipaddress.ip_network(text, strict=False))
        except ValueError as exc:
            raise SystemExit(f"invalid allowlist entry {text!r}: {exc}") from exc
    return networks


def _peer_allowed(peer_ip: str, networks: list[ipaddress._BaseNetwork]) -> bool:
    try:
        address = ipaddress.ip_address(peer_ip)
    except ValueError:
        return False
    return any(address in network for network in networks)


def _read_exact(sock: socket.socket, size: int, *, deadline: float | None = None) -> bytes:
    chunks: list[bytes] = []
    remaining = size
    while remaining > 0:
        if deadline is not None:
            remaining_time = deadline - time.monotonic()
            if remaining_time <= 0:
                raise TimeoutError("frame read deadline exceeded")
            sock.settimeout(remaining_time)
        chunk = sock.recv(remaining)
        if not chunk:
            raise EOFError
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def _read_frame(sock: socket.socket, max_bytes: int, *, deadline: float | None = None) -> dict[str, Any]:
    header = _read_exact(sock, 4, deadline=deadline)
    (length,) = struct.unpack(">I", header)
    if length <= 0:
        raise RelayFrameError("empty frame")
    if length > max_bytes:
        raise RelayFrameError("frame exceeds configured limit")
    body = _read_exact(sock, length, deadline=deadline)
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError, RecursionError):
        raise RelayFrameError("invalid frame JSON") from None
    if not isinstance(payload, dict):
        raise RelayFrameError("frame JSON must be an object")
    return payload


def _write_frame(sock: socket.socket, payload: dict[str, Any]) -> None:
    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")

def _provider_registry_entry(provider_name: str) -> dict[str, Any]:
    requested = provider_name.strip().lower()
    candidates = [
        item
        for item in _read_llm_registry()
        if str(item.get("provider") or "").strip().lower() == requested
        and str(item.get("kind") or "").strip() == "openai_compatible_chat"
        and AIProviderRegistry.is_enabled(item)
    ]
    for item in candidates:
        if str(item.get("id") or "").strip() == f"{requested}_primary":
            return item
    if candidates:
        return candidates[0]
    raise ValueError(f"{requested} provider not configured")


