def read_resource(inv: Invocation) -> dict[str, Any]:
    import base64

    address = inv.argument("address")
    limit = int(inv.argument("max_bytes") or 4 * 1024 * 1024)
    try:
        data, content_type, resolved = _service().read_content(address, actor=inv.caller, max_bytes=limit)
    except ValueError as exc:
        if "limit" not in str(exc):
            raise
        return _oversized_read(address, inv.caller)
    version = _resource_version(resolved.get("record") or {}) if "/" not in address else ""
    result: dict[str, Any] = {
        "content_type": str(content_type or "application/octet-stream"),
        "version": version or hashlib.sha256(data).hexdigest(),
        "size": len(data),
    }
    try:
        result["text"] = data.decode("utf-8")
    except UnicodeDecodeError:
        result["base64"] = base64.b64encode(data).decode("ascii")
    return result

def update_user(inv: Invocation) -> dict[str, Any]:
    username = inv.argument("username")
    changes = dict(inv.argument("changes") or {})
    unknown = sorted(set(changes) - {"display_name", "recovery_email", "avatar", "status"})
    if unknown:
        raise invalid("changes 只能包含 display_name、recovery_email、avatar 与 status")
    web()._require_authenticated_actor(inv.caller)
    has_avatar = "avatar" in changes
    avatar_payload = changes.pop("avatar", None)
    user: dict[str, Any] = {}
    if changes:
        result = web()._admin_access_action(inv.caller, {
            "action": "update", "username": username,
            "display_name": changes.get("display_name"),
            "email": changes.get("recovery_email"),
            "status": changes.get("status"),
            "revoke_sessions": changes.get("status") == "disabled",
        })
        user = result.get("user") or {}
    result = dict(user or {"username": username, **_access().user(username)})
    if has_avatar:
        result["avatar"] = _set_avatar(username, avatar_payload, inv.caller)
    return {"user": result}

def fork_resident(inv: Invocation) -> dict[str, Any]:
    source = inv.argument("source_resident_id")
    if _family_role(source) == "facade":
        raise InstructionError("instruction.conflict", "Family 门面不能 Fork；请 Fork 具体的成员")
    lineage_id = inv.argument("lineage_id")
    family = _family_to_join(lineage_id, inv)
    fork_mode = inv.argument("fork_mode") or "full"
    if fork_mode == "message" and not inv.argument("message"):
        raise invalid("fork_mode=message 需要 message")
    payload: dict[str, Any] = {
        "source": source,
        "fork_mode": fork_mode,
        **placement(inv, lineage_id),
    }
    for name in ("context_source_resident_id", "message"):
        if inv.argument(name) is not None:
            payload[name] = inv.argument(name)
    if inv.argument("title"):
        payload["child_title"] = inv.argument("title")
    if inv.argument("provider"):
        payload["provider"] = inv.argument("provider")
    account = inv.argument("account")
    if account:
        payload["backend_route_id"] = account
    if inv.idempotency_key:
        payload["idempotency_key"] = inv.idempotency_key
    result = domain().fork_lineage_resident(lineage_id, payload, inv.caller)
    resident_id = str((result.get("created_resident") or {}).get("id") or "")
    return {
        "resident_id": resident_id,
        "lineage_id": lineage_id,
        "inheritance_edge_id": str((result.get("inheritance_edge") or {}).get("id") or ""),
        "created": bool(result.get("created", True)),
        **_join_family(lineage_id, resident_id, family, inv),
    }

def deliver_message(inv: Invocation) -> dict[str, Any]:
    message = inv.argument("message") or {}
    unknown = sorted(set(message) - {"message_id", "role", "content_parts", "quote"})
    if unknown:
        raise invalid("message 只包含 message_id、role、content_parts 和 quote", unknown_fields=unknown)
    if inv.argument("user_id"):
        if "quote" in message or inv.argument("reply_to_message_id"):
            # Only a user message quotes; a message to a user is the sender's own (decision_c524c775e0be).
            raise invalid("发给用户的消息不带引用")
        return deliver_to_user(inv, inv.argument("user_id"), message)
    resident_id = inv.argument("resident_id")
    return deliver(inv, resident_id, message, business_ref=inv.argument("business_ref") or "",
                   reply_to=inv.argument("reply_to_message_id") or "")

