def emit_event(inv: Invocation) -> dict[str, Any]:
    event_type = inv.argument("event_type") or "manual.triggered"
    if event_type != "manual.triggered":
        # Other Event types are facts the runtime observes; they cannot be emitted.
        raise InstructionError(
            "instruction.forbidden", f"{event_type} 由运行时根据真实事实产生，不能用 EmitEvent 伪造",
        )
    result = _event_result(_emit(
        inv,
        event_name=inv.argument("event_name"),
        subject_resident_id=inv.argument("subject_resident_id"),
        payload=inv.argument("payload"),
    ))
    return {"event_id": result["event_id"], "trigger_path_id": result["trigger_path_id"]}

def start(arguments, caller, *, idempotency_key='', trigger_path_id=''):
    args = _validate(arguments)
    activation = deepcopy(ACTIVATION.get())
    lineage_id = str(activation.get('lineage_id') or arguments.get('lineage_id') or '')
    if not lineage_id and caller.startswith('resident_'):
        from ..isa.common import lineage_of_resident
        lineage_id = lineage_of_resident(caller)
    from management_portal.hatg.resource_policy import resource_type
    if resource_type(lineage_id) != 'lineage':
        raise ValueError('RunScript 需要有效的所属 lineage_id')
    if arguments.get('lineage_id') and arguments['lineage_id'] != lineage_id:
        raise ValueError('RunScript lineage_id 与当前激活不符')
    from management_common.authorization_context import subject_payload
    source = Path(args['path']).read_bytes()
    config = {**args, 'authorization': subject_payload()}
    admission = hashlib.sha256((caller + '\0' + idempotency_key).encode()).hexdigest() if idempotency_key else ''
    with store.transaction() as state:
        for row in state['runs'].values():
            if admission and row.get('admission') == admission:
                return _receipt(row)
            if row.get('lineage_id') == lineage_id and args.get('exclusive_key') and row.get('exclusive_key') == args['exclusive_key'] and row['status'] == 'running':
                return {**_receipt(row), 'status': 'already_running'}
        identifier = 'script_run_' + secrets.token_hex(12)
        record = {**args, 'script_run_id': identifier, 'caller_id': caller, 'status': 'running',
                  'lineage_id': lineage_id, 'effect_id': activation.get('effect_id', ''),
                  'trigger_path_id': trigger_path_id, 'identity': activation.get('identity', {}), 'trigger_type': activation.get('trigger_type', ''),
                  'started_at': now(), 'finished_at': '', 'duration_seconds': 0, 'sha256': hashlib.sha256(source).hexdigest(),
                  'exit_code': None, 'outputs': {}, 'error_code': '', 'stderr_tail': '', 'artifacts': [],
                  'unit': 'portal-script-' + identifier, 'admission': admission, 'notified': False,
                  'authorization': config['authorization']}
        state['runs'][identifier] = record
        # Commit admission before the external launch; crash recovery marks an
        # abandoned admission lost, never starts it twice.
    try:
        launch(record, config)
    except Exception as error:
        with store.transaction() as state:
            state['runs'][identifier].update(status='failed', finished_at=now(), error_code='script.launch_failed', stderr_tail=str(error))
        raise
    return _receipt(record)

