def runtime_catalog(client: Any, account_id: str) -> dict[str, Any]:
    with _lock:
        account_lock = _account_locks.setdefault(account_id, threading.Lock())
    with account_lock:
        cached = _cache.get(account_id)
        if cached and time.monotonic() - cached[0] < 60:
            return copy.deepcopy(cached[1])
        models = []
        cursor = None
        for _ in range(20):
            result = client.request("model/list", {"limit": 100, "cursor": cursor}, timeout=10)
            models.extend(model for model in result.get("data", []) if not model.get("hidden"))
            next_cursor = result.get("nextCursor")
            if not next_cursor:
                break
            if next_cursor == cursor:
                raise ValueError("Provider model catalog repeated a cursor")
            cursor = next_cursor
        else:
            raise ValueError("Provider model catalog exceeds the page limit")
        if not models:
            raise ValueError("Provider returned no available models")
        defaults = next((model for model in models if model.get("isDefault")), models[0])
        value = {
            "source": "model/list", "account_id": account_id,
            "models": [model["model"] for model in models],
            "default_model": defaults["model"], "default_reasoning_effort": defaults.get("defaultReasoningEffort", ""),
            "efforts_by_model": {model["model"]: [option["reasoningEffort"] for option in model.get("supportedReasoningEfforts", [])] for model in models},
            "default_efforts_by_model": {model["model"]: model.get("defaultReasoningEffort", "") for model in models},
            "service_tiers_by_model": {model["model"]: model.get("serviceTiers", []) for model in models},
            "input_modalities_by_model": {model["model"]: model.get("inputModalities", []) for model in models},
        }
        _cache[account_id] = (time.monotonic(), value)
        return copy.deepcopy(value)

def list_provider_accounts(inv: Invocation) -> dict[str, Any]:
    snapshot = _accounts_snapshot(bool(inv.argument("refresh")))
    accounts = [item for item in snapshot.get("accounts") or [] if isinstance(item, dict)]
    account_id = inv.argument("account_id")
    if account_id:
        accounts = [item for item in accounts if str(item.get("account_id") or item.get("id") or "") == account_id]
        if not accounts:
            raise not_found(f"执行账号不存在：{account_id}")
    from .accounts import default_execution_accounts

    catalog = default_execution_accounts(tolerate_unavailable=True)
    default_routes = {provider: catalog.resolve(provider).route_id
                      for provider, adapter in catalog.adapters.items() if adapter.accounts()}
    return {"accounts": accounts, "default_routes": default_routes}

def agent_backends(self, request, parsed, actor):
    return self._runtime_catalog(request, parsed, include_backends=True)

def runtime_catalog(self, request, parsed, actor):
    return self._runtime_catalog(request, parsed, include_backends=False)

def _runtime_catalog(self, request, parsed, *, include_backends):
    try:
        query = parse_qs(parsed.query)
        resident_id = str((query.get("resident_id") or [""])[0])
        runtime_route = self.resident_api().get_resident_runtime_route(
            resident_id, self.session_actor(request) or ""
        ) if resident_id else {}
        catalog = self.execution_api().runtime_catalog(
            account_id=str(runtime_route.get("account_id") or (query.get("account_id") or [""])[0]),
            backend=str(runtime_route.get("backend") or (query.get("backend") or [""])[0]),
            include_backends=include_backends,
        )
        return self.respond(request, 200, catalog)
    except Exception as exc:
        return self.error(request, exc)

def _resolve_codex_runtime_configuration(
    settings: object,
    catalog: dict[str, Any],
    *,
    explicit_fields: object = (),
) -> dict[str, Any]:
    """Resolve one account/model/effort/speed tuple against one Provider catalog."""

    requested = normalize_settings(settings)
    resolved = effective_codex_runtime_settings(requested)
    explicit = {
        str(field)
        for field in (explicit_fields or ())
        if str(field) in CODEX_PROVIDER_CONFIGURATION_FIELDS and requested.get(str(field))
    }
    models = [
        str(model).strip()
        for model in catalog.get("models", [])
        if str(model).strip()
    ]
    if not models:
        raise ValueError("当前账号的 Provider 目录没有可用模型")

    requested_model = str(resolved.get("model") or "").strip()
    if requested_model not in models:
        if "model" in explicit:
            raise ValueError(
                f"当前账号的 Provider 目录未列出 {requested_model}"
            )
        provider_default = str(catalog.get("default_model") or "").strip()
        requested_model = provider_default if provider_default in models else models[0]
    resolved["model"] = requested_model

    efforts_by_model = catalog.get("efforts_by_model") or {}
    efforts = [
        str(effort).strip().lower()
        for effort in efforts_by_model.get(requested_model, [])
        if str(effort).strip()
    ]
    requested_effort = str(
        resolved.get("reasoning_effort") or ""
    ).strip().lower()
    if efforts and requested_effort not in efforts:
        if "reasoning_effort" in explicit:
            raise ValueError(
                f"{requested_model} 不支持 reasoning effort "
                f"{requested_effort}；可选：{' / '.join(efforts)}"
            )
        model_default = str(
            (catalog.get("default_efforts_by_model") or {}).get(
                requested_model
            )
            or (
                catalog.get("default_reasoning_effort")
                if requested_model == str(catalog.get("default_model") or "")
                else ""
            )
            or ""
        ).strip().lower()
        requested_effort = (
            model_default if model_default in efforts else efforts[0]
        )
    elif not efforts:
        if "reasoning_effort" in explicit and requested_effort:
            raise ValueError(
                f"{requested_model} 未声明可用 reasoning effort"
            )
        requested_effort = ""
    resolved["reasoning_effort"] = requested_effort

    requested_tier = _clean_service_tier(resolved.get("service_tier"))
    tier_ids = _catalog_service_tier_ids(catalog, requested_model)
    if requested_tier and requested_tier not in tier_ids:
        if "service_tier" in explicit:
            available = " / ".join(tier_ids) or "1x"
            raise ValueError(
                f"{requested_model} 不支持 speed {requested_tier}；可选：{available}"
            )
        requested_tier = ""
    resolved["service_tier"] = requested_tier
    return resolved

def validate_codex_runtime_updates(
    current: object, updates: dict[str, Any], *, account_id: str = "",
) -> dict[str, Any]:
    checked = dict(updates)
    candidate = merge_settings(current, checked)
    before = effective_codex_runtime_settings(current)
    resolved = resolve_codex_runtime_configuration(
        candidate,
        account_id=account_id,
        explicit_fields=set(checked) & set(CODEX_PROVIDER_CONFIGURATION_FIELDS),
    )
    reconciled = any(
        resolved[field] != before[field]
        for field in CODEX_PROVIDER_CONFIGURATION_FIELDS
    )
    for field in CODEX_PROVIDER_CONFIGURATION_FIELDS:
        if field in checked or reconciled:
            checked[field] = resolved[field]
    return checked

