def family_credentials(store, connection, principal_id):
    """Yield real peer credentials with their read-only sharing provenance.

    Sharing never recurses through a peer's other Families or its represented
    personal AMA owner; only the formal peers' own stored credentials count.
    """
    if not principal_id.startswith('resident_'):
        return
    for peer, family_ids in sorted(store.family_peers(principal_id).items()):
        if peer == principal_id or not peer.startswith('resident_'):
            continue
        principal = store.object(connection, 'principal', peer)
        if not principal or not principal.get('active'):
            continue
        provenance = {'family_shared': True, 'source_principal_id': peer, 'family_ids': list(family_ids)}
        for credential in store.credential_sets.read(connection, peer, principal.get('credential_revision', '')):
            yield credential, provenance


def permission_roots(store, connection, principal_id, resources, *, represent=True) -> list[PermissionRoot]:
    principal = store.object(connection, 'principal', principal_id)
    if not principal or not principal.get('active'):
        return []
    roots = credential_roots(store.credential_sets.read(connection, principal_id, principal.get('credential_revision', '')), resources)
    if represent:
        for owner in store.represented(principal_id):
            roots.extend(permission_roots(store, connection, owner, resources, represent=False))
        for credential, provenance in family_credentials(store, connection, principal_id):
            resource = resources.get(credential.get('resource_id'))
            if credential_valid(credential, resource):
                root = credential_root(credential, resource)
                roots.append(replace(root, source={**root.source, **provenance}))
    return roots


