class Level(IntEnum):
    none = 0
    viewer = 1
    contributor = 2
    admin = 3

    @classmethod
    def parse(cls, value: object) -> "Level":
        if isinstance(value, cls):
            return value
        if isinstance(value, str) and value in cls.__members__:
            return cls[value]
        if type(value) is int and value in range(4):
            return cls(value)
        raise ValueError("Permission level must be none, viewer, contributor or admin")

