def tool_result_text(item: AgentLoopToolResult) -> str:
    """Return a lossless text view only for plain successful tool results."""

    result = item.result if isinstance(item.result, dict) else {}
    if result.get("success") is not True:
        return ""
    content_items = result.get("contentItems")
    if not isinstance(content_items, list) or not content_items:
        return ""
    texts: list[str] = []
    for content_item in content_items:
        if (
            not isinstance(content_item, dict)
            or content_item.get("type") != "inputText"
            or not isinstance(content_item.get("text"), str)
        ):
            return ""
        texts.append(content_item["text"])
    return "\n".join(texts)


def replace_tool_result_text(
    item: AgentLoopToolResult,
    replacement: str,
) -> AgentLoopToolResult:
    """Replace an eligible plain-text result while preserving its envelope."""

    result = deepcopy(item.result)
    result["contentItems"] = [{
        "type": "inputText",
        "text": str(replacement or ""),
    }]
    return AgentLoopToolResult(
        call_id=item.call_id,
        tool_name=item.tool_name,
        arguments=dict(item.arguments),
        result=result,
        source=item.source,
    )


def utf8_bytes(value: object) -> int:
    return len(str(value or "").encode("utf-8"))


def numeric_delta(before: object, after: object) -> int:
    return max(0, utf8_bytes(before) - utf8_bytes(after))

def _program_operator_barriers(
    lineage: dict[str, Any],
    event_source_id: str,
    *, route_ids: Iterable[str] = (),
) -> list[dict[str, Any]]:
    """Freeze reachable operator inputs for this occurrence's active routes.

    Traverse operator branches, including branches that may emit no packets.
    Stop at Resident boundaries: their replies start independent occurrences.
    """

    plan = _compiled_program(lineage)
    wires_by_id = {
        str(wire.get("id") or ""): wire
        for wire in plan.get("wires") or []
        if isinstance(wire, dict)
    }
    operators = plan.get("packet_operators") or {}
    grouped: dict[str, set[str]] = {}
    frontier = [wires_by_id[wire_id] for wire_id in route_ids if wire_id in wires_by_id]
    expanded_operator_ids: set[str] = set()
    while frontier:
        wire = frontier.pop(0)
        operator_id = str(wire.get("target") or "")
        wire_id = str(wire.get("id") or "")
        if operator_id not in operators or not wire_id:
            continue
        grouped.setdefault(operator_id, set()).add(wire_id)
        if operator_id in expanded_operator_ids:
            continue
        expanded_operator_ids.add(operator_id)
        operator = operators.get(operator_id) or {}
        frontier.extend(
            wires_by_id[wire_id]
            for wire_id in operator.get("outgoing_packet_wire_ids") or []
            if wire_id in wires_by_id
        )
    return [
        {
            "event_source_id": event_source_id,
            "operator_id": operator_id,
            "expected_packet_wire_ids": sorted(packet_wire_ids),
        }
        for operator_id, packet_wire_ids in sorted(grouped.items())
    ]


