def evaluate_rules(
    kind: str, config: dict[str, Any], inputs: list[dict[str, Any]]
) -> OperatorOutput:
    if kind == "filter":
        return OperatorOutput(lineage_operators.rule_filter_result(config, inputs))
    if kind == "selector":
        return OperatorOutput([], lineage_operators.rule_selector_result(config, inputs))
    if not inputs:
        return OperatorOutput([])
    return OperatorOutput([lineage_operators.rule_reducer_result(config, inputs).to_dict()])

def conversation_state(
    job: Mapping[str, object] | None,
    *,
    intake_state: str,
    snapshot: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    active_job = dict(job or {})
    queue = normalized_queue(active_job)
    waiting_queue = public_waiting_queue(active_job)
    execution_state = (
        public_execution_state(active_job, snapshot=snapshot)
        if isinstance(snapshot, Mapping) and active_job
        else {}
    )
    # Provider completion precedes Resident result delivery. Only the durable
    # Resident job may end the public lifecycle, after its reply/error is saved.
    if (
        not active_job
        or not is_active(active_job)
        or completion_applied(active_job)
    ):
        return {
            "work_state": "queued" if waiting_queue else "idle",
            "active_message_id": "",
            "queued_count": len(waiting_queue),
            "intake_state": resident_state.normalize_intake_state(intake_state),
        }
    if is_execution_held(active_job):
        return {
            "work_state": "queued",
            "active_message_id": "",
            "queued_count": len(waiting_queue),
            "intake_state": resident_state.normalize_intake_state(intake_state),
        }
    elif not submitted_execution_id(active_job):
        execution_state = {"status": "submitting", "queue_reason": ""}
    elif not execution_state:
        # A binding is a submission receipt, not evidence that a worker began.
        execution_state = {"status": "submitting", "queue_reason": ""}
    status = str(execution_state.get("status") or "").lower()
    state = {
        "work_state": (
            "stopping"
            if (
                bool(str(active_job.get("stop_requested_at") or "").strip())
                or bool(execution_state.get("cancel_requested"))
            )
            else
            "queued"
            if status in {"held", "submitting", "queued"}
            else "running"
        ),
        "active_message_id": str(active_job.get("user_message_id") or ""),
        "queued_count": len(queue),
        "intake_state": resident_state.normalize_intake_state(intake_state),

def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.command == "status":
            selected = args.instance or "all"
            result = status(selected, include_schema=args.schema)
        elif args.command == "request-restart":
            result = request_restart(
                args.instance,
                components=args.component,
            )
        else:
            with operation_lock(_operation_lock_path(args.instance)):
                if args.command == "start":
                    result = start(args.instance)
                elif args.command == "stop":
                    result = stop(
                        args.instance,
                        drain=args.drain,
                        drain_timeout=args.drain_timeout,
                        force=args.force,
                    )
                elif args.command == "restart":
                    result = restart(
                        args.instance,
                        notice_seconds=args.notice,
                        components=args.component,
                        force_worker_restart=(
                            not args.generation_only
                            and "execution-worker" in (args.component or [])
                        ),
                    )
    except Exception as exc:
        print(
            json.dumps({"ok": False, "error": str(exc)}, ensure_ascii=False),
            file=sys.stderr,
        )
        return 1
    print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))

@contextmanager
def exclusive(key: str, *, stop: Callable[[], bool], poll_seconds: float = 1.0):
    """Serialize a shared test identity without consuming a global test slot."""
    root = slot_root()
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    name = hashlib.sha256(key.encode()).hexdigest()
    descriptor = os.open(root / f"exclusive-{name}.lock", os.O_RDWR | os.O_CREAT | os.O_CLOEXEC, 0o600)
    try:
        while True:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if stop():
                    yield False
                    return
                time.sleep(poll_seconds)
        yield True
    finally:
        os.close(descriptor)


class SlotLease:
    def __init__(self, kind: str, descriptors: list[int]):
        self.kind = kind
        self._descriptors = descriptors

    @property
    def count(self) -> int:
        return len(self._descriptors) // 2

    def release(self) -> None:
        descriptors, self._descriptors = self._descriptors, []
        for descriptor in descriptors:
            os.close(descriptor)

def _execute_group_in_slot(
    self, run_id: str, group_spec: dict[str, Any], selected: list[dict[str, Any]],
    run_dir: Path, actor: str,
) -> tuple[str, str]:
    lease = slots.acquire("tau", 1, stop=lambda: self._is_cancelled(run_id))
    if lease is None:
        # The normal path still withdraws a resumed invocation and runs cleanup.
        return self._execute_group(run_id, group_spec, selected, run_dir, actor)
    try:
        return self._execute_group(run_id, group_spec, selected, run_dir, actor)
    finally:
        lease.release()

    now = execution_timestamp()
    changed = connection.execute(
        "\n                UPDATE executions\n                SET status = 'claimed', owner_worker_id = %s, claim_token = %s,\n                    lease_expires_at = %s, available_at = 'epoch'::timestamptz,\n                    attempts = attempts + 1, updated_at = %s\n                WHERE execution_id = %s AND status = 'queued'\n                ",
        (worker_id, token, instant(now_epoch + duration), now, execution_id),
    )
    if changed.rowcount != 1:
        raise PermissionError("execution claim ownership changed")
    if not interrupt_only:
        self._record_actor_dispatch(
            connection,
            actor=str(candidate["actor"]),
            priority=int(candidate["priority"]),
            now_epoch=now_epoch,
        )
    self._event(
        connection,
        execution_id,
        "claimed",
        {
            "worker_id": worker_id,
            "lease_seconds": duration,
            "capacity_key": capacity_key,
            "dispatch_interval_seconds": dispatch_state[
                "interval_seconds"
            ],
            "next_dispatch_at": dispatch_state[
                "next_dispatch_at"
            ],
        },
    )
    row = connection.execute(
        'SELECT * FROM executions WHERE execution_id = %s',
        (execution_id,),
    ).fetchone()
    connection.commit()
return {
    "claimed": True,
    "claim_token": token,
    "execution": self._row_payload(row),
}

def execute_claim(
    self,
    claim: dict[str, Any],
    *,
    lease_seconds: int = 90,
) -> dict[str, Any]:
    execution = (
        claim.get("execution")
        if isinstance(claim.get("execution"), dict)
        else {}
    )
    execution_id = str(execution.get("execution_id") or "")
    claim_token = str(claim.get("claim_token") or "")
    recovery_checkpoint = (
        dict(execution.get("checkpoint"))
        if isinstance(execution.get("checkpoint"), dict)
        else {}
    )
    if not execution_id or not claim_token:
        raise ValueError("claimed execution identity is incomplete")

    cancelled = threading.Event()
    heartbeat_stop = threading.Event()
    ownership_lost = threading.Event()
    planned_handover = threading.Event()
    turn_controls: queue.Queue[dict[str, Any]] = queue.Queue()
    seen_turn_controls: set[str] = set()
    turn_control_lock = threading.Lock()
    receipt_lock = threading.Lock()
    self.scheduler.start(execution_id, claim_token)
    queue_wait_ms = _elapsed_since_iso_ms(str(execution.get("created_at") or ""))

    def cancellation_requested() -> bool:
